export const PFM: PfMat[] = [
	{"id": "ku-kesadaran", "g": "umum", "name": "Keadaan umum & kesadaran", "sk": [639, 642, 87, 595], "goal": "Menilai kesan sakit, kesadaran kualitatif, dan tanda bahaya sejak pertama melihat pasien.", "tools": ["Senter", "Jam tangan"], "prep": [], "steps": [["Amati dari ujung tempat tidur", "Tampak sakit ringan/sedang/berat; gelisah, sesak, kesakitan, pucat, ikterik, sianosis; posisi (ortopnea, meringkuk, opistotonus); alat yang terpasang (oksigen, infus, kateter)."], ["Nilai kesadaran kualitatif", "Kompos mentis (sadar penuh, menjawab baik), apatis (acuh), delirium (gelisah, disorientasi), somnolen (mengantuk, bangun dengan rangsang suara), sopor/stupor (bangun dengan rangsang nyeri kuat), koma (tidak ada respons)."], ["Skala cepat AVPU", "Alert, responds to Voice, responds to Pain, Unresponsive. P atau U setara GCS ≤ 8."], ["Lanjutkan GCS bila kesadaran menurun", "Lihat materi GCS; catat E-V-M terpisah."], ["Perhatikan bau, habitus & bicara", "Bau aseton, uremik, alkohol, fetor hepatikus; kurus/obes; bicara pelo/afasia."]], "normal": ["Tampak sakit ringan, kompos mentis, GCS E4V5M6 = 15, kooperatif."], "abn": [["Gelisah + kebingungan akut", "Delirium: cari hipoksia, hipoglikemia, sepsis, obat, gangguan elektrolit"], ["Posisi tripod/ortopnea", "Gagal napas/gagal jantung kiri"], ["Meringkuk diam tidak mau bergerak", "Peritonitis"], ["Gelisah berguling-guling", "Kolik (batu ureter/bilier)"], ["Bau aseton (buah)", "Ketoasidosis diabetik/kelaparan"], ["AVPU P atau U", "Amankan jalan napas, ABCDE, rujuk segera"]], "doc": "KU: tampak sakit sedang, kompos mentis (GCS E4V5M6), kooperatif.", "key": ["Kesan umum dinilai sebelum menyentuh pasien", "Sebutkan kesadaran kualitatif dan kuantitatif"], "tips": ["Kesadaran dinilai sebelum diberi sedasi/analgesik kuat", "Catat perubahan kesadaran dengan jam"], "dz": ["delirium", "syok", "sepsis"]},
	{"id": "gcs", "g": "umum", "name": "Glasgow Coma Scale (GCS)", "sk": [41], "goal": "Menilai tingkat kesadaran secara kuantitatif dan memantau perubahannya.", "tools": [], "prep": [], "steps": [["Eye (E)", "4 = membuka spontan; 3 = dengan perintah/suara; 2 = dengan rangsang nyeri; 1 = tidak membuka. Catat \"C\" bila mata tertutup bengkak."], ["Verbal (V)", "5 = orientasi baik (orang, tempat, waktu); 4 = bingung; 3 = kata-kata tidak tepat; 2 = suara tidak bermakna (mengerang); 1 = tidak ada. Catat \"T\" bila terintubasi, \"A\" bila afasia."], ["Motor (M)", "6 = mengikuti perintah; 5 = melokalisasi nyeri; 4 = menarik (fleksi normal); 3 = fleksi abnormal (dekortikasi); 2 = ekstensi (deserebrasi); 1 = tidak ada."], ["Beri rangsang nyeri yang benar", "Mulai dengan suara → sentuhan → tekanan kuku jari (perifer) lalu sentral (tekanan supraorbita atau trapezius) selama ≤ 10 detik. Hindari menggosok sternum berulang."], ["Hitung & laporkan per komponen", "Laporkan \"E3V4M6 = 13\", bukan hanya totalnya. Respons motorik terbaik dari sisi mana pun yang dipakai."], ["Versi anak (< 2 tahun)", "V: 5 = tersenyum/mengoceh, 4 = menangis tetapi bisa ditenangkan, 3 = menangis terus/rewel, 2 = gelisah/merintih, 1 = tidak ada."]], "normal": ["E4V5M6 = 15"], "abn": [["GCS 13–15", "Cedera kepala ringan"], ["GCS 9–12", "Cedera kepala sedang"], ["GCS ≤ 8", "Berat/koma: lindungi jalan napas, intubasi/rujuk segera"], ["Penurunan GCS ≥ 2 poin", "Perburukan (perdarahan intrakranial, herniasi) — evaluasi ulang segera"], ["Postur dekortikasi (M3)", "Lesi di atas nukleus rubra (hemisfer/kapsula interna)"], ["Postur deserebrasi (M2)", "Lesi batang otak (mesensefalon/pons), prognosis buruk"]], "doc": "Kesadaran: GCS E4V5M6 = 15, pupil isokor 3 mm/3 mm, RC +/+.", "key": ["Urutan rangsang benar (suara → nyeri perifer → sentral)", "Laporkan E, V, M terpisah", "Sertakan pemeriksaan pupil"], "tips": ["Pada pasien terintubasi tulis V = T (mis. E3VTM5)", "Ulangi tiap 15–30 menit pada cedera kepala sedang-berat"], "dz": ["hematoma-epidural", "stroke-iskemik", "koma"]},
	{"id": "tanda-vital", "g": "umum", "name": "Tanda vital lengkap (nadi, napas, suhu, nyeri)", "sk": [605, 641, 283, 233], "goal": "Mengukur nadi, frekuensi napas, suhu, dan skala nyeri secara benar sebagai data dasar dan pemantauan.", "tools": ["Jam dengan jarum detik", "Termometer digital/timpani", "Kartu skala nyeri"], "prep": [], "steps": [["Nadi radialis", "Raba dengan 2–3 jari di sisi radial pergelangan; hitung 30 detik ×2 bila teratur, 60 detik penuh bila tidak teratur. Nilai frekuensi, irama, isi (kuat/lemah), dan kesamaan kanan-kiri."], ["Karakter nadi", "Nilai pada a. karotis atau brakialis: normal, lambat naik (stenosis aorta), kolaps/water-hammer (regurgitasi aorta), alternans (gagal jantung berat)."], ["Frekuensi napas", "Hitung selama 60 detik sambil tetap memegang pergelangan (pasien tidak sadar sedang dihitung). Amati kedalaman, irama, dan otot bantu napas."], ["Suhu", "Pilih lokasi (aksila 5 menit/termometer digital sampai bunyi, timpani dengan telinga ditarik ke atas-belakang, oral di bawah lidah, rektal untuk bayi). Catat metode."], ["Skala nyeri", "NRS 0–10 untuk dewasa; Wong-Baker (wajah) untuk anak ≥ 3 tahun; FLACC untuk bayi/pasien nonverbal."], ["Hitung defisit nadi bila irama tidak teratur", "Hitung apikal (auskultasi) dan radial bersamaan; selisih > 10 menunjukkan fibrilasi atrium."]], "normal": ["Nadi 60–100 x/menit reguler isi cukup", "RR 12–20 x/menit (dewasa)", "suhu aksila 36,0–37,4 °C", "nyeri 0/10."], "abn": [["Nadi > 100 x/menit", "Takikardia: demam, nyeri, hipovolemia, anemia, hipertiroid, aritmia"], ["Nadi < 60 x/menit", "Bradikardia: atlet, beta-bloker, blok AV, hipotiroid, peningkatan TIK (refleks Cushing)"], ["Ireguler-ireguler + defisit nadi", "Fibrilasi atrium"], ["RR > 20 x/menit (dewasa)", "Takipnea: pneumonia, asidosis, sepsis, emboli paru, ansietas"], ["Pernapasan Kussmaul (dalam, cepat)", "Asidosis metabolik (KAD, uremia)"], ["Pernapasan Cheyne-Stokes", "Gagal jantung berat, lesi otak bilateral, mendekati ajal"], ["Suhu aksila ≥ 37,5 °C", "Demam; ≥ 40 °C hiperpireksia"], ["Suhu < 35 °C", "Hipotermia: sepsis berat, paparan dingin, hipotiroid"]], "doc": "N 88 x/menit reguler, isi cukup; RR 18 x/menit; T 36,8 °C (aksila); nyeri NRS 2/10.", "key": ["Hitung napas tanpa memberitahu pasien", "Hitung nadi 60 detik bila ireguler", "Sebutkan lokasi suhu"], "tips": ["Nilai normal anak berbeda per usia — lihat tabel tanda vital anak", "Nadi + RR + suhu + TD + kesadaran dipakai untuk skor qSOFA/NEWS"], "dz": ["tifoid", "sepsis", "pneumonia"]},
	{"id": "tekanan-darah", "g": "kardio", "name": "Pengukuran tekanan darah", "sk": [281], "goal": "Mengukur tekanan darah arteri secara akurat dengan sfigmomanometer (auskultasi) dan menilai hipotensi ortostatik.", "tools": ["Sfigmomanometer air raksa/aneroid terkalibrasi", "Manset sesuai ukuran (balon menutupi ≥ 80% lingkar lengan)", "Stetoskop"], "prep": ["Pasien istirahat duduk ≥ 5 menit, tidak merokok/kopi 30 menit sebelumnya, kandung kemih kosong", "Lengan bebas pakaian, disangga setinggi jantung, kaki menapak tidak menyilang"], "steps": [["Pasang manset", "Tepi bawah 2–3 cm di atas fossa cubiti, tanda arteri di atas a. brakialis, kencang selebar satu jari."], ["Tentukan sistolik palpasi", "Raba a. radialis, pompa sampai nadi hilang, catat angka, kempiskan. Tekanan target pompa = angka ini + 20–30 mmHg (mencegah auscultatory gap)."], ["Auskultasi", "Letakkan diafragma/bel stetoskop di a. brakialis (jangan di bawah manset), pompa ke target, turunkan 2–3 mmHg per detik."], ["Baca hasil", "Korotkoff I (bunyi pertama) = sistolik; Korotkoff V (bunyi hilang) = diastolik. Bila bunyi terdengar sampai 0, pakai fase IV (meredam)."], ["Ulangi & bandingkan", "Ukur 2 kali selang 1–2 menit, ambil rerata. Kunjungan pertama ukur kedua lengan; pakai lengan dengan nilai lebih tinggi selanjutnya."], ["Ortostatik bila ada indikasi", "Ukur setelah berbaring 5 menit, lalu berdiri 1 dan 3 menit."]], "normal": ["< 120/80 mmHg optimal", "120–139/80–89 normal-tinggi (JNC/ESH berbeda istilah)."], "abn": [["≥ 140/90 mmHg (≥ 2 kali kunjungan)", "Hipertensi; ≥ 180/110 mmHg hipertensi berat — cari kerusakan organ target"], ["Sistolik < 90 mmHg atau MAP < 65", "Hipotensi/syok"], ["Turun sistolik ≥ 20 atau diastolik ≥ 10 saat berdiri", "Hipotensi ortostatik (hipovolemia, obat, neuropati otonom)"], ["Selisih sistolik antarlengan > 15 mmHg", "Stenosis a. subklavia, diseksi aorta, koarktasio"], ["Tekanan nadi lebar (> 60 mmHg)", "Regurgitasi aorta, hipertiroid, lansia (arteri kaku)"], ["Tekanan nadi sempit (< 25 mmHg)", "Syok, tamponade, stenosis aorta berat"], ["Pulsus paradoksus > 10 mmHg", "Tamponade jantung, asma berat"]], "doc": "TD 120/80 mmHg (lengan kanan, duduk). Ortostatik: tidak ada penurunan bermakna.", "key": ["Palpasi sistolik dulu sebelum auskultasi", "Manset sesuai ukuran dan setinggi jantung", "Kecepatan turun 2–3 mmHg/detik"], "tips": ["Manset terlalu kecil memberi hasil terlalu tinggi", "Pada anak gunakan tabel persentil TD menurut usia, jenis kelamin, dan tinggi badan"], "dz": ["hipertensi", "syok"]},
	{"id": "oksimetri", "g": "kardio", "name": "Pulse oximetry (SpO₂)", "sk": [304], "goal": "Mengukur saturasi oksigen perifer secara noninvasif dan memantau terapi oksigen.", "tools": ["Oksimeter pulsasi"], "prep": [], "steps": [["Pilih lokasi", "Jari tangan hangat tanpa kuteks/kuku palsu; alternatif daun telinga atau jari kaki (bayi: telapak kaki/tangan)."], ["Pasang & tunggu", "Tunggu gelombang pletismografi stabil dan nadi di layar sesuai nadi palpasi (≥ 30–60 detik)."], ["Catat dengan FiO₂", "Tulis \"SpO₂ 95% udara ruang\" atau \"SpO₂ 98% dengan O₂ nasal 3 L/menit\"."], ["Kenali sumber kesalahan", "Perfusi buruk/ekstremitas dingin, gerakan, cahaya terang, kuteks, keracunan CO (nilai palsu tinggi), methemoglobinemia (menetap ~85%), kulit gelap (dapat sedikit terlalu tinggi)."]], "normal": ["SpO₂ 95–100% udara ruang (target 88–92% pada PPOK dengan retensi CO₂)."], "abn": [["SpO₂ < 94%", "Hipoksemia: berikan oksigen, cari penyebab"], ["SpO₂ < 90%", "Hipoksemia berat — tata laksana segera, pertimbangkan rujuk"], ["SpO₂ normal tetapi pasien sesak berat", "Curigai keracunan CO, anemia berat, asidosis, atau sinyal palsu"]], "doc": "SpO₂ 97% udara ruang.", "key": ["Konfirmasi nadi oksimeter sama dengan nadi palpasi", "Sebutkan FiO₂"], "tips": ["Oksimeter tidak menilai ventilasi (CO₂) — pasien bisa hiperkapnia dengan SpO₂ normal bila diberi oksigen"], "dz": ["pneumonia", "asma", "ppok"]},
	{"id": "antropometri-gizi", "g": "umum", "name": "Antropometri dewasa & status gizi", "sk": [486, 640], "goal": "Mengukur BB, TB, IMT, lingkar perut, dan menilai status gizi serta habitus.", "tools": ["Timbangan terkalibrasi", "Mikrotoa/stadiometer", "Pita ukur (metlin)", "Kalkulator"], "prep": [], "steps": [["Berat badan", "Pakaian minimal, tanpa alas kaki, timbangan di permukaan datar, baca sampai 0,1 kg."], ["Tinggi badan", "Berdiri tegak membelakangi dinding; tumit, bokong, bahu, kepala menempel; pandangan lurus (garis Frankfurt horizontal)."], ["Hitung IMT", "IMT = BB (kg) / TB² (m). Kriteria Asia-Pasifik: < 18,5 kurang; 18,5–22,9 normal; 23–24,9 berisiko (overweight); 25–29,9 obes I; ≥ 30 obes II."], ["Lingkar perut", "Pertengahan antara tepi bawah iga dan krista iliaka, akhir ekspirasi normal, pita horizontal. Obesitas sentral Asia: ≥ 90 cm (pria), ≥ 80 cm (wanita)."], ["Bila tidak bisa berdiri", "Perkiraan TB dari tinggi lutut atau rentang lengan; LiLA (lingkar lengan atas) < 23,5 cm pada wanita usia subur = KEK."], ["Penilaian klinis gizi", "Wasting otot temporal/interoseus, edema, rambut mudah rontok, glositis, keilitis, kuku sendok."], ["Habitus", "Atletikus, piknikus, astenikus; postur dan proporsi tubuh."]], "normal": ["IMT 18,5–22,9 kg/m²", "lingkar perut < 90/80 cm."], "abn": [["IMT < 18,5 kg/m²", "Gizi kurang: cari TB, keganasan, DM tak terkontrol, hipertiroid, gangguan makan"], ["IMT ≥ 25 kg/m² (Asia)", "Obesitas — skrining DM, hipertensi, dislipidemia, OSA"], ["Obesitas sentral", "Risiko sindrom metabolik"], ["LiLA < 23,5 cm pada ibu hamil", "Kurang energi kronik (KEK)"], ["Penurunan BB > 5% dalam 1 bulan / > 10% dalam 6 bulan tanpa disengaja", "Penurunan BB bermakna — cari penyebab organik"]], "doc": "BB 60 kg, TB 165 cm, IMT 22,0 kg/m² (normal), LP 82 cm. Habitus atletikus.", "key": ["Rumus IMT benar", "Titik ukur lingkar perut benar", "Pakai kriteria Asia-Pasifik"], "tips": ["IMT tidak membedakan otot dan lemak", "Untuk anak gunakan kurva WHO/CDC (lihat Antropometri anak)"], "dz": ["obesitas", "malnutrisi"]},
	{"id": "dehidrasi", "g": "umum", "name": "Penilaian dehidrasi, turgor & capillary refill", "sk": [684, 285, 284], "goal": "Menilai derajat dehidrasi dan perfusi perifer, terutama pada diare anak dan syok.", "tools": ["Jam dengan detik"], "prep": [], "steps": [["Keadaan umum & mata", "Gelisah/rewel atau letargis; mata cekung; air mata ada atau tidak (bayi)."], ["Mukosa & haus", "Bibir/lidah kering; anak minum dengan lahap (haus) atau malas/tidak bisa minum."], ["Turgor kulit", "Cubit kulit perut (anak) atau dada/sternum (lansia) setinggi umbilikus/garis midklavikula selama 1 detik, lepaskan. Kembali segera (normal), lambat (< 2 detik), atau sangat lambat (≥ 2 detik)."], ["Capillary refill time (CRT)", "Tekan kuku atau ujung jari setinggi jantung selama 5 detik sampai pucat, lepas, hitung waktu warna kembali. Normal ≤ 2 detik."], ["Denyut kapiler (Quincke)", "Tekan lembut ujung kuku hingga separuh bantalan pucat; pulsasi kemerahan-pucat sesuai denyut menunjukkan regurgitasi aorta/hiperdinamik."], ["Klasifikasi WHO/MTBS", "Tanpa dehidrasi; dehidrasi ringan-sedang (≥ 2 tanda: gelisah, mata cekung, haus, turgor lambat); dehidrasi berat (≥ 2 tanda: letargis/tidak sadar, mata cekung, tidak bisa minum, turgor sangat lambat)."]], "normal": ["Sadar, mata tidak cekung, mukosa basah, turgor kembali segera, CRT ≤ 2 detik, akral hangat."], "abn": [["2 tanda dehidrasi ringan-sedang", "Rencana terapi B: oralit 75 mL/kg dalam 3 jam"], ["2 tanda dehidrasi berat", "Rencana terapi C: cairan IV RL 100 mL/kg"], ["CRT > 2 detik + akral dingin", "Gangguan perfusi/syok"], ["Turgor lambat pada lansia", "Kurang spesifik (elastisitas kulit menurun) — nilai di sternum/dahi"], ["Pulsasi kapiler Quincke", "Regurgitasi aorta, hipertiroid, demam tinggi"]], "doc": "KU sadar, mata tidak cekung, mukosa bibir basah, turgor kembali cepat, CRT < 2 detik, akral hangat. Kesan: tanpa dehidrasi.", "key": ["Turgor dicubit 1 detik di kulit perut", "CRT ditekan 5 detik", "Klasifikasi derajat dehidrasi"], "tips": ["Pada gizi buruk tanda dehidrasi sulit dinilai — jangan rehidrasi cepat", "Ruangan dingin memperpanjang CRT"], "dz": ["diare-akut", "syok"]},
	{"id": "kgb", "g": "umum", "name": "Palpasi kelenjar getah bening", "sk": [239, 240, 498, 227], "goal": "Menemukan dan mendeskripsikan pembesaran kelenjar getah bening (KGB) regional dan generalisata.", "tools": [], "prep": [], "steps": [["Leher dari belakang", "Pasien duduk, kepala sedikit menunduk ke sisi yang diperiksa. Raba berurutan dengan ujung jari gerakan memutar: submental → submandibula → preaurikular → postaurikular → oksipital → servikal anterior (sepanjang m. sternokleidomastoideus) → servikal posterior → supraklavikula."], ["Aksila", "Lengan pasien disangga; raba dinding sentral, anterior (pektoral), posterior (subskapular), lateral (humerus) dengan tangan berlawanan."], ["Epitroklear", "Siku fleksi 90°, raba di atas epikondilus medial."], ["Inguinal", "Horizontal (di bawah ligamentum inguinale) dan vertikal (sepanjang v. safena magna)."], ["Deskripsikan setiap KGB", "Lokasi, jumlah, ukuran (cm), konsistensi (lunak/kenyal/keras), nyeri tekan, mobilitas (mobile/terfiksir), konglomerasi, kulit di atasnya (merah, fistula)."], ["Periksa daerah drainase", "Cari sumber infeksi/keganasan di daerah yang dialirkan KGB tersebut; periksa juga hepar & lien bila generalisata."]], "normal": ["KGB tidak teraba atau teraba < 1 cm, kenyal, mobile, tidak nyeri (sering pada inguinal)."], "abn": [["Nyeri, lunak, kemerahan", "Limfadenitis reaktif/infeksi akut"], ["Keras, terfiksir, tidak nyeri", "Metastasis keganasan"], ["Kenyal seperti karet, multipel, tidak nyeri", "Limfoma"], ["Konglomerasi + fistula/skrofuloderma", "Limfadenitis TB"], ["KGB supraklavikula kiri (Virchow)", "Metastasis keganasan abdomen (gaster)"], ["Limfadenopati generalisata (≥ 2 regio tidak berdekatan)", "HIV, TB, limfoma, leukemia, infeksi virus (EBV), SLE"]], "doc": "KGB: tidak teraba pembesaran di regio servikal, aksila, inguinal.", "key": ["Urutan regio leher sistematis", "Deskripsi lengkap (lokasi, ukuran, konsistensi, nyeri, mobilitas)", "Periksa daerah drainase"], "tips": ["KGB > 2 cm, keras, atau supraklavikula perlu biopsi/rujuk", "Bandingkan kanan-kiri"], "dz": ["limfadenitis", "limfoma", "hiv-dewasa"]},
	{"id": "kelenjar-ludah", "g": "umum", "name": "Palpasi kelenjar ludah (parotis & submandibula)", "sk": [226], "goal": "Menilai pembesaran, nyeri, dan duktus kelenjar ludah mayor.", "tools": ["Senter", "Spatel lidah", "Sarung tangan"], "prep": [], "steps": [["Inspeksi", "Bengkak di depan telinga (parotis, mengangkat lobulus telinga) atau di bawah sudut mandibula (submandibula); asimetri, kemerahan."], ["Palpasi parotis", "Raba di depan tragus hingga sudut mandibula; nilai ukuran, konsistensi, nyeri."], ["Palpasi bimanual submandibula", "Satu jari bersarung tangan di dasar mulut, tangan lain di bawah mandibula; raba kelenjar dan batu di duktus Wharton."], ["Inspeksi muara duktus", "Duktus Stensen di mukosa pipi berhadapan gigi molar 2 atas; duktus Wharton di dasar mulut samping frenulum. Pijat kelenjar dan amati keluarnya ludah/pus."]], "normal": ["Kelenjar tidak membesar, tidak nyeri, muara duktus tenang, saliva jernih."], "abn": [["Parotis bengkak bilateral nyeri, demam", "Parotitis epidemika (mumps)"], ["Pus keluar dari duktus Stensen", "Parotitis bakterial (supuratif)"], ["Bengkak submandibula saat makan, teraba batu", "Sialolitiasis"], ["Massa parotis keras + paresis n. VII", "Keganasan parotis"]], "doc": "Kelenjar parotis & submandibula tidak membesar, tidak nyeri tekan; muara duktus tenang.", "key": ["Palpasi bimanual submandibula", "Inspeksi muara duktus Stensen dan Wharton"], "tips": [], "dz": ["parotitis"]},
	{"id": "pf-usia", "g": "umum", "name": "Pemeriksaan fisik umum sesuai usia", "sk": [593], "goal": "Menyesuaikan urutan, teknik, dan nilai normal pemeriksaan fisik dengan usia pasien (bayi, anak, dewasa, lansia).", "tools": [], "prep": [], "steps": [["Bayi & balita", "Periksa di pangkuan orang tua; mulai dari yang tidak mengganggu (inspeksi, hitung napas, auskultasi saat tenang) lalu yang tidak nyaman (telinga, tenggorok) di akhir. Ukur antropometri & lingkar kepala."], ["Anak usia sekolah", "Jelaskan dengan bahasa sederhana, tunjukkan alat; hormati privasi; nilai tumbuh kembang dan tanda vital sesuai usia."], ["Remaja", "Tawarkan wawancara tanpa orang tua (HEEADSSS), pendamping saat pemeriksaan sensitif, nilai Tanner."], ["Dewasa", "Pemeriksaan head-to-toe sistematis sesuai keluhan."], ["Lansia", "Nilai fungsi (ADL, jatuh, gait \"timed up and go\"), kognisi, penglihatan/pendengaran, hipotensi ortostatik, gizi, polifarmasi; turgor kurang andal."], ["Ibu hamil", "Hindari terlentang lama setelah 20 minggu (sindrom hipotensi supinasi) — miringkan ke kiri."]], "normal": ["Temuan sesuai nilai normal kelompok usia."], "abn": [["Nilai tanda vital dewasa dipakai pada anak", "Salah interpretasi — gunakan tabel tanda vital per usia"], ["Timed up and go > 12 detik pada lansia", "Risiko jatuh tinggi"]], "doc": "Pemeriksaan disesuaikan usia; tanda vital dalam batas normal untuk usia.", "key": ["Urutan ramah anak (yang tidak nyaman di akhir)", "Pendamping untuk pemeriksaan sensitif"], "tips": ["Frekuensi napas normal: < 2 bln < 60, 2–12 bln < 50, 1–5 th < 40 x/menit (MTBS)"], "dz": []},
	{"id": "rumple-leede", "g": "umum", "name": "Uji tourniquet (Rumple-Leede)", "sk": [618], "goal": "Menilai fragilitas kapiler, terutama untuk skrining demam berdarah dengue.", "tools": ["Sfigmomanometer", "Spidol/pulpen"], "prep": [], "steps": [["Ukur TD", "Tentukan sistolik dan diastolik, hitung tekanan rata-rata (S+D)/2."], ["Pompa manset", "Pertahankan pada tekanan rata-rata selama 5 menit (3 menit pada anak)."], ["Kempiskan & tunggu", "Lepas manset, tunggu 1–2 menit sampai warna kulit normal."], ["Hitung petekie", "Buat kotak 2,5 × 2,5 cm (1 inci persegi) di volar lengan bawah, hitung petekie di dalamnya."]], "normal": ["< 10 petekie per 2,5 cm² (negatif)."], "abn": [["≥ 10 petekie per 2,5 cm²", "Uji tourniquet positif: fragilitas kapiler (DBD, trombositopenia, vaskulitis)"], ["Petekie spontan tanpa uji", "Manifestasi perdarahan — cek trombosit segera"]], "doc": "Uji tourniquet: positif (15 petekie/2,5 cm²).", "key": ["Tekanan = rata-rata sistolik-diastolik", "Durasi 5 menit", "Hitung di kotak 2,5 cm"], "tips": ["Hasil negatif tidak menyingkirkan dengue", "Jangan dilakukan bila sudah ada perdarahan spontan/syok"], "dz": ["dengue", "itp"]},
	{"id": "n1-olfaktorius", "g": "saraf", "name": "N. I (olfaktorius): penghidu", "sk": [0, 190], "goal": "Menilai fungsi penghidu tiap lubang hidung secara sederhana.", "tools": ["Bahan bau tidak merangsang (kopi, teh, sabun, minyak kayu putih, tembakau)"], "prep": ["Pastikan kedua lubang hidung paten (tidak tersumbat sekret/polip)"], "steps": [["Periksa patensi", "Tutup satu lubang hidung, minta pasien menghirup — pastikan udara lewat."], ["Uji per sisi", "Mata pasien terpejam, tutup satu lubang hidung, dekatkan bahan bau ke lubang yang terbuka, minta pasien menghirup dan menyebutkan baunya."], ["Ganti bahan & sisi", "Gunakan ≥ 2 bahan berbeda; ulangi pada sisi lain dengan bahan yang diacak."], ["Hindari bahan iritan", "Amonia/alkohol merangsang n. V (trigeminus), bukan n. I."]], "normal": ["Normosmia: mengenali bau dengan benar kedua sisi."], "abn": [["Anosmia/hiposmia bilateral", "Rinitis, polip, ISPA/COVID-19, merokok, penuaan, Parkinson, Alzheimer"], ["Anosmia unilateral", "Tumor lobus frontal/meningioma olfaktorius, fraktur basis kranii anterior"], ["Parosmia/halusinasi bau", "Epilepsi lobus temporal (aura unsinatus)"]], "doc": "N. I: penghidu normal kanan/kiri (kopi, teh).", "key": ["Periksa per lubang hidung dengan mata tertutup", "Jangan pakai bahan iritan"], "tips": [], "dz": ["rinitis-alergi", "rinosinusitis-kronik"]},
	{"id": "pupil", "g": "saraf", "name": "Pupil & refleks cahaya (N. II–III)", "sk": [1, 2, 3, 4, 144, 145], "goal": "Menilai ukuran, bentuk, kesimetrisan pupil, refleks cahaya langsung/tidak langsung, dan akomodasi.", "tools": ["Senter (penlight)", "Kartu ukuran pupil"], "prep": ["Ruangan agak redup", "pasien melihat jauh"], "steps": [["Inspeksi celah kelopak & pupil", "Lebar fisura palpebra kanan-kiri (ptosis?), ukuran pupil (mm), bentuk (bulat/tidak), isokor atau anisokor."], ["Refleks cahaya langsung", "Sinari pupil dari samping-bawah; pupil yang disinari mengecil."], ["Refleks cahaya tidak langsung (konsensual)", "Sinari satu mata, amati pupil sisi lain ikut mengecil."], ["Swinging flashlight test", "Ayunkan cahaya bergantian kanan-kiri tiap 2–3 detik; pupil yang justru melebar saat disinari = RAPD (defek pupil aferen relatif / Marcus Gunn)."], ["Akomodasi-konvergensi", "Minta pasien melihat jauh lalu ke jari yang didekatkan ke hidung; pupil mengecil dan mata konvergen."]], "normal": ["Pupil bulat, isokor 2–5 mm, RCL +/+, RCTL +/+, akomodasi baik."], "abn": [["Pupil dilatasi unilateral tidak bereaksi + penurunan kesadaran", "Herniasi unkus (paresis n. III) — kegawatan bedah saraf"], ["Ptosis + miosis + anhidrosis", "Sindrom Horner (lesi simpatis: Pancoast, diseksi karotis)"], ["Ptosis + midriasis + mata ke bawah-luar", "Paresis n. III (aneurisma a. komunikans posterior bila pupil terlibat)"], ["RAPD (Marcus Gunn)", "Lesi n. optikus/retina berat sesisi (neuritis optik, glaukoma lanjut)"], ["Pin-point pupil bilateral", "Intoksikasi opioid/organofosfat, perdarahan pons"], ["Pupil kecil ireguler, akomodasi + cahaya − (Argyll Robertson)", "Neurosifilis, diabetes"], ["Pupil tonik lebar, lambat bereaksi (Adie)", "Pupil Adie (benigna), sering wanita muda"]], "doc": "Pupil bulat isokor Ø 3 mm/3 mm, RCL +/+, RCTL +/+, akomodasi baik, RAPD (−).", "key": ["Periksa langsung DAN tidak langsung", "Swinging flashlight untuk RAPD", "Sebutkan ukuran dalam mm"], "tips": ["Anisokoria fisiologis ≤ 1 mm dengan refleks normal ada pada ±20% orang", "Anisokoria lebih jelas di gelap = pupil kecil abnormal (Horner)", "lebih jelas di terang = pupil besar abnormal (n. III)"], "dz": ["hematoma-epidural", "intoksikasi-zat-akut"]},
	{"id": "gerak-bola-mata", "g": "saraf", "name": "Gerakan bola mata, diplopia & nistagmus (N. III, IV, VI)", "sk": [5, 6, 7, 142], "goal": "Menilai fungsi otot ekstraokular, mendeteksi diplopia dan nistagmus.", "tools": ["Senter atau ujung pena"], "prep": [], "steps": [["Posisi primer", "Amati kedudukan kedua mata saat melihat lurus (strabismus? deviasi?)."], ["Ikuti objek pola \"H\"", "Kepala pasien diam, minta mengikuti objek ±50 cm ke 6 arah kardinal (kanan, kanan-atas, kanan-bawah, kiri, kiri-atas, kiri-bawah), lalu ke tengah atas-bawah."], ["Tanyakan diplopia", "Di arah mana bayangan ganda paling jauh terpisah? Tutup satu mata — bayangan terluar milik mata yang lemah."], ["Amati nistagmus", "Tahan pandangan di lateral ±30° selama beberapa detik (jangan terlalu ekstrem — nistagmus fisiologis). Catat arah fase cepat, horizontal/vertikal/rotatoar."], ["Gerak sakadik & pursuit", "Minta melihat cepat bergantian ke dua target; nilai kecepatan dan akurasi."]], "normal": ["Kedudukan ortoforia, gerak bola mata bebas ke segala arah, tidak ada diplopia, tidak ada nistagmus."], "abn": [["Mata tidak bisa abduksi", "Paresis n. VI (peningkatan TIK — false localising sign, DM)"], ["Diplopia vertikal memburuk saat melihat ke bawah (membaca, turun tangga), kepala miring", "Paresis n. IV (trauma)"], ["Mata kebawah-luar + ptosis", "Paresis n. III"], ["Adduksi terganggu, nistagmus mata yang abduksi", "Oftalmoplegia internuklear (MLF): sklerosis multipel, stroke batang otak"], ["Nistagmus horizontal unidireksional, membaik dengan fiksasi", "Vestibular perifer (neuritis vestibularis, BPPV)"], ["Nistagmus vertikal/berubah arah/tidak membaik dengan fiksasi", "Sentral (serebelum/batang otak) — waspada stroke"], ["Diplopia fluktuatif memburuk sore hari", "Miastenia gravis"]], "doc": "Gerak bola mata baik ke segala arah, diplopia (−), nistagmus (−).", "key": ["Pola H dengan kepala diam", "Tanyakan diplopia di setiap arah", "Jangan lateral ekstrem saat menilai nistagmus"], "tips": [], "dz": ["bppv", "miastenia-gravis"]},
	{"id": "n5-trigeminus", "g": "saraf", "name": "N. V (trigeminus): sensorik, motorik & refleks kornea", "sk": [8, 11, 12, 149], "goal": "Menilai sensasi wajah tiga cabang, otot pengunyah, dan refleks kornea.", "tools": ["Kapas", "Jarum tumpul/peniti steril"], "prep": [], "steps": [["Sensorik tiga cabang", "Mata terpejam; sentuh kapas lalu jarum tumpul di dahi (V1), pipi (V2), dagu/rahang (V3) kanan dan kiri; bandingkan."], ["Motorik", "Minta pasien menggigit kuat sambil meraba m. masseter dan m. temporalis kedua sisi; minta membuka mulut melawan tahanan — rahang menyimpang ke sisi lemah (m. pterigoid)."], ["Refleks kornea", "Pasien melihat ke atas-samping berlawanan; sentuhkan ujung kapas yang dipilin ke kornea (bukan sklera) dari samping. Normal: kedua mata berkedip (aferen V1, eferen VII)."], ["Jaw jerk", "Mulut sedikit terbuka, letakkan jari di dagu, ketuk dengan palu refleks. Normal minimal/tidak ada."]], "normal": ["Sensasi wajah simetris, kekuatan menggigit baik, refleks kornea +/+, jaw jerk tidak meningkat."], "abn": [["Hilang sensasi satu cabang", "Lesi cabang perifer (trauma, herpes zoster oftalmikus)"], ["Refleks kornea hilang sesisi", "Lesi n. V (neuroma akustik/tumor sudut serebelopontin) atau n. VII"], ["Rahang deviasi saat membuka mulut", "Kelemahan m. pterigoid sisi deviasi"], ["Jaw jerk meningkat", "Lesi UMN bilateral di atas pons (pseudobulbar)"], ["Nyeri tajam seperti setrum tercetus sentuhan", "Neuralgia trigeminal"]], "doc": "N. V: sensorik V1–V3 simetris, motorik baik, refleks kornea +/+.", "key": ["Sentuh kornea, bukan sklera, dari samping", "Bandingkan kanan-kiri tiga cabang"], "tips": [], "dz": ["neuralgia-trigeminal", "herpes-zoster"]},
	{"id": "n7-fasialis", "g": "saraf", "name": "N. VII (fasialis): kesimetrisan, gerakan wajah & pengecapan", "sk": [10, 13, 14, 197], "goal": "Membedakan paresis fasialis sentral (UMN) dan perifer (LMN) serta menilai pengecapan 2/3 anterior lidah.", "tools": ["Larutan gula, garam, asam, pahit", "Lidi kapas"], "prep": [], "steps": [["Inspeksi saat istirahat", "Simetri lipatan dahi, celah palpebra, plika nasolabialis, sudut mulut."], ["Gerakan otot wajah", "Angkat alis/kerutkan dahi; pejamkan mata kuat (coba buka); kembungkan pipi (tekan); tersenyum/tunjukkan gigi; bersiul."], ["Bedakan sentral vs perifer", "Dahi ikut lumpuh = perifer; dahi tetap bisa dikerutkan (persarafan bilateral) = sentral."], ["Pengecapan", "Lidah dijulurkan, oleskan larutan di 2/3 anterior satu sisi; pasien menunjuk kartu rasa tanpa menarik lidah; berkumur di antara tiap rasa."], ["Fungsi lain", "Tanyakan hiperakusis (m. stapedius) dan mata kering/berair."]], "normal": ["Wajah simetris saat istirahat dan bergerak", "pengecapan normal."], "abn": [["Seluruh wajah sesisi lumpuh termasuk dahi, Bell's phenomenon (+)", "Paresis n. VII perifer (Bell's palsy, Ramsay Hunt, otitis media, trauma)"], ["Hanya wajah bawah lumpuh, dahi normal", "Paresis n. VII sentral (stroke, tumor)"], ["Vesikel di telinga + paresis perifer", "Sindrom Ramsay Hunt (herpes zoster otikus)"], ["Paresis bilateral", "Guillain-Barré, sarkoidosis, penyakit Lyme"], ["Hiperakusis + gangguan pengecapan", "Lesi proksimal (di atas korda timpani dan n. stapedius)"]], "doc": "N. VII: wajah simetris saat diam dan bergerak, kerut dahi +/+, menutup mata kuat +/+, pengecapan 2/3 anterior normal.", "key": ["Periksa dahi untuk membedakan sentral/perifer", "Minimal 4 gerakan wajah"], "tips": ["Pada paresis perifer, tanyakan onset, otalgia, dan periksa telinga"], "dz": ["bells-palsy", "stroke-iskemik"]},
	{"id": "n9-n12-bulbar", "g": "saraf", "name": "N. IX–XII: menelan, palatum, refleks muntah, sternomastoid, trapezius & lidah", "sk": [16, 17, 18, 19, 20, 21, 321], "goal": "Menilai saraf kranial bawah (bulbar) yang mengatur menelan, bicara, otot leher, dan lidah.", "tools": ["Senter", "Spatel lidah", "Segelas air"], "prep": [], "steps": [["Suara & batuk", "Dengarkan suara (serak, sengau/nasal) dan kekuatan batuk."], ["Palatum & uvula", "Minta pasien membuka mulut dan berkata \"aaa\"; arkus faring naik simetris, uvula tetap di tengah."], ["Refleks muntah (gag)", "Sentuh dinding faring posterior kanan lalu kiri dengan spatel (aferen IX, eferen X). Lakukan hanya bila ada indikasi."], ["Uji menelan", "Pasien duduk tegak, minum 1 sendok teh lalu 50–100 mL air; amati batuk, suara basah, atau tersedak."], ["N. XI", "Angkat bahu melawan tahanan (trapezius); putar kepala melawan tahanan tangan pemeriksa di pipi (m. sternokleidomastoideus kontralateral dari arah putaran)."], ["N. XII istirahat", "Lidah di dasar mulut: atrofi, fasikulasi."], ["N. XII dijulurkan", "Julurkan lurus, gerak ke kanan-kiri; dorong pipi dari dalam melawan jari pemeriksa."]], "normal": ["Suara jelas, palatum naik simetris, uvula di tengah, gag +/+, menelan aman, angkat bahu & menoleh kuat, lidah tanpa atrofi/fasikulasi, dijulurkan di tengah."], "abn": [["Uvula tertarik ke satu sisi", "Paresis n. X sisi berlawanan dari arah uvula"], ["Lidah deviasi saat dijulurkan", "Paresis n. XII ke sisi deviasi (LMN) atau kontralateral lesi (UMN)"], ["Atrofi + fasikulasi lidah", "Lesi LMN (ALS/penyakit motor neuron, siringobulbia)"], ["Lidah kecil kaku, gerak lambat, jaw jerk meningkat", "Palsi pseudobulbar (UMN bilateral)"], ["Batuk/suara basah saat uji menelan", "Disfagia orofaring — risiko aspirasi, puasakan & rujuk"], ["Bahu turun, tidak bisa angkat bahu", "Paresis n. XI (pascabedah leher)"]], "doc": "N. IX–X: arkus faring simetris, uvula di tengah, refleks muntah +/+, menelan baik. N. XI: kekuatan sternokleidomastoideus & trapezius baik. N. XII: lidah di tengah, atrofi (−), fasikulasi (−).", "key": ["Uji menelan air sebelum memberi makan pasien stroke", "Nilai lidah saat istirahat dan dijulurkan"], "tips": [], "dz": ["stroke-iskemik", "als"]},
	{"id": "motorik", "g": "saraf", "name": "Sistem motorik: inspeksi, tonus, kekuatan & trofi", "sk": [22, 23, 24, 25, 523, 516], "goal": "Menilai postur, gerakan abnormal, tonus, kekuatan (skala MRC 0–5), dan massa otot untuk membedakan lesi UMN dan LMN.", "tools": ["Pita ukur"], "prep": [], "steps": [["Inspeksi", "Postur, habitus, gerakan involunter (tremor, korea, mioklonus, fasikulasi), atrofi/hipertrofi, kesimetrisan."], ["Trofi", "Bandingkan massa otot kanan-kiri; ukur lingkar lengan/paha pada jarak yang sama dari tonjolan tulang."], ["Tonus", "Pasien rileks; gerakkan pasif sendi siku, pergelangan, lutut dengan kecepatan bervariasi. Tonus lutut: guling tungkai (leg roll) dan angkat lutut cepat (kaki masih menempel kasur = normal)."], ["Uji pronator drift", "Kedua lengan diluruskan ke depan, telapak menghadap atas, mata terpejam 20–30 detik. Lengan turun dan pronasi = kelemahan UMN halus."], ["Kekuatan otot (MRC)", "Uji tiap kelompok otot melawan tahanan, bandingkan kanan-kiri: bahu abduksi, siku fleksi/ekstensi, pergelangan, genggaman, jari abduksi; panggul fleksi/ekstensi, lutut, dorsofleksi/plantarfleksi."], ["Catat dengan skala", "0 tidak ada kontraksi; 1 kontraksi tanpa gerak; 2 gerak tanpa gravitasi; 3 melawan gravitasi; 4 melawan tahanan ringan; 5 normal."]], "normal": ["Eutrofi, tonus normal, kekuatan 5555/5555 di keempat ekstremitas, tidak ada gerakan involunter."], "abn": [["Spastisitas (clasp-knife) + hiperrefleks + Babinski (+)", "Lesi UMN (stroke, mielopati)"], ["Rigiditas lead-pipe/cogwheel + tremor istirahat", "Parkinsonisme"], ["Hipotonus + atrofi + fasikulasi + hiporefleks", "Lesi LMN (sel kornu anterior, radiks, saraf perifer)"], ["Kelemahan proksimal simetris", "Miopati, polimiositis, hipotiroid, steroid"], ["Kelemahan distal + gangguan sensorik stocking-glove", "Polineuropati"], ["Hemiparesis", "Lesi hemisfer/kapsula interna kontralateral (stroke)"], ["Paraparesis + level sensorik", "Lesi medula spinalis (trauma, spondilitis TB, tumor)"]], "doc": "Motorik: eutrofi, tonus normal, kekuatan 5555|5555 / 5555|5555, gerakan involunter (−).", "key": ["Bandingkan kanan-kiri tiap kelompok otot", "Skala MRC benar", "Bedakan pola UMN vs LMN"], "tips": ["Tuliskan kekuatan dengan 4 angka per ekstremitas (proksimal → distal)"], "dz": ["stroke-iskemik", "parkinson", "gbs"]},
	{"id": "refleks-fisiologis", "g": "saraf", "name": "Refleks fisiologis (tendon & superfisial)", "sk": [49, 50, 51, 52], "goal": "Menilai refleks tendon dalam dan refleks superfisial untuk melokalisasi lesi saraf.", "tools": ["Palu refleks"], "prep": [], "steps": [["Posisi & teknik", "Pasien rileks, otot sedikit teregang; pegang palu longgar di ujung, ayunkan dari pergelangan; bandingkan kanan-kiri segera."], ["Biseps (C5–6)", "Siku fleksi 90° di atas paha/disangga, ibu jari pemeriksa di tendon biseps, ketuk ibu jari."], ["Triseps (C7)", "Lengan disangga menggantung siku fleksi 90°, ketuk tendon tepat di atas olekranon."], ["Brakioradialis (C5–6)", "Lengan bawah setengah pronasi di pangkuan, ketuk radius distal ±5 cm di atas pergelangan."], ["Patela (L3–4)", "Duduk dengan tungkai menggantung atau berbaring dengan lutut ditopang, ketuk tendon patela."], ["Achilles (S1)", "Kaki sedikit dorsofleksi oleh tangan pemeriksa, ketuk tendon Achilles."], ["Reinforcement (Jendrassik)", "Bila refleks negatif, minta pasien mengaitkan jari dan menarik (tungkai) atau mengepal/menggigit (lengan) tepat saat diketuk."], ["Superfisial", "Abdominal: gores 4 kuadran ke arah umbilikus (T8–12); kremaster: gores paha medial atas → testis naik (L1–2); anal: gores perianal → kontraksi sfingter (S2–4)."]], "normal": ["Refleks tendon +2 simetris", "refleks abdominal, kremaster, anal positif."], "abn": [["Hiperrefleks (+3/+4) + klonus", "Lesi UMN"], ["Hiporefleks/arefleks", "Lesi LMN, neuropati perifer, GBS, hipotiroid (relaksasi lambat), hipokalemia"], ["Asimetri refleks", "Lesi fokal (radikulopati sisi yang menurun)"], ["Refleks abdominal hilang sesisi", "Lesi UMN ipsilateral atau lesi T8–12"], ["Refleks anal/bulbokavernosus hilang + retensi urin + saddle anesthesia", "Sindrom kauda ekuina — rujuk darurat"]], "doc": "Refleks fisiologis: BPR +2/+2, TPR +2/+2, KPR +2/+2, APR +2/+2; refleks abdominal (+).", "key": ["Teknik ketukan dan posisi benar", "Bandingkan kanan-kiri", "Gunakan Jendrassik bila negatif"], "tips": ["Skala: 0 tidak ada, +1 menurun, +2 normal, +3 meningkat, +4 dengan klonus"], "dz": ["gbs", "hnp", "sindrom-kauda-ekuina"]},
	{"id": "refleks-patologis", "g": "saraf", "name": "Refleks patologis (Babinski & Hoffmann-Tromner) dan klonus", "sk": [57, 59], "goal": "Mendeteksi tanda lesi traktus piramidal (UMN).", "tools": ["Palu refleks dengan ujung tumpul/kunci"], "prep": [], "steps": [["Babinski", "Gores telapak kaki lateral dari tumit ke arah jari kelingking lalu melengkung medial ke pangkal ibu jari dengan benda tumpul. Positif: ekstensi (dorsofleksi) ibu jari ± jari lain mengembang."], ["Grup Babinski", "Chaddock (gores maleolus lateral), Oppenheim (urut tulang kering ke bawah), Gordon (remas betis), Schaeffer (cubit tendon Achilles), Gonda (tekuk jari ke-4)."], ["Hoffmann", "Pegang jari tengah pasien, jentikkan falang distal ke bawah. Positif: fleksi-adduksi ibu jari."], ["Tromner", "Ketuk ujung jari tengah dari bawah (volar). Positif: fleksi ibu jari & jari lain."], ["Klonus", "Lutut fleksi, dorsofleksikan kaki cepat dan tahan; > 3 denyutan berirama = klonus bermakna. Klonus patela: dorong patela ke distal cepat."]], "normal": ["Babinski (−/−), Hoffmann-Tromner (−/−), klonus (−)."], "abn": [["Babinski (+) pada dewasa", "Lesi UMN (stroke, tumor, mielopati, cedera medula)"], ["Babinski (+) pada bayi < 1–2 tahun", "Normal (traktus piramidal belum matang)"], ["Hoffmann (+) unilateral", "Lesi UMN lengan (mielopati servikal, stroke)"], ["Klonus berkelanjutan", "Lesi UMN"]], "doc": "Refleks patologis: Babinski −/−, Chaddock −/−, Hoffmann-Tromner −/−; klonus (−).", "key": ["Arah goresan Babinski benar (lateral lalu medial)", "Jangan terlalu dekat jari (memicu genggam)", "Klonus > 3 denyut"], "tips": ["Withdrawal (menarik seluruh tungkai) bukan Babinski positif — ulangi lebih lembut"], "dz": ["stroke-iskemik", "mielopati"]},
	{"id": "refleks-primitif", "g": "saraf", "name": "Refleks primitif/release (glabela, snout, palmomental, menghisap, menggenggam)", "sk": [53, 54, 55, 56, 58], "goal": "Mendeteksi refleks primitif yang muncul kembali pada dewasa akibat lesi lobus frontal/difus.", "tools": ["Palu refleks"], "prep": [], "steps": [["Glabela (Myerson)", "Ketuk glabela berulang dari atas kepala (di luar lapang pandang). Normal: berkedip lalu berhenti setelah 3–5 ketukan. Positif: terus berkedip."], ["Snout", "Ketuk bibir atas di garis tengah. Positif: bibir mengerucut/monyong."], ["Menghisap (sucking/rooting)", "Gores sudut mulut. Positif: mulut menoleh/menghisap ke arah rangsang."], ["Palmomental", "Gores tenar telapak tangan dari proksimal ke distal. Positif: kontraksi m. mentalis (dagu) sisi yang sama."], ["Menggenggam (grasp)", "Gores telapak tangan dari pangkal ke jari. Positif: pasien menggenggam dan sulit melepas."]], "normal": ["Pada dewasa negatif (glabela berhenti setelah beberapa ketukan). Pada bayi refleks menghisap & menggenggam normal ada."], "abn": [["Glabela tidak berhenti", "Parkinson, lesi frontal difus"], ["Grasp/snout/menghisap positif pada dewasa", "Demensia, lesi lobus frontal, ensefalopati difus"], ["Palmomental positif unilateral", "Lesi frontal kontralateral (bermakna bila asimetris)"]], "doc": "Refleks primitif: glabela (−), snout (−), menghisap (−), palmomental (−/−), grasp (−/−).", "key": ["Ketuk glabela dari luar lapang pandang", "Tafsirkan sesuai usia"], "tips": ["Palmomental positif simetris ringan dapat ditemukan pada lansia normal"], "dz": ["demensia", "parkinson"]},
	{"id": "sensorik", "g": "saraf", "name": "Sistem sensorik (nyeri, suhu, raba, posisi, getar, diskriminatif)", "sk": [34, 35, 36, 37, 38, 39, 40], "goal": "Memetakan gangguan sensorik eksteroseptif, proprioseptif, dan kortikal untuk lokalisasi lesi.", "tools": ["Kapas", "Jarum tumpul sekali pakai", "Garpu tala 128 Hz", "Tabung air hangat & dingin", "Jangka/klip kertas untuk 2 titik", "Benda kecil (koin, kunci)"], "prep": ["Jelaskan dan contohkan rangsang di sternum dengan mata terbuka", "pemeriksaan dengan mata tertutup"], "steps": [["Raba halus", "Sentuh kapas (jangan diusap) di dermatom/area saraf perifer, bandingkan kanan-kiri dan distal-proksimal."], ["Nyeri", "Jarum tumpul bergantian tajam/tumpul; minta pasien menyebut \"tajam\" atau \"tumpul\". Petakan batas dari area kurang ke area normal."], ["Suhu", "Tabung hangat (±40 °C) dan dingin (±10 °C) atau garpu tala dingin."], ["Getar", "Garpu tala 128 Hz digetarkan, letakkan di sendi interfalang distal ibu jari kaki; tanya \"terasa getar? kapan berhenti?\" Bila menurun, naik ke maleolus, tuberositas tibia, SIAS."], ["Posisi sendi (proprioseptif)", "Pegang sisi lateral ibu jari kaki/tangan, gerakkan ke atas/bawah kecil; pasien menebak arah dengan mata terpejam."], ["Diskriminatif", "Stereognosis (kenali benda di tangan), grafestesia (angka ditulis di telapak), diskriminasi 2 titik (normal ujung jari ≤ 5 mm), ekstinksi sensorik (sentuh kedua sisi bersamaan)."]], "normal": ["Sensasi raba, nyeri, suhu, getar, posisi, dan diskriminatif normal simetris."], "abn": [["Pola kaus kaki-sarung tangan (stocking-glove)", "Polineuropati (DM, defisiensi B12, alkohol, kusta)"], ["Level sensorik (batas tegas di dada/perut)", "Lesi medula spinalis setinggi level tersebut"], ["Hemihipestesia (wajah, lengan, tungkai sesisi)", "Lesi talamus/kapsula interna/korteks kontralateral"], ["Nyeri & suhu hilang sesisi, getar & posisi hilang sisi lain", "Sindrom Brown-Séquard (hemiseksi medula)"], ["Hilang nyeri & suhu bentuk jubah (cape) di bahu-lengan", "Siringomielia (lesi sentral servikal)"], ["Getar & posisi terganggu + Romberg (+)", "Lesi kolumna dorsalis (defisiensi B12, tabes dorsalis)"], ["Astereognosis/agrafestesia dengan sensasi primer normal", "Lesi korteks parietal kontralateral"], ["Area anestesi pada bercak kulit", "Kusta (morbus Hansen)"]], "doc": "Sensorik: raba halus, nyeri, suhu, getar, dan proprioseptif normal di keempat ekstremitas; stereognosis baik.", "key": ["Contohkan rangsang dulu dengan mata terbuka", "Bandingkan kanan-kiri dan distal-proksimal", "Petakan batas dari area abnormal ke normal"], "tips": ["Getar dan posisi sering hilang paling awal pada neuropati diabetik"], "dz": ["neuropati-simetris", "kusta", "defisiensi-vitamin"]},
	{"id": "koordinasi", "g": "saraf", "name": "Koordinasi serebelar (telunjuk-hidung, tumit-lutut, disdiadokinesis, past-pointing)", "sk": [27, 31, 32, 33], "goal": "Menilai fungsi serebelum (ataksia ekstremitas) secara sederhana.", "tools": [], "prep": [], "steps": [["Telunjuk-hidung", "Minta pasien menyentuh ujung jari pemeriksa (sejauh lengan) lalu hidungnya sendiri, berulang cepat; pindahkan posisi jari pemeriksa. Amati tremor intensi dan dismetria."], ["Telunjuk-telunjuk / past-pointing", "Pasien merentangkan lengan, lalu menunjuk jari pemeriksa dari atas dengan mata terbuka lalu tertutup. Penyimpangan konsisten ke satu sisi = past-pointing."], ["Tumit-lutut-kering", "Berbaring; letakkan tumit di lutut sisi lain, luncurkan sepanjang tulang kering ke pergelangan, angkat dan ulangi."], ["Disdiadokinesis", "Tepuk punggung tangan dan telapak bergantian cepat di atas tangan lain atau paha; atau ketuk-ketuk kaki cepat di lantai."], ["Rebound (Holmes)", "Pasien menarik lengan (fleksi siku) melawan tahanan; lepas mendadak — normal pasien dapat menghentikan gerakan."]], "normal": ["Gerakan tepat dan halus, tidak ada tremor intensi, dismetria, atau disdiadokinesis", "past-pointing (−)."], "abn": [["Tremor intensi, dismetria, disdiadokinesia ipsilateral", "Lesi hemisfer serebelum sisi yang sama (stroke, tumor, MS)"], ["Ataksia tungkai/badan dengan ekstremitas atas baik", "Lesi vermis serebelum (alkohol)"], ["Past-pointing ke satu sisi", "Lesi vestibular perifer (menyimpang ke sisi lesi) atau serebelum"], ["Koordinasi buruk hanya saat mata tertutup", "Ataksia sensorik (kolumna dorsalis), bukan serebelar"]], "doc": "Koordinasi: telunjuk-hidung baik, tumit-lutut baik, disdiadokinesis (−), past-pointing (−).", "key": ["Target dipindah-pindah", "Bandingkan kanan-kiri", "Bedakan serebelar vs sensorik"], "tips": ["Kelemahan otot dapat menyerupai ataksia — nilai kekuatan dulu"], "dz": ["bppv", "stroke-iskemik"]},
	{"id": "keseimbangan-gait", "g": "saraf", "name": "Keseimbangan & cara berjalan (Romberg, Romberg dipertajam, Fukuda, gait)", "sk": [26, 28, 29, 30, 182, 514], "goal": "Menilai keseimbangan statis-dinamis dan pola berjalan untuk membedakan gangguan vestibular, serebelar, sensorik, dan motorik.", "tools": [], "prep": ["Berdiri dekat pasien untuk mencegah jatuh"], "steps": [["Gait", "Minta pasien berjalan normal ±5 m, berbalik, kembali. Nilai inisiasi, panjang langkah, lebar basis, ayunan lengan, kestabilan saat berbalik."], ["Tandem gait", "Berjalan lurus tumit menyentuh ujung jari kaki (seperti di atas tali)."], ["Romberg", "Berdiri kedua kaki rapat, lengan di samping; mata terbuka 30 detik lalu terpejam 30 detik. Positif bila hilang keseimbangan HANYA saat mata tertutup."], ["Romberg dipertajam (Sharpened)", "Berdiri tandem (satu kaki di depan kaki lain), lengan bersilang di dada, mata terpejam 30 detik."], ["Fukuda (stepping test)", "Mata terpejam, lengan lurus ke depan, berjalan di tempat 50 langkah. Berputar > 30–45° ke satu sisi = disfungsi vestibular sisi tersebut."], ["Uji vestibular sederhana", "Head impulse test (putar kepala cepat ±15° sambil pasien menatap hidung pemeriksa — saccade koreksi = perifer); Dix-Hallpike untuk BPPV."]], "normal": ["Gait normal, tandem baik, Romberg (−), Romberg dipertajam (−), Fukuda tidak berputar > 30°."], "abn": [["Romberg (+)", "Ataksia sensorik (kolumna dorsalis, neuropati) atau vestibular"], ["Jatuh ke satu sisi meski mata terbuka", "Lesi serebelum (bukan Romberg positif)"], ["Fukuda berputar ke satu sisi", "Lesi vestibular perifer sisi tersebut"], ["Gait broad-based, sempoyongan", "Ataksia serebelar"], ["Langkah kecil terseret, ayunan lengan berkurang, festinasi", "Parkinson"], ["Sirkumduksi tungkai, lengan fleksi", "Hemiparesis spastik (stroke)"], ["Steppage (kaki diangkat tinggi, foot drop)", "Paresis n. peroneus/radikulopati L5, neuropati"], ["Waddling (bebek)", "Kelemahan otot panggul proksimal (miopati), displasia panggul"], ["Head impulse test abnormal + nistagmus unidireksional", "Neuritis vestibular (perifer)"], ["Dix-Hallpike: nistagmus torsional-upbeat laten, singkat, kelelahan", "BPPV kanalis posterior"]], "doc": "Gait normal, tandem walking baik, Romberg (−), Romberg dipertajam (−), Fukuda (−).", "key": ["Jaga keamanan pasien", "Romberg: bandingkan mata terbuka vs tertutup", "Deskripsikan pola gait"], "tips": ["HINTS (Head Impulse, Nystagmus, Test of Skew) membantu membedakan vertigo perifer vs stroke"], "dz": ["bppv", "parkinson"]},
	{"id": "meningeal", "g": "saraf", "name": "Tanda rangsang meningeal (kaku kuduk, Kernig, Brudzinski)", "sk": [62, 67, 68], "goal": "Mendeteksi iritasi meningen (meningitis, perdarahan subaraknoid).", "tools": [], "prep": ["Pasien berbaring terlentang tanpa bantal", "pastikan tidak ada cedera servikal"], "steps": [["Kaku kuduk", "Tangan pemeriksa di bawah oksiput, fleksikan leher pasif hingga dagu menyentuh dada. Positif bila ada tahanan dan dagu tidak mencapai dada. Bandingkan dengan rotasi leher (normal pada meningitis)."], ["Brudzinski I (leher)", "Saat fleksi leher, positif bila kedua tungkai fleksi di panggul dan lutut secara refleks."], ["Brudzinski II (kontralateral)", "Fleksikan satu tungkai pada panggul dengan lutut lurus; positif bila tungkai kontralateral ikut fleksi."], ["Kernig", "Fleksikan panggul dan lutut 90°, lalu ekstensikan lutut. Positif bila ekstensi < 135° karena tahanan/nyeri, biasanya bilateral."], ["Pada bayi", "Tanda meningeal sering tidak ada — nilai ubun-ubun membonjol, iritabel, kejang, malas minum."]], "normal": ["Kaku kuduk (−), Brudzinski I/II (−), Kernig > 135° (−)."], "abn": [["Kaku kuduk + demam + penurunan kesadaran", "Meningitis/ensefalitis — kultur darah & antibiotik empiris segera, rujuk"], ["Kaku kuduk + nyeri kepala hebat mendadak (thunderclap)", "Perdarahan subaraknoid"], ["Kaku pada semua arah gerakan leher", "Penyakit servikal (spondilosis), parkinsonisme, bukan meningeal"], ["Kernig unilateral", "Radikulopati (HNP), bukan meningeal"]], "doc": "Tanda rangsang meningeal: kaku kuduk (−), Brudzinski I/II (−/−), Kernig (−/−).", "key": ["Pastikan tidak ada cedera servikal sebelum fleksi leher", "Bedakan kaku kuduk dengan kaku leher semua arah"], "tips": ["Sensitivitas tanda meningeal rendah — jangan menyingkirkan meningitis hanya karena negatif"], "dz": ["meningitis", "ensefalitis", "sah"]},
	{"id": "lasegue-patrick", "g": "saraf", "name": "Lasègue, Patrick/kontra-Patrick, nyeri tekan vertikal & fleksi lumbal", "sk": [60, 61, 64, 66, 521, 529], "goal": "Membedakan nyeri punggung bawah radikular (iritasi radiks) dari kelainan sendi panggul dan sakroiliaka.", "tools": [], "prep": [], "steps": [["Nyeri tekan vertikal (axial loading)", "Tekan puncak kepala ke bawah saat pasien berdiri/duduk; nyeri leher/punggung menunjukkan kelainan vertebra (namun juga tanda Waddell nonorganik bila nyeri punggung bawah)."], ["Fleksi lumbal (Schober)", "Tandai L5 dan 10 cm di atasnya saat berdiri; minta membungkuk maksimal. Pertambahan jarak < 5 cm = keterbatasan fleksi (spondilitis ankilosa)."], ["Lasègue (straight leg raise)", "Terlentang, angkat tungkai lurus pasif perlahan. Positif bila nyeri menjalar ke bawah lutut pada sudut 30–70°. Tambah dorsofleksi kaki (Bragard) memperberat."], ["Lasègue silang", "Mengangkat tungkai sehat memicu nyeri di tungkai yang sakit — spesifik untuk HNP."], ["Patrick (FABER)", "Tumit diletakkan di lutut kontralateral (fleksi-abduksi-rotasi eksterna), tekan lutut ke bawah. Nyeri lipat paha = sendi panggul; nyeri bokong/sakroiliaka = sendi SI."], ["Kontra-Patrick (FADIR)", "Fleksi-adduksi-rotasi interna panggul; nyeri = sendi SI/panggul (impingement)."]], "normal": ["Lasègue (−) > 70°, Patrick (−), kontra-Patrick (−), Schober ≥ 5 cm, nyeri tekan vertikal (−)."], "abn": [["Lasègue (+) 30–70°", "Iritasi radiks L4–S1 (HNP lumbal)"], ["Lasègue silang (+)", "HNP dengan spesifisitas tinggi"], ["Patrick (+) nyeri lipat paha", "Kelainan sendi panggul (OA, nekrosis avaskular)"], ["Patrick/kontra-Patrick (+) nyeri sakroiliaka", "Sakroiliitis (spondiloartritis)"], ["Schober < 5 cm", "Spondilitis ankilosa"], ["Nyeri punggung + defisit neurologis progresif/retensi urin", "Red flag — rujuk segera"]], "doc": "Lasègue −/−, Bragard −/−, Patrick −/−, kontra-Patrick −/−, Schober 5 cm.", "key": ["Catat sudut Lasègue dan lokasi nyeri", "Bedakan nyeri pinggang (bukan radikular) dengan nyeri menjalar"], "tips": ["Nyeri hanya di punggung saat SLR bukan Lasègue positif"], "dz": ["hnp"]},
	{"id": "chvostek", "g": "saraf", "name": "Tanda Chvostek (dan Trousseau)", "sk": [65], "goal": "Mendeteksi hipereksitabilitas neuromuskular akibat hipokalsemia/hipomagnesemia.", "tools": ["Palu refleks", "Sfigmomanometer"], "prep": [], "steps": [["Chvostek", "Ketuk n. fasialis ±2 cm di depan tragus telinga (di bawah arkus zigomatikus). Positif: kedutan sudut mulut/hidung/kelopak sisi yang sama."], ["Trousseau", "Pompa manset 20 mmHg di atas sistolik selama 3 menit. Positif: spasme karpal (fleksi pergelangan dan MCP, ekstensi IP, adduksi ibu jari — \"tangan bidan\")."]], "normal": ["Chvostek (−), Trousseau (−)."], "abn": [["Chvostek (+)", "Hipokalsemia, hipomagnesemia, alkalosis (hiperventilasi); ±10% orang normal positif"], ["Trousseau (+)", "Hipokalsemia (lebih spesifik dari Chvostek)"], ["Positif pascatiroidektomi", "Hipoparatiroid — cek kalsium segera"]], "doc": "Chvostek (−), Trousseau (−).", "key": ["Lokasi ketukan tepat di depan tragus", "Durasi manset 3 menit"], "tips": [], "dz": ["elektrolit-neonatal"]},
	{"id": "fungsi-luhur", "g": "saraf", "name": "Fungsi luhur (orientasi, atensi, memori, bahasa, apraksia, agnosia)", "sk": [42, 43, 44, 45, 46, 47, 48], "goal": "Menyaring gangguan kognitif dan fungsi kortikal fokal (afasia, apraksia, agnosia).", "tools": ["MMSE atau MoCA versi Indonesia", "Kertas & pulpen", "Benda sehari-hari"], "prep": [], "steps": [["Orientasi", "Waktu (tahun, bulan, tanggal, hari, jam), tempat (kota, gedung, lantai), orang (siapa pemeriksa, keluarga)."], ["Atensi & konsentrasi", "Pengurangan 100−7 berturut-turut 5 kali, mengeja kata mundur, menyebut hari/bulan mundur, digit span."], ["Memori", "Registrasi 3 kata → ulangi setelah 5 menit (memori jangka pendek/belajar baru); memori jangka panjang: peristiwa pribadi/umum yang dapat diverifikasi."], ["Bahasa", "Bicara spontan (lancar?), pemahaman perintah 1–3 langkah, repetisi kalimat, penamaan benda, membaca dan menulis."], ["Apraksia", "Minta melakukan gerakan atas perintah lalu meniru: \"tunjukkan cara menyisir/memakai sikat gigi\", melambai, memakai baju (apraksia berpakaian), menggambar jam/menyalin segi lima (konstruksional)."], ["Agnosia", "Kenali benda dengan melihat (visual), wajah (prosopagnosia), benda di tangan dengan mata tertutup (taktil = astereognosis); pengabaian satu sisi (neglect)."], ["Skor terstandar", "MMSE (normal 24–30) atau MoCA (normal ≥ 26; +1 bila pendidikan ≤ 12 tahun)."]], "normal": ["Orientasi baik, atensi baik, memori 3/3, bahasa normal, tidak ada apraksia/agnosia, MMSE ≥ 24 (MoCA ≥ 26)."], "abn": [["Afasia Broca (tidak lancar, paham baik, repetisi buruk)", "Lesi girus frontal inferior dominan"], ["Afasia Wernicke (lancar tanpa makna, paham buruk)", "Lesi girus temporal superior dominan"], ["Afasia konduksi (lancar, paham baik, repetisi sangat buruk)", "Lesi fasikulus arkuatus"], ["Neglect kiri, apraksia berpakaian", "Lesi parietal kanan (nondominan)"], ["Gangguan memori baru progresif", "Demensia Alzheimer"], ["Gangguan atensi akut fluktuatif", "Delirium"], ["MMSE < 24", "Gangguan kognitif — evaluasi demensia (sesuaikan pendidikan)"]], "doc": "Fungsi luhur: orientasi O/T/W baik, atensi baik, memori 3/3, bahasa baik, apraksia (−), agnosia (−). MMSE 29/30.", "key": ["Nilai atensi sebelum memori", "Pisahkan komponen bahasa (lancar, paham, repetisi, penamaan)"], "tips": ["Gangguan kognitif pada lansia sakit akut → curigai delirium dulu sebelum demensia"], "dz": ["demensia", "delirium", "stroke-iskemik"]},
	{"id": "fontanel", "g": "anak", "name": "Penilaian fontanel (ubun-ubun)", "sk": [63, 598], "goal": "Menilai ukuran, ketegangan, dan penutupan fontanel sebagai indikator TIK, hidrasi, dan pertumbuhan tengkorak.", "tools": [], "prep": ["Bayi tenang, posisi tegak/duduk (menangis dan berbaring membuat ubun-ubun tampak menonjol)"], "steps": [["Inspeksi", "Cekung, datar, atau membonjol; pulsasi."], ["Palpasi fontanel anterior", "Raba lembut dengan ujung jari; ukur diagonal (rata-rata 2,1 cm; normal 0,6–3,6 cm)."], ["Fontanel posterior", "Raba di pertemuan sutura sagitalis dan lambdoidea (biasanya < 1 cm, menutup ±2 bulan)."], ["Sutura", "Raba sutura; lebar/terpisah atau tumpang tindih (molding pada BBL) atau menonjol keras (kraniosinostosis)."], ["Ukur lingkar kepala", "Pita melingkar oksiput-glabela; plot di kurva WHO."]], "normal": ["Datar, lunak, sedikit berdenyut", "fontanel anterior menutup 12–18 bulan (paling lambat 24 bulan)."], "abn": [["Membonjol tegang saat tenang & tegak", "Peningkatan TIK: meningitis, hidrosefalus, perdarahan"], ["Cekung", "Dehidrasi"], ["Besar/lambat menutup", "Hidrosefalus, hipotiroid kongenital, rakitis, sindrom Down, akondroplasia"], ["Menutup terlalu dini + kepala kecil", "Mikrosefali, kraniosinostosis"]], "doc": "UUB datar, ukuran 2 × 2 cm, tidak tegang. LK 40 cm (persentil 50).", "key": ["Nilai saat bayi tenang dan tegak", "Ukur dan catat lingkar kepala"], "tips": [], "dz": ["meningitis", "hidrosefalus", "diare-akut"]},
	{"id": "wawancara-psikiatri", "g": "psikiatri", "name": "Wawancara psikiatri (auto- & alloanamnesis)", "sk": [81, 82, 83, 84, 85], "goal": "Memperoleh data keluhan utama, perjalanan penyakit, riwayat pribadi, dan faktor risiko secara terstruktur dan empatik.", "tools": [], "prep": ["Ruangan tenang dan privat", "posisi duduk tidak berhadapan langsung (±45°)", "pastikan keamanan (jalur keluar)"], "steps": [["Bangun rapport", "Perkenalkan diri, pertanyaan terbuka (\"apa yang membuat Anda datang hari ini?\"), dengarkan aktif, refleksikan perasaan."], ["Keluhan utama & RPS", "Onset, pencetus, perjalanan, gejala (mood, psikotik, cemas, tidur, makan), dampak fungsi (pekerjaan, sosial)."], ["Riwayat dahulu", "Episode sebelumnya, rawat inap, terapi & kepatuhan, penyakit medis, penggunaan zat (alkohol, NAPZA, rokok)."], ["Riwayat pribadi", "Kehamilan-persalinan, tumbuh kembang, pendidikan, pekerjaan, perkawinan, kehidupan keluarga, kepribadian premorbid, riwayat hukum."], ["Riwayat keluarga", "Gangguan jiwa, bunuh diri, penggunaan zat dalam keluarga; genogram."], ["Penilaian risiko", "Tanyakan langsung ide/rencana bunuh diri dan risiko mencederai orang lain."], ["Alloanamnesis", "Dengan izin pasien, wawancarai keluarga/orang terdekat untuk data objektif dan perjalanan penyakit."]], "normal": ["Data lengkap, kronologis, dengan sumber (auto/allo) dan reliabilitas tercatat."], "abn": [["Ide bunuh diri dengan rencana/akses sarana", "Risiko tinggi — jangan tinggalkan pasien sendiri, rujuk/rawat"], ["Ketidaksesuaian cerita pasien dan keluarga", "Kurangnya tilikan, gangguan psikotik, atau penyalahgunaan zat"]], "doc": "Autoanamnesis & alloanamnesis (ibu kandung, reliabilitas baik). Keluhan utama: … RPS: … Risiko bunuh diri: tidak ada ide/rencana.", "key": ["Pertanyaan terbuka lalu tertutup", "Selalu tanyakan risiko bunuh diri", "Catat sumber anamnesis"], "tips": [], "dz": ["depresi", "skizofrenia"]},
	{"id": "status-mental-a", "g": "psikiatri", "name": "Status mental: penampilan, kesadaran, perilaku, orientasi & persepsi", "sk": [86, 87, 88, 89, 93, 94], "goal": "Mendeskripsikan status mental secara sistematis — bagian penampilan, kesadaran, psikomotor, orientasi, dan persepsi.", "tools": [], "prep": [], "steps": [["Deskripsi umum", "Penampilan (usia tampak, kerapian, pakaian, kebersihan), sikap terhadap pemeriksa (kooperatif, curiga, bermusuhan), kontak mata, perilaku dan aktivitas psikomotor."], ["Kesadaran", "Kesadaran neurologis (kompos mentis/berkabut/delirium) dan kesadaran psikiatrik (berubah/tidak terganggu)."], ["Psikomotor", "Normoaktif, hipoaktif (retardasi), hiperaktif (agitasi), katatonia, stereotipi, manerisme, tik, ekhopraksia."], ["Pengendalian impuls", "Kemampuan menahan dorongan agresif/seksual selama wawancara; riwayat amuk atau mencederai."], ["Orientasi", "Waktu, tempat, dan orang."], ["Persepsi", "Halusinasi (auditorik, visual, taktil, olfaktorius, gustatorik), ilusi, depersonalisasi, derealisasi. Tanyakan: \"Pernahkah mendengar suara yang orang lain tidak dengar?\""]], "normal": ["Penampilan sesuai usia, rapi, kooperatif, kesadaran jernih, psikomotor normoaktif, orientasi baik, halusinasi/ilusi tidak ada, impuls terkendali."], "abn": [["Halusinasi auditorik (suara mengomentari/berdiskusi)", "Skizofrenia/psikosis"], ["Halusinasi visual + disorientasi + fluktuatif", "Delirium/gangguan mental organik"], ["Halusinasi taktil (serangga merayap)", "Putus alkohol, intoksikasi kokain/amfetamin"], ["Agitasi psikomotor", "Mania, psikosis akut, intoksikasi, delirium"], ["Retardasi psikomotor", "Depresi berat, katatonia"], ["Impuls buruk, agresif", "Risiko kekerasan — keamanan petugas & pasien"]], "doc": "Penampilan: laki-laki tampak sesuai usia, rapi, kooperatif, kontak mata adekuat. Kesadaran: kompos mentis, tidak terganggu. Psikomotor: normoaktif. Orientasi baik. Persepsi: halusinasi (−), ilusi (−). Pengendalian impuls baik.", "key": ["Deskripsi objektif tanpa interpretasi", "Tanyakan halusinasi secara langsung namun empatik"], "tips": [], "dz": ["skizofrenia", "delirium"]},
	{"id": "status-mental-b", "g": "psikiatri", "name": "Status mental: mood-afek, proses & isi pikir, intelegensi, daya nilai & tilikan", "sk": [90, 91, 92, 95, 96], "goal": "Menilai mood-afek, bentuk-arus-isi pikir, fungsi intelektual, daya nilai realitas, dan tilikan.", "tools": [], "prep": [], "steps": [["Mood & afek", "Mood = perasaan yang dilaporkan pasien (\"bagaimana perasaan Anda?\"); afek = ekspresi yang diamati (luas, menyempit, tumpul, datar, labil) dan keserasiannya."], ["Bentuk pikir", "Realistik vs nonrealistik/autistik."], ["Arus pikir", "Koheren, asosiasi longgar, inkoherensi, flight of ideas, sirkumstansial, tangensial, blocking, neologisme."], ["Isi pikir", "Waham (kebesaran, kejar, rujukan, kendali, siar pikir, sisip pikir), obsesi, fobia, preokupasi, ide bunuh diri."], ["Intelegensi klinis", "Pengetahuan umum sesuai pendidikan, berhitung sederhana, pikiran abstrak (arti peribahasa, persamaan benda)."], ["Daya nilai (judgement)", "Sosial dan uji realitas: \"apa yang Anda lakukan bila menemukan dompet di jalan?\"; kemampuan membedakan fantasi dan kenyataan."], ["Tilikan (insight)", "Derajat 1–6: 1 menyangkal sakit total … 4 sadar sakit tetapi menyalahkan faktor luar … 6 tilikan emosional sejati (sadar dan mau berubah)."]], "normal": ["Mood eutimik, afek luas serasi, bentuk pikir realistik, arus koheren, waham (−), intelegensi sesuai pendidikan, daya nilai baik, tilikan derajat 6."], "abn": [["Mood depresif + afek menyempit + ide bunuh diri", "Episode depresi — nilai risiko bunuh diri"], ["Mood elasi/iritabel + flight of ideas + waham kebesaran", "Episode manik (bipolar)"], ["Waham kejar/kendali + asosiasi longgar + afek tumpul", "Skizofrenia"], ["Pikiran obsesif + kompulsi yang disadari tidak masuk akal", "Gangguan obsesif-kompulsif"], ["Uji realitas terganggu (RTA terganggu)", "Psikotik"], ["Tilikan 1–2", "Risiko ketidakpatuhan terapi — libatkan keluarga"]], "doc": "Mood eutimik, afek luas-serasi. Proses pikir: bentuk realistik, arus koheren, isi: waham (−), ide bunuh diri (−). Intelegensi sesuai pendidikan. Daya nilai sosial & uji realitas baik. Tilikan derajat 6.", "key": ["Bedakan mood (subjektif) dan afek (objektif)", "Sebut jenis waham spesifik", "Nilai tilikan dengan derajat"], "tips": [], "dz": ["depresi", "skizofrenia", "bipolar"]},
	{"id": "visus", "g": "mata", "name": "Tajam penglihatan & refraksi subjektif", "sk": [126, 128], "goal": "Mengukur tajam penglihatan jauh tiap mata dan mengoreksi kelainan refraksi secara subjektif.", "tools": ["Kartu Snellen (6 m) atau E-chart", "Penutup mata (okluder)", "Pinhole", "Trial lens set"], "prep": ["Ruangan cukup terang, pasien duduk 6 m dari kartu (atau 3 m dengan cermin)"], "steps": [["Periksa per mata", "Tutup mata kiri, periksa mata kanan dahulu (OD), lalu OS; pasien memakai kacamata jarak jauh bila punya (catat cc/sc)."], ["Baca dari atas", "Turun sampai baris terkecil yang masih terbaca ≥ setengah hurufnya. Catat sebagai 6/x."], ["Bila < 6/60", "Hitung jari pada jarak 1–5 m (1/60–5/60); goyangan tangan 1 m (1/300); persepsi cahaya dengan proyeksi (1/~ PS+ proyeksi baik); tidak ada persepsi cahaya (0)."], ["Pinhole", "Bila visus < 6/6, ulangi dengan pinhole. Membaik = kelainan refraksi; tidak membaik = kelainan organik."], ["Refraksi subjektif", "Mulai lensa sferis +0,50: lebih kabur → coba minus bertahap (miopia, ambil minus terkecil dengan visus terbaik); lebih jelas → plus terbesar (hipermetropia). Silinder bila belum 6/6 (gambar kipas/astigmat dial)."], ["Presbiopia", "Usia ≥ 40 tahun: uji baca dekat 33 cm (kartu Jaeger), tambah adisi +1,00 (40 th) sampai +3,00 (≥ 60 th)."]], "normal": ["Visus 6/6 ODS tanpa koreksi."], "abn": [["Visus membaik dengan pinhole", "Kelainan refraksi (miopia, hipermetropia, astigmatisme)"], ["Visus tidak membaik dengan pinhole", "Kelainan media/retina/saraf (katarak, retinopati, glaukoma, neuritis optik) — rujuk"], ["Penurunan visus mendadak tanpa nyeri", "Oklusi arteri/vena retina, ablasio retina, perdarahan vitreus — rujuk segera"], ["Penurunan visus + mata merah + nyeri", "Glaukoma akut, uveitis, keratitis — rujuk segera"]], "doc": "VOD 6/6, VOS 6/12 PH 6/6 → koreksi S −0,75 → 6/6.", "key": ["Periksa per mata, kanan dahulu", "Gunakan pinhole bila < 6/6", "Miopia: minus terkecil", "hipermetropia: plus terbesar"], "tips": ["Visus < 6/18 pada mata terbaik = low vision", "< 3/60 = buta (WHO)"], "dz": ["kelainan-refraksi", "katarak-senilis", "presbiopia"]},
	{"id": "visus-anak", "g": "mata", "name": "Penilaian penglihatan bayi & anak", "sk": [127], "goal": "Menyaring gangguan penglihatan dan ambliopia pada bayi dan anak sesuai usia.", "tools": ["Senter", "Mainan berwarna", "Kartu E/Lea symbols/HOTV", "Oftalmoskop"], "prep": [], "steps": [["Bayi < 3 bulan", "Refleks berkedip terhadap cahaya; menatap wajah; refleks merah (red reflex) dengan oftalmoskop dari 50 cm."], ["3–6 bulan", "Fiksasi dan mengikuti mainan (fix and follow) ke kanan-kiri; tutup satu mata — bayi menolak/menangis bila mata yang sehat ditutup (curiga ambliopia sisi lain)."], ["6–36 bulan", "Mengambil benda kecil (manik-manik), Hirschberg untuk strabismus, cover test."], ["≥ 3 tahun", "Kartu E tumbling/Lea/HOTV dengan cara mencocokkan; per mata."], ["Usia sekolah", "Snellen standar."]], "normal": ["Fix & follow baik per mata, red reflex simetris, ortoforia", "visus sesuai usia (3 th ±6/12, ≥ 5–6 th 6/6)."], "abn": [["Leukokoria (refleks putih)", "Retinoblastoma, katarak kongenital — rujuk segera"], ["Red reflex asimetris", "Katarak, strabismus, anisometropia"], ["Menolak bila satu mata ditutup", "Ambliopia/penurunan visus mata yang lain"], ["Nistagmus pada bayi", "Gangguan penglihatan berat sejak lahir — rujuk"]], "doc": "Red reflex (+) simetris, fix & follow (+) ODS, Hirschberg simetris.", "key": ["Teknik sesuai usia", "Red reflex wajib pada bayi"], "tips": [], "dz": ["ambliopia", "katarak-kongenital", "retinoblastoma"]},
	{"id": "lapang-pandang", "g": "mata", "name": "Lapang pandang (konfrontasi & Amsler grid)", "sk": [131, 132], "goal": "Menyaring defek lapang pandang perifer dan sentral.", "tools": ["Benda kecil berwarna merah/jari", "Amsler grid"], "prep": [], "steps": [["Posisi", "Duduk berhadapan sejajar ±1 m (lengan rentang); pasien menutup mata kiri, pemeriksa menutup mata kanan (mata berhadapan)."], ["Konfrontasi", "Gerakkan jari dari perifer ke tengah di 4 kuadran (di bidang antara pemeriksa-pasien); pasien menyebut saat pertama kali melihat. Bandingkan dengan lapang pandang pemeriksa."], ["Hitung jari per kuadran", "Tunjukkan 1, 2, atau 5 jari di tiap kuadran."], ["Desaturasi merah", "Bandingkan warna benda merah di tiap kuadran/antar mata (lesi n. optikus tampak pucat)."], ["Amsler grid", "Kartu kotak 10 × 10 cm pada jarak baca 30 cm, satu mata, menatap titik tengah. Tanyakan garis bergelombang (metamorfopsia) atau hilang (skotoma)."]], "normal": ["Lapang pandang sama dengan pemeriksa di keempat kuadran", "Amsler: garis lurus, tidak ada yang hilang."], "abn": [["Hemianopia bitemporal", "Lesi kiasma optikum (adenoma hipofisis)"], ["Hemianopia homonim", "Lesi traktus/radiasi optika/korteks oksipital kontralateral (stroke)"], ["Kuadranopia homonim atas", "Lesi lobus temporal (Meyer's loop)"], ["Penyempitan lapang pandang perifer (tunnel)", "Glaukoma lanjut, retinitis pigmentosa"], ["Metamorfopsia pada Amsler", "Kelainan makula (degenerasi makula, edema makula)"]], "doc": "Lapang pandang konfrontasi ODS sama dengan pemeriksa; Amsler grid normal.", "key": ["Mata yang berhadapan (OD pasien dengan OS pemeriksa)", "Objek di bidang tengah", "Uji 4 kuadran per mata"], "tips": [], "dz": ["glaukoma-kronik", "stroke-iskemik"]},
	{"id": "adneksa-mata", "g": "mata", "name": "Kelopak, bulu mata, konjungtiva, sklera & duktus lakrimal (termasuk eversi kelopak)", "sk": [133, 134, 135, 136, 137, 138, 139], "goal": "Memeriksa adneksa dan permukaan mata depan, termasuk mencari benda asing di bawah kelopak atas.", "tools": ["Senter", "Lidi kapas", "Lup", "Sarung tangan"], "prep": [], "steps": [["Kelopak", "Posisi (ptosis, retraksi, entropion, ektropion), edema, massa (hordeolum, kalazion), lagoftalmus."], ["Bulu mata", "Trikiasis (mengarah ke kornea), distikiasis, krusta/skuama (blefaritis), kutu (ftiriasis)."], ["Konjungtiva palpebra & forniks inferior", "Tarik kelopak bawah ke bawah sambil pasien melihat ke atas: pucat (anemia), papil, folikel, sekret, benda asing."], ["Eversi kelopak atas", "Pasien melihat ke bawah; pegang bulu mata atas, letakkan lidi kapas di batas atas tarsus (±1 cm dari tepi), balik kelopak ke atas. Periksa konjungtiva tarsal superior (papil raksasa, benda asing, sikatriks trakoma)."], ["Konjungtiva bulbi & sklera", "Injeksi konjungtiva (merah di perifer, bergerak) vs injeksi silier (merah melingkar di limbus); perdarahan subkonjungtiva; pterigium; sklera ikterik/biru."], ["Duktus lakrimal", "Inspeksi punktum; tekan sakus lakrimal di kantus medial — keluar sekret/pus = dakriosistitis/obstruksi."], ["KGB preaurikular", "Raba di depan tragus."]], "normal": ["Kelopak & bulu mata normal, konjungtiva tidak hiperemis/anemis, sklera putih tidak ikterik, punktum normal, regurgitasi sakus (−), KGB preaurikular tidak teraba."], "abn": [["Injeksi konjungtiva + sekret purulen", "Konjungtivitis bakteri"], ["Folikel + sekret serus + KGB preaurikular membesar", "Konjungtivitis virus (adenovirus)"], ["Papil raksasa tarsal superior + gatal", "Konjungtivitis vernal (alergi)"], ["Injeksi silier (limbus)", "Keratitis, uveitis anterior, glaukoma akut — rujuk"], ["Benjolan nyeri di tepi kelopak", "Hordeolum; tidak nyeri, lebih dalam => Kalazion"], ["Regurgitasi pus dari punktum", "Dakriosistitis"], ["Sklera ikterik", "Hiperbilirubinemia (> 2–3 mg/dL)"], ["Konjungtiva anemis", "Anemia"]], "doc": "Palpebra edema (−), konjungtiva anemis (−), hiperemis (−), sklera ikterik (−), sekret (−), regurgitasi sakus lakrimal (−).", "key": ["Eversi kelopak atas dengan benar (pasien melihat ke bawah)", "Bedakan injeksi konjungtiva dan silier"], "tips": [], "dz": ["konjungtivitis", "hordeolum", "kalazion", "dakriosistitis"]},
	{"id": "segmen-anterior", "g": "mata", "name": "Kornea, bilik mata depan, iris & lensa (termasuk fluoresein & sensitivitas kornea)", "sk": [146, 147, 148, 149, 150, 151, 152], "goal": "Menilai segmen anterior bola mata dengan senter/lup dan tes fluoresein.", "tools": ["Senter", "Lup/loupe binokular", "Strip fluoresein", "Lampu biru kobalt", "Lidi kapas"], "prep": [], "steps": [["Kornea", "Kejernihan, kilau, defek, infiltrat, ulkus, benda asing, sikatriks (nebula-makula-leukoma), arkus senilis. Senter dari samping (iluminasi oblik)."], ["Uji fluoresein", "Basahi strip dengan saline, sentuhkan ke forniks inferior, minta berkedip; lihat dengan lampu biru. Area hijau = defek epitel (erosi/ulkus); pola dendritik = herpes simpleks."], ["Sensitivitas kornea", "Sentuh kornea dengan kapas dipilin tanpa disadari pasien; bandingkan kedua mata (menurun pada keratitis herpes/neurotropik)."], ["Bilik mata depan (BMD)", "Kedalaman dengan senter dari temporal sejajar iris — bayangan di iris nasal = BMD dangkal; isi: hipopion (pus), hifema (darah)."], ["Iris", "Warna, pola kripta, sinekia, iridodonesis, rubeosis."], ["Lensa", "Jernih atau keruh (katarak); shadow test (bayangan iris pada lensa) positif = katarak imatur, negatif = matur/jernih."]], "normal": ["Kornea jernih, fluoresein (−), BMD dalam, jernih, iris normal, pupil bulat, lensa jernih."], "abn": [["Fluoresein dendritik", "Keratitis herpes simpleks — jangan beri steroid"], ["Ulkus kornea + hipopion", "Keratitis/ulkus bakteri/jamur — rujuk segera"], ["Hifema", "Trauma tumpul — tirah baring posisi kepala 30°, rujuk"], ["BMD dangkal + pupil lebar lonjong + kornea keruh + nyeri", "Glaukoma sudut tertutup akut — rujuk darurat"], ["Shadow test (+)", "Katarak imatur"], ["Lensa putih, shadow test (−)", "Katarak matur"]], "doc": "Kornea jernih, fluoresein (−); BMD dalam, hifema (−), hipopion (−); iris coklat, kripta (+); pupil bulat RC (+); lensa jernih, shadow test (−).", "key": ["Iluminasi oblik untuk kornea dan kedalaman BMD", "Teknik fluoresein dan interpretasi pola"], "tips": [], "dz": ["keratitis", "katarak-senilis", "glaukoma-akut", "hifema"]},
	{"id": "kedudukan-bola-mata", "g": "mata", "name": "Kedudukan bola mata (Hirschberg & cover-uncover)", "sk": [140, 141], "goal": "Mendeteksi strabismus (manifes dan laten).", "tools": ["Senter", "Okluder", "Objek fiksasi"], "prep": [], "steps": [["Hirschberg", "Senter dipegang 33 cm di depan pasien, pasien menatap cahaya. Normal: refleks kornea di tengah pupil kedua mata (sedikit nasal). Pergeseran 1 mm ≈ 7° (≈ 15 prisma dioptri)."], ["Cover test (tropia)", "Pasien fiksasi objek; tutup satu mata dan amati mata yang TIDAK ditutup. Bergerak untuk mengambil fiksasi = strabismus manifes (tropia)."], ["Uncover test (foria)", "Tutup satu mata beberapa detik, buka, amati mata yang baru dibuka. Bergerak kembali ke posisi = foria (laten)."], ["Alternate cover", "Tutup bergantian cepat kanan-kiri untuk menampakkan deviasi total."]], "normal": ["Refleks kornea simetris di tengah, cover-uncover tanpa gerakan (ortoforia)."], "abn": [["Refleks kornea di temporal pupil", "Esotropia (mata ke dalam)"], ["Refleks kornea di nasal jauh", "Eksotropia (mata ke luar)"], ["Strabismus pada anak", "Risiko ambliopia — rujuk dini"], ["Strabismus akut pada dewasa + diplopia", "Paresis saraf kranial (III, IV, VI)"]], "doc": "Hirschberg: ortoforia; cover-uncover test: tidak ada gerakan.", "key": ["Jarak senter 33 cm", "Amati mata yang tidak ditutup pada cover test"], "tips": [], "dz": ["strabismus", "ambliopia"]},
	{"id": "funduskopi", "g": "mata", "name": "Funduskopi (oftalmoskopi direk)", "sk": [9, 154, 155], "goal": "Menilai refleks fundus, papil saraf optik, pembuluh darah retina, dan makula.", "tools": ["Oftalmoskop direk", "(bila perlu) midriatikum tropikamid 1% setelah menyingkirkan risiko sudut tertutup"], "prep": ["Ruangan gelap", "pasien menatap titik jauh di depan, tidak boleh bergerak"], "steps": [["Pegang & posisi", "Mata kanan pasien: oftalmoskop di tangan kanan, mata kanan pemeriksa (sebaliknya untuk mata kiri). Lensa 0."], ["Refleks fundus", "Dari jarak ±30–50 cm, lihat ke pupil: refleks merah-oranye homogen. Bercak gelap = kekeruhan media (katarak, vitreus)."], ["Mendekat 15° temporal", "Mendekat hingga ±3 cm sambil mengikuti refleks; putar lensa untuk fokus pembuluh darah."], ["Papil (diskus optikus)", "Ikuti pembuluh ke arah pertemuannya: batas tegas, warna oranye-merah muda, rasio cup-disc (C/D) normal ≤ 0,5."], ["Pembuluh darah", "Rasio arteri:vena ±2:3, persilangan AV (nicking), refleks cahaya arteri, perdarahan, eksudat, mikroaneurisma, cotton wool spot."], ["Makula", "Minta pasien melihat langsung ke cahaya sebentar; makula lebih gelap dengan refleks fovea."]], "normal": ["Refleks fundus (+), papil batas tegas, warna normal, C/D 0,3, a:v 2:3, perdarahan/eksudat (−), refleks makula (+)."], "abn": [["Papiledema (batas papil kabur, menonjol, pulsasi vena hilang) bilateral", "Peningkatan TIK — rujuk segera"], ["C/D > 0,6 atau asimetri > 0,2", "Glaukoma"], ["Papil pucat (atrofi optik)", "Neuritis optik lama, glaukoma, kompresi"], ["AV nicking, copper/silver wiring, perdarahan flame-shaped", "Retinopati hipertensi"], ["Mikroaneurisma, dot-blot hemorrhage, eksudat keras, neovaskularisasi", "Retinopati diabetik"], ["Retina pucat + cherry red spot makula", "Oklusi a. sentralis retina — kegawatan"], ["Perdarahan luas \"blood and thunder\"", "Oklusi v. sentralis retina"], ["Refleks fundus hilang/putih", "Katarak matur, perdarahan vitreus, ablasio, retinoblastoma (anak)"]], "doc": "Funduskopi ODS: refleks fundus (+), papil N. II bulat batas tegas, warna normal, C/D 0,3, a:v 2:3, perdarahan (−), eksudat (−), refleks makula (+).", "key": ["Tangan dan mata pemeriksa sama dengan mata pasien yang diperiksa", "Urutan refleks fundus → papil → pembuluh → makula"], "tips": ["Midriatikum memudahkan tetapi kontraindikasi pada sudut BMD dangkal dan pasien neurologis yang pupilnya perlu dipantau"], "dz": ["retinopati-diabetik", "retinopati-hipertensi", "glaukoma-kronik", "papiledema"]},
	{"id": "tio", "g": "mata", "name": "Tekanan intraokular (palpasi & tonometri Schiøtz)", "sk": [156, 157], "goal": "Memperkirakan dan mengukur tekanan intraokular (TIO) untuk deteksi glaukoma.", "tools": ["Tonometer Schiøtz dengan beban 5,5/7,5/10 g", "Tetes anestesi lokal (pantokain/tetrakain 0,5%)", "Alkohol swab", "Tabel konversi", "Antibiotik tetes"], "prep": [], "steps": [["Palpasi (digital)", "Pasien melihat ke bawah (mata tertutup); kedua jari telunjuk bergantian menekan lembut bola mata melalui kelopak atas di atas tarsus. Bandingkan kedua mata dan dengan TIO normal pemeriksa: N, N+1, N+2, N−1."], ["Persiapan Schiøtz", "Kalibrasi pada blok uji (jarum menunjuk 0), desinfeksi kaki tonometer, teteskan anestesi 2 kali."], ["Posisi", "Pasien berbaring terlentang, menatap ibu jarinya sendiri yang diangkat lurus di atas (kornea horizontal)."], ["Pengukuran", "Buka kelopak tanpa menekan bola mata, letakkan kaki tonometer tegak lurus di tengah kornea, baca skala. Bila skala < 3, tambah beban."], ["Konversi", "Gunakan tabel Friedenwald (skala + beban → mmHg). Beri antibiotik tetes setelah pemeriksaan."]], "normal": ["Palpasi N/N", "TIO 10–21 mmHg."], "abn": [["TIO > 21 mmHg", "Hipertensi okular/glaukoma — nilai papil dan lapang pandang"], ["Mata keras seperti batu + merah + nyeri + mual", "Glaukoma sudut tertutup akut — rujuk darurat"], ["Mata lunak (N−) pasca trauma", "Ruptur bola mata — jangan tekan, lindungi & rujuk"]], "doc": "TIO palpasi N/N; Schiøtz OD 5/5,5 g (17,3 mmHg), OS 5/5,5 g (17,3 mmHg).", "key": ["Jangan menekan bola mata saat membuka kelopak", "Kornea harus horizontal", "Kontraindikasi: ulkus kornea, infeksi, trauma tembus"], "tips": [], "dz": ["glaukoma-kronik", "glaukoma-akut"]},
	{"id": "ishihara", "g": "mata", "name": "Tes penglihatan warna (Ishihara)", "sk": [167], "goal": "Menyaring defisiensi penglihatan warna merah-hijau.", "tools": ["Buku Ishihara (12/24/38 plate)"], "prep": ["Pencahayaan siang hari alami/lampu daylight", "jarak ±75 cm", "kacamata baca dipakai bila perlu"], "steps": [["Plate demonstrasi", "Plate 1 (angka 12) dapat dibaca oleh semua orang termasuk buta warna — bila tidak terbaca, curigai visus sangat buruk/pura-pura."], ["Baca tiap plate", "Maksimal 3 detik per plate, tiap mata atau kedua mata."], ["Plate tracing", "Untuk yang tidak bisa membaca angka (anak), minta menelusuri garis."], ["Interpretasi", "Jumlah plate benar dibandingkan lembar kunci; plate diagnostik membedakan protan dan deutan."]], "normal": ["Semua plate (12/12 atau ≥ 13/14 pada 24 plate) terbaca benar."], "abn": [["Plate merah-hijau salah sesuai pola", "Defisiensi warna kongenital (protan/deutan), X-linked, terutama pria"], ["Defisiensi warna didapat, unilateral", "Neuritis optik, toksisitas obat (etambutol, hidroksiklorokuin)"]], "doc": "Tes Ishihara 12 plate: 12/12 benar ODS, kesan normal.", "key": ["Pencahayaan cukup", "Batas waktu 3 detik per plate"], "tips": ["Periksa penglihatan warna sebelum dan selama terapi etambutol"], "dz": ["tbparu"]},
	{"id": "otoskopi", "g": "tht", "name": "Telinga luar & membran timpani (otoskopi, lampu kepala)", "sk": [173, 174, 175], "goal": "Memeriksa aurikula, liang telinga, dan membran timpani.", "tools": ["Lampu kepala", "Otoskop dengan spekulum sesuai ukuran", "Spekulum telinga", "Pengait serumen/kapas lidi"], "prep": ["Pasang lampu kepala: fokus cahaya ±30 cm di depan, sejajar mata pemeriksa", "pasien duduk menyamping, kepala sejajar mata pemeriksa"], "steps": [["Inspeksi & palpasi aurikula", "Bentuk, radang, fistel preaurikular, nyeri tarik aurikula/tekan tragus, nyeri tekan mastoid, KGB retroaurikular."], ["Luruskan liang telinga", "Dewasa: tarik aurikula ke atas-belakang; anak/bayi: ke bawah-belakang."], ["Pegang otoskop", "Seperti memegang pena, tangan pemeriksa bertumpu di pipi pasien (aman bila pasien bergerak); tangan kanan untuk telinga kanan."], ["Liang telinga", "Serumen (obturans?), sekret (warna, bau), edema, furunkel, jamur (spora putih/hitam), benda asing."], ["Membran timpani (MT)", "Warna putih mutiara, refleks cahaya (arah jam 5 di kanan, jam 7 di kiri), manubrium maleus, pars tensa & flaksida, perforasi (sentral/marginal/atik), retraksi, bulging, cairan/bubble."]], "normal": ["Aurikula normal, liang lapang, serumen minimal, MT intak putih mengkilat, refleks cahaya (+)."], "abn": [["Nyeri tarik aurikula + liang edema", "Otitis eksterna"], ["MT hiperemis, bulging, refleks cahaya hilang", "Otitis media akut stadium supurasi"], ["MT retraksi, air-fluid level/bubble", "Otitis media efusi"], ["Perforasi sentral + sekret mukoid", "OMSK tipe aman (benigna)"], ["Perforasi atik/marginal + kolesteatoma + sekret berbau", "OMSK tipe bahaya — rujuk"], ["Nyeri tekan & bengkak di belakang telinga, aurikula terdorong", "Mastoiditis — rujuk segera"], ["Spora hitam/putih seperti kertas basah", "Otomikosis"]], "doc": "Aurikula normal, nyeri tarik (−), tragus pain (−). CAE lapang, serumen (−), sekret (−). MT intak, refleks cahaya (+) arah jam 5 (AD) / jam 7 (AS).", "key": ["Arah tarik aurikula sesuai usia", "Tangan bertumpu di pipi pasien", "Deskripsi MT lengkap"], "tips": [], "dz": ["otitis-eksterna", "oma", "omsk", "serumen"]},
	{"id": "garpu-tala", "g": "tht", "name": "Tes pendengaran: garpu tala (Rinne, Weber, Schwabach) & tes berbisik", "sk": [15, 176, 177], "goal": "Menentukan ada tidaknya gangguan dengar dan membedakan tuli konduktif dan sensorineural.", "tools": ["Garpu tala 512 Hz (atau 256/1024 Hz)"], "prep": ["Ruangan tenang", "pastikan liang telinga tidak tertutup serumen"], "steps": [["Getarkan garpu tala", "Pukul ringan ujungnya pada siku/lutut atau karet (jangan benda keras)."], ["Rinne", "Tangkai ditempel di prosesus mastoid sampai bunyi tidak terdengar, lalu ujung garpu tala dipindah ±2,5 cm di depan liang telinga. Masih terdengar = Rinne positif (AC > BC, normal/sensorineural); tidak terdengar = Rinne negatif (konduktif)."], ["Weber", "Tangkai di garis tengah dahi/verteks/gigi seri; tanyakan bunyi lebih keras di telinga mana. Lateralisasi ke telinga sakit = konduktif; ke telinga sehat = sensorineural."], ["Schwabach", "Tangkai di mastoid pasien sampai tidak terdengar, segera pindah ke mastoid pemeriksa (yang normal). Pemeriksa masih mendengar = Schwabach memendek (sensorineural); dibalik (pemeriksa dulu) pasien masih mendengar = memanjang (konduktif)."], ["Tes berbisik", "Pemeriksa di belakang/samping pasien (cegah membaca bibir), telinga lain ditutup dan digesek (masking). Bisikan kata 2 suku setelah ekspirasi normal dari jarak 6 m, mendekat bila tidak terdengar."]], "normal": ["Rinne (+) kedua telinga, Weber tidak ada lateralisasi, Schwabach sama dengan pemeriksa", "tes berbisik terdengar ≥ 6 m."], "abn": [["Rinne (−), Weber lateralisasi ke telinga sakit, Schwabach memanjang", "Tuli konduktif (serumen, otitis media, perforasi, otosklerosis)"], ["Rinne (+), Weber lateralisasi ke telinga sehat, Schwabach memendek", "Tuli sensorineural (presbikusis, bising, ototoksik, Ménière, neuroma akustik)"], ["Tuli sensorineural mendadak unilateral", "Kegawatan THT — rujuk segera (steroid dalam 72 jam)"], ["Tes berbisik 1–4 m", "Tuli sedang; < 1 m => tuli berat"]], "doc": "Rinne +/+, Weber tidak ada lateralisasi, Schwabach sama dengan pemeriksa. Tes berbisik 6 m/6 m. Kesan: pendengaran normal.", "key": ["Tangkai di mastoid lalu ujung di depan liang telinga (Rinne)", "Interpretasi kombinasi 3 tes", "Masking telinga yang tidak diperiksa saat tes berbisik"], "tips": ["Audiometri nada murni (SKDI 3) untuk konfirmasi derajat ketulian"], "dz": ["presbiakusis", "tuli-mendadak", "serumen"]},
	{"id": "dengar-anak", "g": "tht", "name": "Pemeriksaan pendengaran pada anak", "sk": [179], "goal": "Menyaring gangguan pendengaran sejak dini agar intervensi sebelum usia 6 bulan.", "tools": ["Mainan berbunyi (kerincingan, bel) frekuensi berbeda", "Otoskop"], "prep": [], "steps": [["Tanyakan faktor risiko", "Riwayat keluarga, infeksi TORCH, BBLR/asfiksia, hiperbilirubinemia berat, meningitis, obat ototoksik, kelainan kraniofasial."], ["Bayi 0–4 bulan", "Refleks kaget (Moro) atau berkedip (auropalpebral) terhadap bunyi keras."], ["4–7 bulan", "Menoleh ke arah sumber bunyi di samping (setinggi telinga)."], ["7–12 bulan", "Melokalisasi bunyi dari samping dan bawah; mengoceh dan meniru suara."], ["Balita", "Mengikuti perintah tanpa isyarat; perkembangan bicara sesuai usia (kata pertama ±12 bulan, kalimat 2 kata ±24 bulan)."], ["Rujuk skrining objektif", "OAE (otoacoustic emission) atau BERA pada semua bayi baru lahir/berisiko."]], "normal": ["Respons terhadap bunyi sesuai usia", "perkembangan bahasa sesuai."], "abn": [["Tidak menoleh terhadap bunyi pada usia 6 bulan", "Curiga gangguan dengar — rujuk OAE/BERA"], ["Keterlambatan bicara", "Selalu periksa pendengaran"]], "doc": "Anak menoleh ke arah bunyi kanan & kiri; MT intak ADS. Kesan: tidak ada gangguan dengar.", "key": ["Bunyi di luar lapang pandang anak", "Tanyakan faktor risiko"], "tips": [], "dz": ["tuli-kongenital"]},
	{"id": "hidung", "g": "tht", "name": "Hidung & sinus paranasal (inspeksi, palpasi wajah, obstruksi, rinoskopi anterior, transiluminasi)", "sk": [184, 185, 186, 187, 188, 189, 191, 192], "goal": "Menilai hidung luar, rongga hidung anterior, dan sinus paranasal.", "tools": ["Lampu kepala", "Spekulum hidung (Hartmann)", "Senter kecil", "Spatel/kaca dingin"], "prep": [], "steps": [["Inspeksi luar", "Bentuk (deviasi, saddle nose), deformitas, hematoma, krusta, vestibulum (furunkel)."], ["Palpasi", "Tulang nasal (krepitasi, nyeri, mobilitas fraktur), zigoma, maksila, mandibula (step-off, maloklusi), nyeri tekan sinus frontal, maksila, etmoid (kantus medial)."], ["Obstruksi hidung", "Tutup satu lubang hidung, minta menghirup; atau kaca/spatel logam dingin di bawah hidung — luas embun kanan vs kiri."], ["Rinoskopi anterior", "Spekulum dipegang tangan kiri (paruh ditutup saat masuk/keluar), dimasukkan horizontal ±1 cm, buka arah atas-bawah. Kepala pasien posisi 1 (lurus) lihat dasar & konka inferior; posisi 2 (tengadah) lihat konka media & meatus media."], ["Nilai rongga hidung", "Mukosa (merah muda/livid/hiperemis), sekret (serus, mukopurulen, lokasi di meatus media), konka (eutrofi/hipertrofi), septum (deviasi, perforasi, perdarahan di Little's area), massa (polip pucat bertangkai, tumor)."], ["Transiluminasi", "Ruangan gelap; senter di bawah alis medial (frontal) dan di dalam mulut di palatum (maksila, mulut ditutup). Bandingkan terang kanan-kiri."]], "normal": ["Hidung luar normal, deformitas (−), nyeri tekan sinus (−), cavum nasi lapang, mukosa merah muda, sekret (−), konka eutrofi, septum di tengah, transiluminasi terang simetris."], "abn": [["Konka livid pucat + sekret serus", "Rinitis alergi"], ["Massa pucat, bertangkai, tidak nyeri, tidak berdarah saat disentuh", "Polip nasi"], ["Sekret mukopurulen di meatus media + nyeri tekan pipi", "Rinosinusitis maksila"], ["Transiluminasi gelap unilateral", "Sinusitis (cairan/penebalan mukosa)"], ["Krepitasi/deformitas tulang hidung pasca trauma", "Fraktur os nasal"], ["Pembengkakan septum fluktuatif pasca trauma", "Hematoma septum — drainase segera (risiko saddle nose)"], ["Perdarahan dari Little's area", "Epistaksis anterior"], ["Massa rapuh berdarah unilateral pada dewasa", "Curiga keganasan (karsinoma nasofaring/sinonasal) — rujuk"]], "doc": "Hidung luar normal; NT sinus (−). Rinoskopi anterior: cavum nasi lapang/lapang, mukosa merah muda, sekret (−), konka inferior eutrofi, septum deviasi (−), massa (−). Transiluminasi terang simetris.", "key": ["Paruh spekulum ditutup saat keluar (jangan menjepit bulu hidung)", "Dua posisi kepala", "Deskripsi konka, septum, sekret, massa"], "tips": [], "dz": ["rinitis-alergi", "rinosinusitis-kronik", "rinosinusitis-akut", "epistaksis", "fraktur-nasal"]},
	{"id": "orofaring", "g": "tht", "name": "Rongga mulut, tonsil & orofaring", "sk": [238, 319, 320], "goal": "Memeriksa bibir, rongga mulut, tonsil, dan dinding faring.", "tools": ["Lampu kepala/senter", "Spatel lidah", "Sarung tangan"], "prep": [], "steps": [["Bibir & mukosa", "Warna (sianosis, pucat), keilitis angularis, stomatitis, sariawan (aftosa), bercak putih (kandidiasis, leukoplakia), bercak Koplik (campak)."], ["Gigi & gusi", "Karies, gigi goyang, abses, gingivitis, hipertrofi gingiva (fenitoin)."], ["Lidah", "Papil (atrofi/glositis), selaput (kotor tifoid), massa/ulkus di tepi lidah."], ["Tekan lidah", "Spatel di 2/3 anterior lidah (jangan terlalu belakang — memicu muntah), minta pasien bernapas lewat mulut/berkata \"aaa\"."], ["Tonsil", "Ukuran (T0–T4: T1 dalam fosa, T2 melewati pilar posterior, T3 mendekati uvula, T4 melewati garis tengah), permukaan (kripta melebar, detritus, membran), warna, simetri."], ["Faring", "Dinding posterior (hiperemis, granular, post-nasal drip), uvula di tengah, abses peritonsil (uvula terdorong)."]], "normal": ["Mukosa merah muda basah, gigi geligi baik, tonsil T1–T1 tenang, faring tidak hiperemis, uvula di tengah."], "abn": [["Tonsil hiperemis membesar + detritus + demam", "Tonsilitis akut bakterial (GAS)"], ["Membran putih keabuan sulit diangkat, berdarah, bull neck", "Difteri — isolasi & rujuk segera"], ["Tonsil membesar asimetris + uvula terdorong + trismus", "Abses peritonsil — rujuk"], ["Kripta melebar, detritus, tonsil membesar berulang", "Tonsilitis kronik"], ["Plak putih dapat dikerok", "Kandidiasis oral (curiga imunosupresi/HIV bila dewasa)"], ["Bercak Koplik (putih di mukosa pipi)", "Campak (prodromal)"], ["Ulkus tidak sembuh > 3 minggu", "Curiga keganasan — biopsi/rujuk"]], "doc": "Mukosa bibir & mulut basah, stomatitis (−). Tonsil T1–T1, hiperemis (−), kripta tidak melebar, detritus (−). Faring hiperemis (−), uvula di tengah.", "key": ["Spatel di 2/3 anterior lidah", "Gradasi ukuran tonsil T0–T4"], "tips": [], "dz": ["faringitis", "difteri", "kandidiasis-oral", "campak"]},
	{"id": "rinoskopi-posterior-laring", "g": "tht", "name": "Rinoskopi posterior & laringoskopi indirek", "sk": [229, 230], "goal": "Melihat nasofaring dan laring dengan cermin.", "tools": ["Lampu kepala", "Kaca nasofaring kecil & kaca laring", "Lampu spiritus/air hangat (cegah embun)", "Spatel", "Kasa", "Semprot anestesi lokal (lidokain 10%) bila refleks muntah kuat"], "prep": [], "steps": [["Hangatkan kaca", "Uji di punggung tangan pemeriksa (tidak terlalu panas)."], ["Rinoskopi posterior", "Tekan lidah dengan spatel, masukkan kaca kecil menghadap atas di belakang uvula tanpa menyentuh dinding; pasien bernapas lewat hidung. Lihat koana, ujung konka, septum posterior, torus tubarius, fossa Rosenmüller, adenoid."], ["Laringoskopi indirek", "Pasien duduk tegak condong ke depan, julurkan lidah; pegang lidah dengan kasa, masukkan kaca laring menghadap ke bawah, tekan uvula ke atas-belakang lembut."], ["Fonasi & respirasi", "Minta pasien berkata \"iii\" (pita suara aduksi) lalu bernapas (abduksi). Nilai epiglotis, valekula, sinus piriformis, aritenoid, plika vokalis (warna, gerak, nodul, massa)."]], "normal": ["Nasofaring bersih, fossa Rosenmüller simetris", "laring: plika vokalis putih, gerak simetris, massa (−)."], "abn": [["Massa di fossa Rosenmüller + KGB leher atas + epistaksis/tuli unilateral", "Curiga karsinoma nasofaring — rujuk"], ["Nodul bilateral di 1/3 anterior-tengah pita suara", "Nodul vokal (penyalahgunaan suara)"], ["Pita suara tidak bergerak sesisi", "Paresis n. laringeus rekuren (tumor paru/tiroid, pasca tiroidektomi)"], ["Massa ireguler di pita suara + suara serak > 3 minggu pada perokok", "Curiga karsinoma laring — rujuk"], ["Adenoid besar menutup koana", "Hipertrofi adenoid"]], "doc": "Rinoskopi posterior: koana bebas, adenoid (−), fossa Rosenmüller simetris. Laringoskopi indirek: epiglotis tenang, plika vokalis putih, gerak simetris, massa (−).", "key": ["Kaca dihangatkan dan diuji", "Tidak menyentuh dinding faring", "Fonasi \"iii\" untuk menilai gerak pita suara"], "tips": [], "dz": ["karsinoma-nasofaring", "laringitis-akut"]},
	{"id": "leher-tiroid", "g": "tht", "name": "Leher & kelenjar tiroid", "sk": [225, 228, 485], "goal": "Menilai massa leher dan kelenjar tiroid (ukuran, konsistensi, nodul, gerak saat menelan) serta tanda hipo/hipertiroid.", "tools": ["Segelas air", "Stetoskop", "Pita ukur"], "prep": [], "steps": [["Inspeksi leher", "Pasien duduk, leher sedikit ekstensi; amati simetri, massa, skar, vena distensi. Minta menelan air — massa tiroid ikut naik; minta menjulurkan lidah — kista duktus tiroglosus ikut naik."], ["Palpasi dari belakang", "Leher sedikit fleksi; tiga jari kedua tangan di kanan-kiri trakea di bawah kartilago krikoid (isthmus), lalu geser ke lateral untuk lobus kanan & kiri sambil pasien menelan."], ["Deskripsi", "Ukuran, difus/nodular (jumlah nodul), konsistensi (lunak/kenyal/keras), nyeri tekan, mobilitas, batas bawah (retrosternal?)."], ["Palpasi dari depan & KGB", "Konfirmasi dari depan; raba KGB servikal."], ["Perkusi & auskultasi", "Perkusi manubrium (pekak = retrosternal); auskultasi bruit di atas tiroid (hipertiroid Graves)."], ["Tanda klinis tiroid", "Tremor halus jari, telapak hangat lembap, takikardia/FA, eksoftalmus, lid lag (hiper); kulit kering kasar, bradikardia, relaksasi refleks lambat (hipo)."], ["Pemberton", "Kedua lengan diangkat ke atas kepala 1 menit — wajah pletorik/sesak = goiter retrosternal menekan pintu atas toraks."]], "normal": ["Tiroid tidak teraba/teraba kecil, lunak, simetris, ikut bergerak saat menelan", "KGB tidak membesar", "trakea di tengah."], "abn": [["Pembesaran difus + bruit + eksoftalmus + takikardia", "Penyakit Graves (hipertiroid)"], ["Nodul soliter keras, terfiksir, KGB membesar, suara serak", "Curiga karsinoma tiroid — rujuk (USG/BAJAH)"], ["Multinodular tanpa gejala tiroid", "Goiter multinodular nontoksik"], ["Nyeri tekan tiroid + demam", "Tiroiditis subakut"], ["Massa garis tengah ikut naik saat lidah dijulurkan", "Kista duktus tiroglosus"], ["Massa lateral di anterior sternokleidomastoideus pada dewasa muda", "Kista brankial"]], "doc": "Leher: simetris, trakea di tengah, JVP tidak meningkat. Tiroid: tidak teraba membesar, nodul (−), ikut bergerak saat menelan, bruit (−). KGB tidak membesar.", "key": ["Palpasi dari belakang sambil pasien menelan", "Deskripsi lengkap nodul", "Periksa tanda status tiroid"], "tips": [], "dz": ["hipertiroid", "hipotiroid", "goiter", "kanker-tiroid"]},
	{"id": "distres-napas", "g": "respirasi", "name": "Penilaian respirasi & tanda distres napas", "sk": [233], "goal": "Menilai frekuensi, pola, dan tanda kerja napas meningkat untuk mengenali gagal napas dini.", "tools": ["Jam", "Oksimeter"], "prep": [], "steps": [["Frekuensi & kedalaman", "Hitung 60 detik; bandingkan dengan nilai normal usia."], ["Tanda distres", "Napas cuping hidung, retraksi (suprasternal, interkostal, subkostal), penggunaan otot bantu (sternokleidomastoideus, skalenus), pursed-lip breathing, posisi tripod."], ["Bunyi napas dari jauh", "Stridor (inspirasi, obstruksi atas), mengi (ekspirasi), grunting (bayi), gurgling (sekret)."], ["Warna & kesadaran", "Sianosis sentral (lidah/bibir), gelisah atau mengantuk (hiperkapnia)."], ["Kemampuan bicara", "Kalimat penuh, frasa, kata, atau tidak bisa bicara."], ["Pada anak", "Tarikan dinding dada bagian bawah ke dalam (TDDK) = pneumonia berat menurut MTBS."]], "normal": ["RR sesuai usia, pola teratur, tidak ada otot bantu, retraksi, atau sianosis", "bicara kalimat penuh."], "abn": [["Stridor saat istirahat", "Obstruksi jalan napas atas (croup, epiglotitis, benda asing) — jangan periksa tenggorok, rujuk"], ["Hanya bicara kata-kata + otot bantu + silent chest", "Asma serangan berat/mengancam nyawa"], ["TDDK pada balita", "Pneumonia berat (MTBS) — rujuk"], ["Grunting pada bayi", "Distres napas berat"], ["Napas cepat + dalam tanpa distres paru", "Kompensasi asidosis metabolik (KAD, syok, uremia)"], ["Mengantuk + RR lambat pada pasien sesak", "Kelelahan/gagal napas hiperkapnia — ventilasi segera"]], "doc": "RR 20 x/menit, regular, retraksi (−), napas cuping hidung (−), otot bantu (−), sianosis (−), bicara kalimat penuh. SpO₂ 97% udara ruang.", "key": ["Hitung napas 60 detik", "Sebutkan tanda distres secara spesifik"], "tips": ["RR normal anak: < 2 bln < 60", "2–12 bln < 50", "1–5 th < 40", "> 5 th < 30 x/menit"], "dz": ["asma", "pneumonia", "croup", "ppok"]},
	{"id": "inspeksi-toraks", "g": "respirasi", "name": "Inspeksi toraks", "sk": [234, 276], "goal": "Menilai bentuk dinding dada, gerak napas, dan tanda luar penyakit paru/jantung.", "tools": [], "prep": ["Pasien duduk/berbaring dengan dada terbuka sampai pinggang (wanita: tutup bila tidak diperiksa), pencahayaan baik"], "steps": [["Bentuk dada", "Normal (diameter AP:lateral ±1:2), barrel chest (AP ≈ lateral), pektus ekskavatum/karinatum, kifoskoliosis, gibbus."], ["Simetri statis & dinamis", "Amati dari depan, belakang, dan dari kaki tempat tidur: ada yang tertinggal saat inspirasi?"], ["Jenis & pola napas", "Torakal, abdominal, torakoabdominal; paradoksal (flail chest)."], ["Kulit & dinding", "Skar operasi/WSD, spider naevi, pelebaran vena, ginekomastia, iktus kordis tampak, pulsasi abnormal."], ["Tangan", "Clubbing finger (sudut Lovibond > 180°, Schamroth window hilang), sianosis perifer, tremor flapping (CO₂), noda nikotin."]], "normal": ["Dada simetris statis dan dinamis, bentuk normal, tidak ada retraksi, skar, atau clubbing."], "abn": [["Barrel chest", "PPOK/emfisema"], ["Satu sisi tertinggal", "Patologi di sisi yang tertinggal (efusi, pneumotoraks, pneumonia, atelektasis)"], ["Gerak paradoksal segmen dinding dada", "Flail chest — kegawatan"], ["Clubbing finger", "Kanker paru, bronkiektasis, abses paru, PJB sianotik, endokarditis, sirosis"], ["Gibbus di punggung", "Spondilitis TB"]], "doc": "Toraks: bentuk normal, simetris statis & dinamis, retraksi (−), skar (−). Clubbing finger (−).", "key": ["Amati dari depan, belakang, dan dari kaki", "Bandingkan gerak kanan-kiri"], "tips": [], "dz": ["ppok", "efusi-pleura", "pneumotoraks", "spondilitis-tb"]},
	{"id": "palpasi-toraks", "g": "respirasi", "name": "Palpasi toraks (trakea, ekspansi, fremitus taktil)", "sk": [235], "goal": "Menilai posisi trakea, ekspansi dada, fremitus taktil, dan nyeri tekan.", "tools": [], "prep": [], "steps": [["Posisi trakea", "Jari telunjuk dan manis pada klavikula medial, jari tengah meraba trakea di sternal notch — jarak kanan-kiri sama?"], ["Nyeri tekan & krepitasi", "Raba dinding dada pada area keluhan (fraktur iga, emfisema subkutis — sensasi \"kertas krisik\")."], ["Ekspansi dada", "Kedua tangan di dada bawah posterior (dan anterior), ibu jari bertemu di garis tengah, kulit sedikit dikerutkan; minta tarik napas dalam — ibu jari bergeser simetris ≥ 3–5 cm."], ["Fremitus taktil", "Sisi ulnar telapak/bantalan jari menempel di dinding dada, minta pasien berkata \"tujuh puluh tujuh\"/\"sembilan puluh sembilan\"; bandingkan kanan-kiri dari atas ke bawah, posterior, lateral, anterior."]], "normal": ["Trakea di tengah, ekspansi simetris, fremitus taktil sama kanan-kiri, nyeri tekan (−), krepitasi (−)."], "abn": [["Trakea terdorong menjauhi sisi lesi", "Efusi pleura masif, tension pneumothorax"], ["Trakea tertarik ke sisi lesi", "Atelektasis, fibrosis, pneumonektomi"], ["Fremitus meningkat", "Konsolidasi (pneumonia)"], ["Fremitus menurun/hilang", "Efusi pleura, pneumotoraks, penebalan pleura, atelektasis obstruktif"], ["Ekspansi menurun unilateral", "Patologi sisi tersebut"], ["Krepitasi subkutan", "Emfisema subkutis (pneumotoraks, trauma)"]], "doc": "Trakea di tengah. Ekspansi dada simetris. Fremitus taktil kanan = kiri. Nyeri tekan (−), krepitasi (−).", "key": ["Bandingkan simetris kanan-kiri", "Sebutkan arti fremitus meningkat vs menurun"], "tips": [], "dz": ["pneumonia", "efusi-pleura", "pneumotoraks"]},
	{"id": "perkusi-toraks", "g": "respirasi", "name": "Perkusi toraks (termasuk batas paru-hepar & peranjakan)", "sk": [236], "goal": "Menilai sonoritas paru dan batas organ dengan perkusi.", "tools": [], "prep": [], "steps": [["Teknik", "Jari tengah tangan kiri (pleksimeter) menempel erat di sela iga sejajar iga; ketuk falang tengah dengan ujung jari tengah kanan (plessor) dari pergelangan, cepat, 2 ketukan."], ["Urutan", "Bandingkan kanan-kiri berselang-seling dari apeks (supraklavikula) ke basal; posterior (lengan pasien bersilang agar skapula terbuka), lateral, anterior; hindari tulang skapula."], ["Batas paru-hepar", "Perkusi linea midklavikula kanan dari atas: sonor → redup (batas paru-hepar, normal ICS VI) → pekak."], ["Peranjakan diafragma", "Posterior: tentukan batas redup saat ekspirasi maksimal dan inspirasi maksimal; selisih normal 3–5 cm."]], "normal": ["Sonor di seluruh lapang paru", "batas paru-hepar ICS VI linea midklavikula kanan", "peranjakan 3–5 cm."], "abn": [["Redup/pekak", "Konsolidasi, efusi pleura (pekak \"seperti batu\"), massa, atelektasis"], ["Hipersonor", "Pneumotoraks, emfisema/PPOK"], ["Pekak dengan batas atas melengkung (garis Ellis-Damoiseau)", "Efusi pleura"], ["Batas paru-hepar turun, peranjakan berkurang", "Emfisema/hiperinflasi"], ["Batas paru-hepar naik", "Paralisis diafragma, hepatomegali, asites, efusi subpulmonal"]], "doc": "Perkusi sonor di seluruh lapang paru kanan = kiri. Batas paru-hepar ICS VI LMCD, peranjakan 4 cm.", "key": ["Pleksimeter menempel erat sejajar iga", "Bandingkan kanan-kiri berselang-seling", "Gerak dari pergelangan"], "tips": [], "dz": ["efusi-pleura", "pneumotoraks", "pneumonia", "ppok"]},
	{"id": "auskultasi-paru", "g": "respirasi", "name": "Auskultasi paru (suara napas, suara tambahan, resonansi vokal)", "sk": [237], "goal": "Menilai suara napas dasar, suara tambahan, dan resonansi suara.", "tools": ["Stetoskop (diafragma)"], "prep": ["Ruangan tenang", "diafragma langsung di kulit"], "steps": [["Minta napas dalam lewat mulut", "Lebih dalam dari biasa tetapi tidak cepat (cegah hiperventilasi)."], ["Urutan", "Sama seperti perkusi: apeks ke basal, kanan-kiri bergantian, posterior-lateral-anterior; satu siklus napas penuh tiap titik."], ["Suara napas dasar", "Vesikuler (inspirasi lebih panjang, lembut, di sebagian besar paru); bronkial (keras, ekspirasi panjang, ada jeda — normal di trakea); bronkovesikuler (di area hilus)."], ["Suara tambahan", "Ronki basah halus/kasar (crackles: halus akhir inspirasi = alveolar/fibrosis/edema; kasar = sekret bronkus), wheezing (musikal, ekspirasi), ronki kering kasar (rhonchi), pleural friction rub (gesekan, inspirasi-ekspirasi, tidak hilang dengan batuk), stridor."], ["Batukkan", "Suara tambahan yang hilang setelah batuk = sekret."], ["Resonansi vokal", "Pasien berkata \"77\"; meningkat pada konsolidasi. Whispered pectoriloquy: bisikan jelas terdengar = konsolidasi. Egofoni: \"iii\" terdengar \"eee\"."]], "normal": ["Vesikuler di kedua lapang paru, ronki (−/−), wheezing (−/−), friction rub (−)."], "abn": [["Suara napas bronkial + ronki basah + fremitus meningkat + redup", "Konsolidasi (pneumonia)"], ["Suara napas menurun/hilang + perkusi pekak + fremitus menurun", "Efusi pleura"], ["Suara napas hilang + hipersonor + fremitus hilang", "Pneumotoraks"], ["Wheezing ekspirasi difus + ekspirasi memanjang", "Asma, PPOK, bronkiolitis"], ["Ronki basah halus bibasal", "Edema paru (gagal jantung), fibrosis paru"], ["Wheezing unilateral terlokalisasi menetap", "Obstruksi lokal (benda asing, tumor)"], ["Friction rub", "Pleuritis (pneumonia, emboli paru, TB)"], ["Silent chest pada asma", "Serangan mengancam nyawa"]], "doc": "Suara napas vesikuler +/+, ronki −/−, wheezing −/−.", "key": ["Diafragma di kulit langsung", "Bandingkan kanan-kiri satu siklus penuh", "Kenali minimal 4 suara tambahan"], "tips": ["Sintesis temuan inspeksi-palpasi-perkusi-auskultasi menjadi satu kesimpulan (konsolidasi, efusi, pneumotoraks, kolaps)"], "dz": ["pneumonia", "asma", "efusi-pleura", "gagal-jantung", "ppok"]},
	{"id": "prekordium", "g": "kardio", "name": "Inspeksi & palpasi prekordium (iktus kordis, thrill, heave)", "sk": [277], "goal": "Menilai lokasi dan karakter iktus kordis serta getaran/angkatan abnormal di prekordium.", "tools": [], "prep": ["Pasien berbaring 30–45°", "pemeriksa di sisi kanan pasien"], "steps": [["Inspeksi", "Iktus kordis tampak? pulsasi lain, deformitas dada, skar sternotomi."], ["Palpasi iktus", "Telapak tangan kanan di prekordium, lalu ujung jari untuk menentukan titik terlateral-terbawah denyut. Normal ICS V linea midklavikula kiri, diameter ≤ 2,5 cm (1 ICS)."], ["Karakter iktus", "Normal (ketukan singkat), kuat angkat/heaving (hipertrofi), tapping (S1 keras teraba — stenosis mitral), tergeser difus."], ["Parasternal heave", "Pangkal telapak di parasternal kiri — terangkat saat sistol = hipertrofi ventrikel kanan."], ["Thrill", "Getaran seperti kucing mendengkur; raba di apeks, parasternal kiri, area aorta & pulmonal. Thrill = murmur derajat ≥ 4/6."], ["Bila sulit teraba", "Miringkan pasien ke kiri (posisi dekubitus lateral kiri)."]], "normal": ["Iktus kordis tidak tampak, teraba di ICS V linea midklavikula kiri, tidak kuat angkat, thrill (−), heave (−)."], "abn": [["Iktus bergeser ke lateral/bawah", "Kardiomegali (dilatasi ventrikel kiri), atau terdorong (efusi/pneumotoraks)"], ["Iktus kuat angkat (heaving) tidak bergeser", "Hipertrofi konsentrik (hipertensi, stenosis aorta)"], ["Iktus tapping", "Stenosis mitral"], ["Parasternal heave", "Hipertrofi ventrikel kanan (hipertensi pulmonal, stenosis mitral, PPOK lanjut)"], ["Iktus tidak teraba", "Obesitas, emfisema, efusi perikard, dekstrokardia"], ["Thrill sistolik apeks/parasternal", "Murmur ≥ 4/6 (VSD, MR berat, AS)"]], "doc": "Iktus kordis tidak tampak, teraba di ICS V LMCS, tidak kuat angkat, thrill (−), heave (−).", "key": ["Lokasi iktus dengan landmark tepat (hitung ICS dari angulus Louis)", "Telapak lalu ujung jari"], "tips": [], "dz": ["gagal-jantung", "hipertensi", "demam-reumatik"]},
	{"id": "perkusi-jantung", "g": "kardio", "name": "Perkusi batas jantung", "sk": [279], "goal": "Memperkirakan ukuran jantung melalui batas redup relatif.", "tools": [], "prep": [], "steps": [["Batas kiri", "Mulai dari linea aksilaris anterior kiri di ICS V, perkusi ke medial sampai sonor berubah redup. Normal di sekitar linea midklavikula kiri."], ["Batas kanan", "Tentukan batas paru-hepar (ICS VI LMCD), naik 1 ICS (ICS V/IV), perkusi dari lateral ke medial. Normal di linea sternalis kanan."], ["Batas atas (pinggang jantung)", "Perkusi linea parasternal kiri dari atas ke bawah; normal redup mulai ICS II–III."], ["Korelasi dengan iktus", "Batas kiri biasanya sesuai iktus kordis."]], "normal": ["Kanan di linea sternalis kanan ICS IV", "kiri ICS V linea midklavikula kiri", "atas ICS II–III linea parasternal kiri."], "abn": [["Batas kiri melewati linea midklavikula kiri", "Kardiomegali (pembesaran ventrikel kiri)"], ["Batas kanan > 2 cm dari sternal kanan", "Pembesaran atrium kanan, efusi perikard"], ["Pinggang jantung menghilang", "Pembesaran atrium kiri (stenosis mitral)"], ["Batas tidak dapat ditentukan (hipersonor)", "Emfisema"]], "doc": "Batas jantung: kanan ICS IV linea sternalis kanan; kiri ICS V LMCS; atas ICS II linea parasternal kiri. Kesan: tidak membesar.", "key": ["Perkusi dari sonor ke redup", "Landmark ICS benar"], "tips": ["Perkusi kurang akurat — konfirmasi dengan foto toraks (CTR > 50%) atau ekokardiografi"], "dz": ["gagal-jantung", "kardiomiopati"]},
	{"id": "auskultasi-jantung", "g": "kardio", "name": "Auskultasi jantung (bunyi jantung, murmur, gallop, Carvallo)", "sk": [280, 288], "goal": "Menilai bunyi jantung I–II, bunyi tambahan, dan murmur dengan karakteristik lengkap.", "tools": ["Stetoskop dengan diafragma (frekuensi tinggi) dan bel (frekuensi rendah)"], "prep": ["Ruangan tenang", "pasien berbaring 30–45°", "raba nadi karotis bersamaan untuk menentukan sistol"], "steps": [["Empat area", "Mitral (apeks, ICS V LMCS), trikuspid (ICS IV parasternal kiri bawah), pulmonal (ICS II parasternal kiri), aorta (ICS II parasternal kanan). Juga aksila dan karotis untuk penjalaran."], ["Diafragma lalu bel", "Diafragma untuk S1, S2, murmur regurgitasi, rub; bel ditempel ringan untuk S3, S4, murmur stenosis mitral (rumble)."], ["S1 & S2", "Intensitas (keras/lemah), split S2 fisiologis saat inspirasi di area pulmonal."], ["Bunyi tambahan", "S3 (setelah S2, \"Ken-tuc-ky\", gagal jantung/volume overload), S4 (sebelum S1, \"Ten-nes-see\", hipertrofi/kaku), opening snap, ejection click, friction rub."], ["Murmur — deskripsi", "Timing (sistolik/diastolik), lokasi maksimal, penjalaran, derajat (1–6), bentuk (crescendo-decrescendo/holosistolik), nada, kualitas, perubahan dengan manuver."], ["Manuver", "Dekubitus lateral kiri + bel di apeks (MS); duduk condong ke depan, ekspirasi tahan, diafragma di sternal kiri (AR); inspirasi menguatkan murmur sisi kanan (Carvallo: murmur TR mengeras saat inspirasi)."]], "normal": ["BJ I–II murni reguler, murmur (−), gallop (−)."], "abn": [["Murmur ejeksi sistolik ICS II kanan menjalar ke karotis", "Stenosis aorta"], ["Murmur holosistolik apeks menjalar ke aksila", "Regurgitasi mitral"], ["Murmur diastolik rumbling di apeks + opening snap + S1 keras", "Stenosis mitral (sering reumatik)"], ["Murmur diastolik dekresendo sternal kiri, duduk condong ke depan", "Regurgitasi aorta"], ["Holosistolik sternal kiri bawah mengeras saat inspirasi (Carvallo +)", "Regurgitasi trikuspid"], ["Holosistolik keras sternal kiri ICS III–IV + thrill", "VSD"], ["S3 gallop", "Gagal jantung (disfungsi sistolik), volume overload (normal pada anak/dewasa muda/hamil)"], ["Friction rub 3 komponen, berubah dengan posisi", "Perikarditis"]], "doc": "BJ I–II murni reguler, murmur (−), gallop (−).", "key": ["Raba karotis untuk menentukan sistol", "Diafragma dan bel", "Deskripsi murmur lengkap (timing, lokasi, penjalaran, derajat)"], "tips": ["Derajat Levine: 1 sangat pelan … 4 dengan thrill … 6 terdengar tanpa stetoskop menempel"], "dz": ["demam-reumatik", "gagal-jantung", "radang-jantung"]},
	{"id": "karotis-bruit", "g": "kardio", "name": "Palpasi arteri karotis & deteksi bruit", "sk": [278, 286], "goal": "Menilai karakter nadi karotis dan mendengar bruit pembuluh darah besar.", "tools": ["Stetoskop (bel)"], "prep": [], "steps": [["Palpasi karotis", "Satu sisi saja dalam satu waktu (jangan bilateral — risiko sinkop), medial dari m. sternokleidomastoideus setinggi kartilago tiroid; jangan pijat sinus karotis."], ["Karakter", "Amplitudo, kecepatan naik, kontur (normal, lambat naik, kolaps, bisferiens)."], ["Bruit karotis", "Bel stetoskop di sepanjang karotis (sudut mandibula sampai klavikula) sambil pasien menahan napas."], ["Bruit lain", "Abdomen (a. renalis: kuadran atas lateral umbilikus; aorta), femoral, tiroid."]], "normal": ["Nadi karotis simetris, kontur normal, bruit (−)."], "abn": [["Bruit karotis", "Stenosis aterosklerotik a. karotis (risiko stroke) — evaluasi Doppler"], ["Nadi lambat naik bervolume kecil (parvus et tardus)", "Stenosis aorta"], ["Nadi kolaps (Corrigan)", "Regurgitasi aorta"], ["Bruit epigastrik/paraumbilikal + hipertensi muda", "Stenosis a. renalis (hipertensi renovaskular)"], ["Bruit di atas tiroid", "Hipertiroid Graves (vaskularisasi meningkat)"]], "doc": "A. karotis teraba simetris, isi cukup, bruit (−/−).", "key": ["Palpasi satu sisi bergantian", "Gunakan bel untuk bruit sambil menahan napas"], "tips": [], "dz": ["stroke-iskemik", "penyakit-katup"]},
	{"id": "jvp", "g": "kardio", "name": "Tekanan vena jugularis (JVP)", "sk": [282], "goal": "Memperkirakan tekanan atrium kanan dari tinggi kolom darah vena jugularis interna.", "tools": ["Penggaris 2 buah", "Senter (cahaya tangensial)"], "prep": ["Pasien berbaring dengan kepala-dada 45°, kepala sedikit menoleh ke kiri, leher rileks"], "steps": [["Identifikasi pulsasi", "Cari pulsasi v. jugularis interna di antara dua kepala sternokleidomastoideus menuju lobus telinga — bergelombang 2 puncak, tidak teraba, hilang bila ditekan di bawahnya, berubah dengan posisi dan respirasi (berbeda dari karotis)."], ["Ukur", "Penggaris vertikal di angulus sterni (Louis), penggaris horizontal dari titik tertinggi pulsasi ke penggaris vertikal. Tinggi vertikal di atas angulus sterni + 5 cm = tekanan atrium kanan."], ["Notasi", "JVP 5 + 2 cmH₂O (titik tertinggi 2 cm di atas angulus sterni)."], ["Uji refluks hepatojugular", "Tekan kuadran kanan atas 10–15 detik dengan tekanan tetap; kenaikan JVP ≥ 3 cm yang menetap = positif."]], "normal": ["JVP 5 ± 2 cmH₂O (≤ 3 cm di atas angulus sterni)", "refluks hepatojugular (−)."], "abn": [["JVP meningkat", "Gagal jantung kanan/kongestif, overload cairan, efusi perikard/tamponade, PPOK dengan kor pulmonal, obstruksi v. kava superior"], ["JVP naik saat inspirasi (Kussmaul)", "Perikarditis konstriktif, tamponade, infark ventrikel kanan"], ["Gelombang v besar", "Regurgitasi trikuspid"], ["Gelombang a cannon", "Disosiasi AV (blok AV total)"], ["Vena leher kolaps saat berbaring datar", "Hipovolemia"], ["Refluks hepatojugular (+)", "Gagal jantung kanan"]], "doc": "JVP 5 + 1 cmH₂O, refluks hepatojugular (−).", "key": ["Posisi 45° dan landmark angulus sterni", "Bedakan pulsasi vena vs karotis"], "tips": [], "dz": ["gagal-jantung", "kor-pulmonal-kronik"]},
	{"id": "arteri-perifer", "g": "kardio", "name": "Arteri ekstremitas, ABI, uji postur & hiperemia reaktif", "sk": [283, 291, 292, 293, 295], "goal": "Menilai pulsasi arteri perifer dan menyaring penyakit arteri perifer (PAP).", "tools": ["Sfigmomanometer", "Doppler genggam 8 MHz", "Gel", "Jam"], "prep": [], "steps": [["Inspeksi tungkai", "Warna (pucat, sianosis, kemerahan dependen), rambut rontok, kuku tebal, kulit mengkilat atrofi, ulkus (lokasi ujung jari/tumit = arteri), gangren."], ["Raba suhu & pulsasi", "Bandingkan kanan-kiri: radialis, brakialis, femoralis (pertengahan lig. inguinale), poplitea (lutut fleksi 30°, kedua tangan), tibialis posterior (belakang maleolus medial), dorsalis pedis (lateral tendon ekstensor halusis). Derajat 0 (tidak ada), 1 (lemah), 2 (normal), 3 (kuat/aneurisma)."], ["Radio-femoral delay", "Raba radialis & femoralis bersamaan — keterlambatan femoral = koarktasio aorta."], ["Uji Buerger (postur)", "Berbaring, angkat tungkai 45° selama 1–2 menit: pucat = iskemia (sudut Buerger < 20° berat). Lalu duduk dengan tungkai menggantung: kemerahan lambat/merah kehitaman (rubor dependen)."], ["Hiperemia reaktif", "Setelah tungkai diangkat/dioklusi beberapa menit lalu dilepas, waktu pengisian kemerahan normal < 15 detik; > 30 detik = insufisiensi arteri."], ["ABI", "TD sistolik tibialis posterior/dorsalis pedis (dengan Doppler) ÷ TD sistolik brakialis tertinggi. Hitung per tungkai."]], "normal": ["Pulsasi +2 simetris, akral hangat, Buerger (−)", "ABI 1,0–1,4."], "abn": [["ABI ≤ 0,9", "Penyakit arteri perifer"], ["ABI < 0,4 / nyeri istirahat / ulkus / gangren", "Iskemia tungkai kritis — rujuk"], ["ABI > 1,4", "Arteri tidak kompresibel (kalsifikasi: DM, CKD) — ABI tidak valid, pakai toe-brachial index"], ["6P (pain, pallor, pulseless, paresthesia, paralysis, poikilothermia) mendadak", "Iskemia tungkai akut (emboli) — kegawatan vaskular"], ["Radio-femoral delay", "Koarktasio aorta"], ["Kulit tungkai kecoklatan (hemosiderin) + edema + ulkus maleolus medial", "Insufisiensi vena kronik (bukan arteri)"]], "doc": "A. radialis, femoralis, poplitea, tibialis posterior, dorsalis pedis teraba +2 simetris. Akral hangat. ABI kanan 1,1, kiri 1,05.", "key": ["Raba semua titik nadi dan bandingkan", "Rumus ABI benar (pembagi brakialis tertinggi)"], "tips": [], "dz": ["pad", "kaki-diabetik"]},
	{"id": "varises-homan", "g": "kardio", "name": "Uji vena tungkai: Trendelenburg, Perthes & Homan", "sk": [287, 289, 290], "goal": "Menilai kompetensi katup vena superfisial/perforator pada varises dan menyaring trombosis vena dalam.", "tools": ["Tourniquet/torniket karet"], "prep": [], "steps": [["Inspeksi berdiri", "Distribusi varises (v. safena magna medial, parva posterior betis), edema, perubahan kulit, ulkus."], ["Trendelenburg (Brodie-Trendelenburg)", "Berbaring, angkat tungkai untuk mengosongkan vena; pasang torniket di paha atas (di bawah sambungan safenofemoral) atau tekan dengan jari; minta berdiri. Varises tetap kosong lalu cepat terisi saat torniket dilepas = inkompetensi safenofemoral. Terisi cepat walau torniket terpasang = inkompetensi perforator di bawah torniket."], ["Perthes", "Torniket di paha dengan varises terisi (berdiri), minta jalan/jinjit 10 kali. Varises mengempis = vena dalam paten dan perforator kompeten; makin membesar & nyeri = obstruksi vena dalam (jangan stripping)."], ["Homan", "Lutut sedikit fleksi, dorsofleksikan kaki secara pasif mendadak; nyeri betis = positif. Sensitivitas & spesifisitas rendah — gunakan skor Wells."], ["Pemeriksaan TVD", "Bandingkan lingkar betis 10 cm di bawah tuberositas tibia (selisih > 3 cm bermakna), edema pitting unilateral, nyeri tekan sepanjang vena dalam."]], "normal": ["Trendelenburg (−), Perthes varises mengempis, Homan (−), lingkar betis simetris."], "abn": [["Trendelenburg (+) setelah torniket dilepas", "Inkompetensi katup safenofemoral"], ["Perthes: varises makin membesar dan nyeri", "Obstruksi vena dalam"], ["Betis bengkak unilateral + nyeri tekan + Homan (+)", "Curiga TVD — hitung Wells, USG Doppler/D-dimer, rujuk"], ["TVD + sesak/nyeri dada mendadak", "Emboli paru — kegawatan"]], "doc": "Varises v. safena magna kanan. Trendelenburg: inkompetensi safenofemoral. Perthes: vena dalam paten. Homan (−). Lingkar betis kanan 35 cm, kiri 35 cm.", "key": ["Kosongkan vena dulu (tungkai diangkat) sebelum memasang torniket", "Interpretasi Perthes sebelum tindakan"], "tips": ["Homan saja tidak cukup untuk menegakkan atau menyingkirkan TVD"], "dz": ["varises", "tvd"]},
	{"id": "edema", "g": "kardio", "name": "Penilaian edema", "sk": [294], "goal": "Menilai lokasi, derajat, dan jenis edema.", "tools": [], "prep": [], "steps": [["Inspeksi", "Simetris atau unilateral, lokasi (pretibial, dorsum pedis, sakral pada pasien berbaring, periorbita, generalisata/anasarka), kemerahan, perubahan kulit."], ["Pitting", "Tekan ibu jari di atas tulang (dorsum pedis, belakang maleolus medial, pretibial) selama ≥ 5 detik; amati lekukan dan waktu kembali."], ["Derajat", "+1 lekuk 2 mm, kembali segera; +2 4 mm, < 15 detik; +3 6 mm, ±1 menit; +4 8 mm, 2–5 menit."], ["Batas atas", "Tentukan sampai setinggi mana (pergelangan, betis, lutut, paha, dinding perut)."], ["Nyeri, suhu & kulit", "Hangat-merah-nyeri (selulitis, TVD); kulit tebal tanpa pitting (limfedema, miksedema)."]], "normal": ["Edema (−)."], "abn": [["Pitting bilateral simetris tungkai", "Gagal jantung, sindrom nefrotik, sirosis (hipoalbuminemia), obat (amlodipin), kehamilan"], ["Edema periorbita pagi hari", "Sindrom nefrotik, glomerulonefritis"], ["Edema unilateral + nyeri betis", "TVD"], ["Unilateral hangat merah nyeri, batas tidak tegas", "Selulitis"], ["Non-pitting, kulit tebal (peau d'orange)", "Limfedema (filariasis, pascaoperasi), miksedema"], ["Anasarka", "Hipoalbuminemia berat, gagal jantung berat, gagal ginjal"], ["Edema tungkai + preeklamsia", "Bukan kriteria diagnosis tetapi waspadai bila disertai hipertensi & proteinuria"]], "doc": "Edema pretibial pitting +2 bilateral sampai pertengahan tungkai bawah; sakral (−).", "key": ["Tekan ≥ 5 detik di atas tulang", "Sebut derajat dan batas atas", "Bedakan pitting vs non-pitting"], "tips": [], "dz": ["gagal-jantung", "sindrom-nefrotik", "sirosis", "filariasis"]},
	{"id": "inspeksi-auskultasi-abdomen", "g": "abdomen", "name": "Inspeksi & auskultasi abdomen", "sk": [322], "goal": "Menilai bentuk, kulit, gerakan dinding perut, dan bising usus sebelum palpasi.", "tools": ["Stetoskop"], "prep": ["Pasien berbaring datar, satu bantal, lengan di samping, lutut boleh sedikit fleksi", "kandung kemih kosong", "buka dari prosesus xifoideus sampai simfisis", "pemeriksa di kanan pasien"], "steps": [["Inspeksi dari samping & kaki", "Bentuk (datar, cembung, skafoid, distensi simetris/asimetris), umbilikus (inverted/everted), gerak napas."], ["Kulit", "Skar operasi, striae (putih lama, ungu-merah Cushing), kaput medusa, spider naevi, ekimosis (Cullen periumbilikal, Grey Turner pinggang), ruam."], ["Gerakan & massa", "Peristaltik tampak (darm contour/darm steifung = obstruksi), pulsasi epigastrik (aorta), massa, hernia."], ["Auskultasi sebelum palpasi", "Diafragma di satu titik (kuadran kanan bawah) selama ≥ 1 menit (hingga 2–3 menit bila tidak terdengar). Hitung bising usus (normal ±5–35 x/menit)."], ["Karakter bising usus", "Normal, meningkat (diare, awal obstruksi), metalik/high-pitched (obstruksi mekanik), menurun/hilang (ileus paralitik, peritonitis)."], ["Bruit & succussion splash", "Bruit aorta/renalis; goyang abdomen dengan stetoskop di epigastrium — kecipak > 3 jam setelah makan = obstruksi gaster outlet."]], "normal": ["Abdomen datar, simetris, skar (−), massa (−)", "bising usus (+) normal 10 x/menit."], "abn": [["Distensi + bising usus metalik + darm contour", "Obstruksi usus mekanik"], ["Distensi + bising usus hilang", "Ileus paralitik, peritonitis difus"], ["Kaput medusa + spider naevi", "Hipertensi portal (sirosis)"], ["Ekimosis Cullen/Grey Turner", "Pankreatitis akut hemoragik, perdarahan retroperitoneal"], ["Striae ungu lebar", "Sindrom Cushing"], ["Pulsasi ekspansil di epigastrium", "Aneurisma aorta abdominal"]], "doc": "Abdomen: datar, simetris, distensi (−), skar (−), venektasi (−). Bising usus (+) normal 8 x/menit, metalik (−).", "key": ["Auskultasi sebelum palpasi/perkusi", "Dengarkan ≥ 1 menit sebelum menyatakan bising usus menurun"], "tips": [], "dz": ["ileus-obstruksi", "peritonitis", "sirosis", "pankreatitis"]},
	{"id": "palpasi-abdomen", "g": "abdomen", "name": "Palpasi abdomen (superfisial, dalam, hepar, lien, ginjal, aorta)", "sk": [324, 359], "goal": "Menilai nyeri tekan, defans, massa, dan organ (hepar, lien, ginjal, aorta).", "tools": [], "prep": ["Tangan hangat", "tanyakan lokasi nyeri dan palpasi area tersebut terakhir", "perhatikan wajah pasien"], "steps": [["Palpasi superfisial", "Telapak tangan datar, tekan ringan 1–2 cm di keempat kuadran (sembilan regio): nyeri tekan, defans muskular (involunter), massa superfisial."], ["Palpasi dalam", "Tekan 4–5 cm (bimanual bila perlu) untuk massa: lokasi, ukuran, konsistensi, permukaan, nyeri, mobilitas, pulsasi."], ["Hepar", "Ujung jari tangan kanan sejajar arkus kosta mulai dari fossa iliaka kanan, naik bertahap tiap inspirasi dalam sampai tepi hepar menyentuh jari. Catat: berapa jari/cm di bawah arkus kosta di LMCD, tepi (tajam/tumpul), permukaan, konsistensi, nyeri."], ["Murphy sign", "Tekan di bawah arkus kosta kanan LMC, minta tarik napas dalam — napas terhenti karena nyeri = kolesistitis."], ["Lien", "Mulai dari fossa iliaka kanan ke arah arkus kosta kiri (diagonal) mengikuti inspirasi; tangan kiri menyangga iga kiri belakang. Bila tidak teraba, miringkan pasien ke kanan. Ukur dengan garis Schuffner (S1–S8)."], ["Ginjal (balotemen)", "Bimanual: tangan kiri di pinggang belakang (sudut kostovertebra), tangan kanan di anterior kuadran atas; dorong dari belakang saat inspirasi — ginjal \"melenting\" ke tangan depan."], ["Aorta", "Tekan dalam kedua tangan di kiri-kanan garis tengah di atas umbilikus; nilai lebar dan pulsasi ekspansil (normal ≤ 3 cm)."]], "normal": ["Supel, nyeri tekan (−), defans (−), hepar & lien tidak teraba, ballotement ginjal (−), massa (−)."], "abn": [["Defans muskular + nyeri tekan difus", "Peritonitis — rujuk bedah"], ["Murphy sign (+)", "Kolesistitis akut"], ["Hepatomegali tepi tumpul, nyeri tekan", "Hepatitis akut, kongesti hepar (gagal jantung kanan), abses hepar"], ["Hepar keras berbenjol", "Sirosis makronodular, keganasan hepar/metastasis"], ["Splenomegali", "Malaria, demam tifoid, hipertensi portal, leukemia, talasemia, limfoma"], ["Ballotement ginjal (+)", "Hidronefrosis, ginjal polikistik, tumor ginjal"], ["Massa pulsatil ekspansil > 3 cm", "Aneurisma aorta abdominal"]], "doc": "Abdomen supel, nyeri tekan (−), defans (−). Hepar & lien tidak teraba. Ballotement ginjal −/−. Massa (−).", "key": ["Palpasi area nyeri terakhir", "Hepar & lien dimulai dari fossa iliaka kanan", "Deskripsi organomegali dengan ukuran"], "tips": ["Lien harus membesar 2–3× untuk dapat teraba", "Bedakan lien (ada takik, tidak bisa diraba batas atasnya) dari ginjal kiri (balotemen +, perkusi timpani di atasnya)"], "dz": ["peritonitis", "kolesistitis", "hepatitis-a", "sirosis", "malaria", "tifoid"]},
	{"id": "perkusi-abdomen", "g": "abdomen", "name": "Perkusi abdomen (timpani, pekak hati, ruang Traube)", "sk": [329], "goal": "Menilai distribusi gas/cairan, ukuran hepar, dan pembesaran lien dengan perkusi.", "tools": [], "prep": [], "steps": [["Perkusi umum", "Sembilan regio; dominan timpani normal."], ["Ukuran hepar (liver span)", "Perkusi LMCD dari atas (sonor paru → redup, batas atas ±ICS V–VI) dan dari bawah (timpani → redup, batas bawah ±arkus kosta). Normal 6–12 cm."], ["Pekak hati", "Pekak hati yang hilang (diganti timpani) = udara bebas intraperitoneal."], ["Ruang Traube", "Area semilunar di antara iga VI, linea aksilaris anterior kiri, dan arkus kosta kiri; normal timpani. Redup = splenomegali (atau efusi pleura kiri, makanan di lambung)."], ["Perkusi kandung kemih", "Dari umbilikus ke simfisis; redup di suprapubik = kandung kemih penuh (retensi)."]], "normal": ["Timpani di seluruh abdomen", "liver span 6–12 cm LMCD", "pekak hati (+)", "ruang Traube timpani."], "abn": [["Pekak hati hilang", "Pneumoperitoneum (perforasi organ berongga) — rujuk segera"], ["Liver span > 12 cm", "Hepatomegali"], ["Ruang Traube redup", "Splenomegali"], ["Hipertimpani difus", "Distensi gas (obstruksi, ileus)"], ["Redup di pinggang bilateral", "Curiga asites — lanjutkan shifting dullness"]], "doc": "Perkusi timpani; liver span 9 cm LMCD; pekak hati (+); ruang Traube timpani.", "key": ["Liver span dari dua arah di LMCD", "Pekak hati hilang = udara bebas"], "tips": [], "dz": ["perforasi-usus", "peritonitis", "sirosis"]},
	{"id": "asites", "g": "abdomen", "name": "Asites: pekak beralih (shifting dullness) & undulasi", "sk": [330, 331], "goal": "Mendeteksi cairan bebas intraperitoneal.", "tools": [], "prep": [], "steps": [["Pekak sisi (flank dullness)", "Perkusi dari umbilikus ke lateral (pinggang) — timpani di tengah, redup di pinggang."], ["Shifting dullness", "Tandai batas timpani-redup di pinggang kiri, miringkan pasien ke kanan, tunggu 30–60 detik, perkusi lagi titik tadi. Menjadi timpani = positif (cairan berpindah). Ulangi sisi lain."], ["Undulasi (fluid thrill)", "Pasien/asisten menekan sisi ulnar tangannya di garis tengah perut (meredam getaran lemak); pemeriksa mengetuk satu pinggang, tangan lain merasakan getaran di pinggang seberang. Hanya positif pada asites masif."], ["Puddle sign", "(jarang dipakai) posisi lutut-dada untuk asites minimal."]], "normal": ["Shifting dullness (−), undulasi (−)."], "abn": [["Shifting dullness (+)", "Asites (≥ 500–1000 mL): sirosis, gagal jantung, sindrom nefrotik, keganasan peritoneum, TB peritoneal"], ["Undulasi (+)", "Asites masif"], ["Asites + demam + nyeri perut pada sirosis", "Peritonitis bakterial spontan — rujuk"]], "doc": "Shifting dullness (−), undulasi (−).", "key": ["Tunggu 30–60 detik setelah memiringkan pasien", "Gunakan peredam lemak di garis tengah untuk undulasi"], "tips": [], "dz": ["sirosis", "sindrom-nefrotik", "gagal-jantung"]},
	{"id": "apendisitis-sign", "g": "abdomen", "name": "Tanda peritoneal & apendisitis (Blumberg, Rovsing, psoas, obturator)", "sk": [326, 327, 328, 336], "goal": "Mendeteksi iritasi peritoneum dan tanda khas apendisitis akut.", "tools": [], "prep": [], "steps": [["Nyeri tekan McBurney", "Titik 1/3 lateral garis SIAS kanan–umbilikus."], ["Nyeri lepas (Blumberg)", "Tekan perlahan dan dalam di area nyeri, lepas mendadak — nyeri lebih hebat saat dilepas. Alternatif lebih nyaman: nyeri ketok/batuk (cough sign)."], ["Rovsing", "Tekan dalam di kuadran kiri bawah — nyeri dirasakan di kanan bawah."], ["Psoas", "Pasien miring ke kiri, ekstensikan tungkai kanan di panggul (atau terlentang: angkat tungkai kanan lurus melawan tahanan). Nyeri = apendiks retrosekal (iritasi m. psoas)."], ["Obturator", "Terlentang, fleksikan panggul dan lutut kanan 90°, rotasi interna panggul. Nyeri hipogastrik = apendiks pelvik."], ["Skor Alvarado", "Migrasi nyeri (1), anoreksia (1), mual-muntah (1), nyeri tekan kanan bawah (2), nyeri lepas (1), demam ≥ 37,3 °C (1), leukositosis (2), shift kiri (1). ≥ 7 kemungkinan besar apendisitis."]], "normal": ["Nyeri tekan McBurney (−), Blumberg (−), Rovsing (−), psoas (−), obturator (−)."], "abn": [["Nyeri tekan McBurney + Blumberg (+) + Rovsing (+)", "Apendisitis akut — rujuk bedah"], ["Psoas (+)", "Apendisitis retrosekal, abses psoas"], ["Obturator (+)", "Apendisitis pelvik, abses pelvik, hernia obturator"], ["Nyeri lepas difus + defans", "Peritonitis generalisata (apendiks perforasi)"], ["Nyeri kanan bawah pada wanita usia subur", "Singkirkan kehamilan ektopik, kista ovarium terpuntir, PID (β-hCG, PF ginekologi)"]], "doc": "Nyeri tekan McBurney (+), Blumberg (+), Rovsing (+), psoas (+), obturator (−). Skor Alvarado 8.", "key": ["Mulai palpasi jauh dari area nyeri", "Sebut cara dan interpretasi masing-masing tanda"], "tips": [], "dz": ["apendisitis", "peritonitis", "kehamilan-ektopik"]},
	{"id": "hernia", "g": "abdomen", "name": "Hernia: inspeksi inguinal saat tekanan intraabdomen & palpasi hernia", "sk": [323, 325], "goal": "Mendeteksi dan membedakan hernia inguinalis lateralis, medialis, dan femoralis serta menilai reponibilitas.", "tools": [], "prep": ["Periksa dalam posisi berdiri lalu berbaring"], "steps": [["Inspeksi berdiri", "Benjolan di lipat paha/skrotum; minta batuk/mengejan — benjolan muncul atau membesar."], ["Palpasi benjolan", "Ukuran, konsistensi, nyeri, dapat dimasukkan (reponibel) atau tidak; bising usus di dalamnya; batas atas dapat diraba (bukan hernia — hidrokel/varikokel) atau tidak."], ["Finger test", "Jari kelingking melalui kulit skrotum menyusuri funikulus ke annulus inguinalis eksterna, minta batuk. Impuls di ujung jari = lateralis (indirek); di sisi jari = medialis (direk)."], ["Ziemann test", "Jari II di annulus internus, III di annulus eksternus (Hesselbach), IV di fossa ovalis (femoralis); minta mengejan — dorongan di jari mana."], ["Thumb test", "Setelah hernia direposisi, tekan annulus internus (titik tengah SIAS–tuberkulum pubikum) dengan ibu jari, minta batuk. Benjolan tidak keluar = lateralis; tetap keluar = medialis."], ["Tanda strangulasi", "Benjolan tegang, nyeri, merah, tidak bisa masuk, mual-muntah, tanda obstruksi."]], "normal": ["Tidak ada benjolan lipat paha saat batuk/mengejan."], "abn": [["Benjolan inguinal-skrotal, impuls di ujung jari, thumb test tertahan", "Hernia inguinalis lateralis (indirek), tersering pada anak & pria muda"], ["Benjolan di segitiga Hesselbach, impuls di sisi jari", "Hernia inguinalis medialis (direk), lansia"], ["Benjolan di bawah ligamentum inguinale, lateral tuberkulum pubikum, wanita", "Hernia femoralis (risiko strangulasi tinggi)"], ["Benjolan tidak bisa direposisi, nyeri, merah, muntah", "Hernia inkarserata/strangulata — kegawatan bedah"], ["Skrotum membesar, batas atas teraba, transiluminasi (+)", "Hidrokel, bukan hernia"]], "doc": "Inspeksi: benjolan inguinal kanan saat mengejan, Ø 4 cm, reponibel. Finger test: impuls di ujung jari. Thumb test: tertahan. Kesan: hernia inguinalis lateralis dekstra reponibel.", "key": ["Periksa berdiri dan berbaring", "Sebut interpretasi finger/Ziemann/thumb test", "Nilai tanda strangulasi"], "tips": [], "dz": ["hernia-inguinal", "hidrokel"]},
	{"id": "colok-dubur", "g": "abdomen", "name": "Colok dubur (rectal toucher), prostat, sakrum & sarung tangan", "sk": [332, 333, 334, 364, 557], "goal": "Menilai anus, rektum, prostat, dan isi rektum.", "tools": ["Sarung tangan", "Jeli pelumas", "Kasa", "Pendamping (chaperone)"], "prep": ["Informed consent dan pendamping", "posisi Sims (miring kiri, lutut kanan fleksi) atau litotomi atau lutut-dada", "kosongkan kandung kemih"], "steps": [["Inspeksi perianal", "Buka bokong: hemoroid eksterna, fisura (biasanya garis tengah posterior), fistula, abses, skin tag, prolaps, kondiloma, ekskoriasi."], ["Palpasi sakrum & koksigis", "Nyeri tekan, sakrum (dekubitus, pilonidal)."], ["Masukkan jari", "Jari telunjuk berpelumas di anal verge, tekan lembut hingga sfingter relaks, masukkan perlahan mengarah ke umbilikus."], ["Tonus sfingter", "Minta pasien mengencangkan anus (menjepit jari)."], ["Dinding rektum", "Putar jari 360°: massa, ulkus, nyeri tekan, ampula kolaps atau berisi feses keras."], ["Prostat (pria)", "Di anterior: ukuran (normal sebesar kenari ±3 × 3 cm, grade I–IV), konsistensi (kenyal seperti ujung hidung), permukaan, sulkus medianus, nodul keras, nyeri tekan, pool atas teraba atau tidak."], ["Inspeksi sarung tangan", "Feses (warna: hitam/melena, dempul/akolik, darah segar), lendir, darah, pus."]], "normal": ["Perianal tenang", "tonus sfingter ani baik", "mukosa licin", "ampula berisi feses lunak", "prostat kenyal, simetris, sulkus medianus (+), pool atas teraba, nodul (−)", "sarung tangan: feses coklat, darah (−), lendir (−)."], "abn": [["Prostat membesar, kenyal, simetris, sulkus medianus mendangkal", "Benign prostatic hyperplasia (BPH)"], ["Nodul keras berbenjol, asimetris, sulkus hilang", "Curiga karsinoma prostat — PSA & rujuk"], ["Prostat sangat nyeri, hangat, lunak + demam", "Prostatitis akut (hindari masase)"], ["Tonus sfingter hilang + saddle anesthesia", "Sindrom kauda ekuina/cedera medula — rujuk darurat"], ["Massa keras ireguler di rektum, darah pada sarung tangan", "Curiga karsinoma rektum — rujuk"], ["Melena pada sarung tangan", "Perdarahan SCBA"], ["Nyeri hebat, fisura garis tengah posterior", "Fisura ani (colok dubur bisa ditunda)"], ["Prostat letak tinggi melayang pada trauma pelvis", "Ruptur uretra posterior — jangan pasang kateter"]], "doc": "RT: perianal tenang, TSA kuat, mukosa licin, ampula berisi feses, massa (−). Prostat: ±3 cm, kenyal, simetris, sulkus medianus (+), nodul (−), nyeri (−). Sarung tangan: feses coklat, darah (−), lendir (−).", "key": ["Informed consent dan pendamping", "Inspeksi perianal sebelum memasukkan jari", "Deskripsi prostat dan sarung tangan"], "tips": [], "dz": ["bph", "hemoroid", "fisura-ani", "kanker-kolorektal", "prostatitis"]},
	{"id": "ginjal-kk", "g": "abdomen", "name": "Nyeri ketok ginjal, perkusi kandung kemih & refleks bulbokavernosus", "sk": [360, 361, 362, 363], "goal": "Menilai traktus urinarius bagian atas dan bawah serta refleks sakral.", "tools": ["Sarung tangan"], "prep": [], "steps": [["Nyeri ketok CVA", "Pasien duduk; telapak tangan kiri di sudut kostovertebra, ketuk dengan sisi ulnar kepalan tangan kanan; bandingkan kanan-kiri."], ["Inspeksi & palpasi suprapubik", "Benjolan di suprapubik (kandung kemih penuh), nyeri tekan."], ["Perkusi kandung kemih", "Dari umbilikus ke simfisis — batas redup; kandung kemih penuh redup ≥ beberapa jari di atas simfisis."], ["Pemeriksaan traktus urinarius lain", "Meatus uretra (stenosis, sekret, hipospadia), testis, prostat (colok dubur)."], ["Refleks bulbokavernosus", "Pria: tekan/cubit glans penis; wanita: tekan klitoris (atau tarik kateter Foley lembut) sambil jari di anus — kontraksi sfingter ani = positif (S2–S4)."]], "normal": ["Nyeri ketok CVA (−/−), kandung kemih tidak teraba/tidak redup, refleks bulbokavernosus (+)."], "abn": [["Nyeri ketok CVA (+) + demam", "Pielonefritis akut"], ["Nyeri ketok CVA + kolik menjalar ke lipat paha", "Batu ureter"], ["Kandung kemih penuh teraba, redup sampai umbilikus", "Retensi urin (BPH, striktur, neurogenik, obat)"], ["Refleks bulbokavernosus hilang setelah cedera medula", "Syok spinal (atau lesi konus/kauda)"], ["Refleks bulbokavernosus kembali tanpa fungsi motorik/sensorik distal", "Cedera medula komplet (syok spinal berakhir)"]], "doc": "Nyeri ketok CVA −/−. Supra pubik: buli-buli tidak penuh, nyeri tekan (−). Refleks bulbokavernosus (+).", "key": ["Bandingkan kanan-kiri", "Interpretasi refleks bulbokavernosus pada trauma medula"], "tips": [], "dz": ["pielonefritis", "batu-saluran-kemih", "isk"]},
	{"id": "payudara", "g": "reproduksi", "name": "Inspeksi & palpasi payudara", "sk": [389], "goal": "Mendeteksi benjolan dan kelainan payudara serta KGB aksila; mengajarkan SADARI.", "tools": [], "prep": ["Pendamping (chaperone)", "waktu ideal 7–10 hari setelah hari pertama haid", "pasien duduk lalu berbaring"], "steps": [["Inspeksi duduk dalam 4 posisi", "Lengan di samping; lengan diangkat ke atas kepala; tangan di pinggang menekan (kontraksi pektoralis); membungkuk ke depan. Amati ukuran, simetri, kontur, retraksi/dimpling kulit, peau d'orange, kemerahan, puting (retraksi, ekzema, sekret)."], ["Palpasi berbaring", "Lengan sisi yang diperiksa di bawah kepala, bantal tipis di bawah bahu. Gunakan 3 jari tengah (bantalan) dengan gerakan memutar kecil dan 3 tingkat tekanan (ringan, sedang, dalam)."], ["Pola sistematis", "Vertikal (lawn-mower) dari klavikula ke lipatan inframamae, sternum ke linea aksilaris media, termasuk ekor Spence (aksila)."], ["Areola & puting", "Tekan lembut sekitar areola; amati sekret (warna: bening, susu, darah; satu atau banyak duktus)."], ["Deskripsi massa", "Kuadran/arah jam & jarak dari puting, ukuran (cm), bentuk, konsistensi, batas, mobilitas, nyeri tekan, perlekatan kulit/dinding dada."], ["KGB", "Aksila, supraklavikula, infraklavikula."]], "normal": ["Simetris, retraksi (−), peau d'orange (−), massa (−), sekret (−), KGB aksila tidak teraba."], "abn": [["Massa keras, batas tidak tegas, terfiksir, retraksi kulit/puting, peau d'orange", "Curiga karsinoma payudara — rujuk (USG/mamografi/biopsi)"], ["Massa kenyal, batas tegas, sangat mobile, wanita muda", "Fibroadenoma mamae"], ["Massa kistik nyeri berubah dengan siklus haid", "Kelainan fibrokistik"], ["Sekret berdarah dari satu duktus", "Papiloma intraduktal (atau karsinoma)"], ["Payudara merah bengkak nyeri pada ibu menyusui", "Mastitis; berfluktuasi => abses payudara"], ["Galaktorea bilateral pada wanita tidak menyusui", "Hiperprolaktinemia (prolaktinoma, obat)"]], "doc": "Mammae simetris, retraksi kulit/puting (−), peau d'orange (−). Massa (−/−). Sekret puting (−). KGB aksila tidak teraba.", "key": ["Inspeksi 4 posisi", "Palpasi sistematis 3 tingkat tekanan termasuk aksila", "Deskripsi massa lengkap"], "tips": ["Ajarkan SADARI tiap bulan dan SADANIS oleh tenaga kesehatan"], "dz": ["kanker-payudara", "fam", "mastitis"]},
	{"id": "genital-pria", "g": "reproduksi", "name": "Genitalia eksterna pria (penis, skrotum, testis, transiluminasi)", "sk": [388, 390], "goal": "Memeriksa penis, skrotum, testis, epididimis, dan funikulus spermatikus.", "tools": ["Sarung tangan", "Senter (transiluminasi)"], "prep": ["Informed consent, pendamping, privasi", "pasien berdiri lalu berbaring"], "steps": [["Inspeksi pubis & penis", "Rambut pubis (Tanner, kutu), kulit (lesi, ulkus, kondiloma, vesikel), preputium (dapat diretraksi? fimosis/parafimosis), meatus uretra (posisi: hipospadia/epispadia; sekret)."], ["Palpasi penis", "Korpus (plak fibrosis Peyronie), nyeri; tekan glans untuk sekret."], ["Inspeksi skrotum", "Ukuran, simetri (kiri normal lebih rendah), kulit, pembengkakan."], ["Palpasi testis", "Satu per satu antara ibu jari dan dua jari: ukuran (orkidometer: dewasa 15–25 mL), konsistensi kenyal, permukaan, nyeri, massa."], ["Epididimis & funikulus", "Epididimis di posterolateral testis; funikulus dari testis ke cincin inguinal — varikokel (\"seperti kantong cacing\") saat berdiri dan Valsava, vas deferens."], ["Transiluminasi", "Ruangan gelap; senter di belakang massa skrotum — tembus cahaya merah = cairan (hidrokel)."], ["Refleks kremaster", "Gores paha medial atas; testis ipsilateral naik."]], "normal": ["Penis normal, meatus di ujung glans, sekret (−)", "skrotum simetris, testis kenyal ±4–5 cm, massa (−)", "varikokel (−)", "transiluminasi (−)."], "abn": [["Testis nyeri mendadak, letak tinggi melintang, refleks kremaster hilang", "Torsio testis — kegawatan bedah (< 6 jam)"], ["Epididimis bengkak nyeri, nyeri berkurang saat testis diangkat (Prehn +)", "Epididimitis"], ["Massa testis keras tidak nyeri", "Curiga tumor testis — rujuk"], ["Skrotum membesar, transiluminasi (+), testis tidak teraba terpisah", "Hidrokel"], ["Pelebaran vena funikulus saat berdiri, hilang saat berbaring", "Varikokel"], ["Skrotum kosong", "Undesensus testis (kriptorkismus) — rujuk sebelum 1 tahun"], ["Ulkus genital tidak nyeri, keras", "Sifilis primer (chancre); nyeri multipel => herpes/chancroid"], ["Duh uretra purulen", "Uretritis gonore/non-gonore"]], "doc": "Genitalia eksterna: penis normal, OUE di ujung glans, sekret (−). Skrotum: testis kanan-kiri teraba, kenyal, ukuran ±15 mL, nyeri (−), massa (−). Transiluminasi (−).", "key": ["Pendamping dan privasi", "Bandingkan kedua testis", "Transiluminasi untuk massa skrotum"], "tips": [], "dz": ["torsio-testis", "hidrokel", "varikokel", "epididimitis", "gonore", "sifilis"]},
	{"id": "genital-wanita-spekulum", "g": "reproduksi", "name": "Genitalia eksterna wanita & pemeriksaan spekulum", "sk": [390, 391, 395, 396, 397, 398], "goal": "Memeriksa vulva, vagina, dan serviks; mengambil spesimen duh tubuh, Pap smear, dan IVA.", "tools": ["Spekulum Cocor bebek (Graves/Pederson) ukuran sesuai", "Lampu sorot", "Sarung tangan", "Kertas pH", "Lidi kapas & kaca objek", "Spatula Ayre/cytobrush & fiksatif", "Asam asetat 3–5%"], "prep": ["Kandung kemih kosong", "pendamping", "posisi litotomi", "spekulum dihangatkan & dibasahi air (bukan jeli bila akan Pap smear)"], "steps": [["Inspeksi vulva", "Rambut pubis, labia mayora/minora, klitoris, introitus, meatus uretra, kelenjar Bartholin (posisi jam 5 & 7: bengkak?), lesi (ulkus, kondiloma, vesikel, leukoplakia), prolaps saat mengejan."], ["Palpasi", "Kelenjar Bartholin antara ibu jari (luar) dan telunjuk (di dalam introitus); kelenjar Skene (tekan uretra dari dalam vagina — sekret?)."], ["Insersi spekulum", "Buka labia dengan 2 jari, masukkan spekulum tertutup miring 45° menekan ke posterior (hindari uretra), putar horizontal, dorong ke forniks posterior, buka perlahan sampai serviks tampak, kunci."], ["Inspeksi serviks & vagina", "Warna, ukuran, bentuk ostium (nulipara bulat, multipara melintang), erosi/ektropion, polip, massa, perdarahan, kista Naboth, duh (warna, konsistensi, bau). Dinding vagina saat menarik spekulum."], ["Spesimen duh", "Swab forniks posterior: pH (normal ≤ 4,5), sediaan salin (clue cell, trikomonas), KOH 10% (pseudohifa, whiff test amina), Gram (diplokokus intraseluler) dari endoserviks."], ["Pap smear", "Spatula Ayre diputar 360° di zona transformasi + cytobrush di endoserviks (putar ½ putaran), oles ke kaca objek, fiksasi segera."], ["IVA", "Oleskan asam asetat 3–5% di serviks, tunggu 1 menit; bercak putih (acetowhite) tebal berbatas tegas di zona transformasi = IVA positif."]], "normal": ["Vulva tenang, Bartholin tidak membesar", "portio licin, ostium tertutup, erosi (−), duh fisiologis putih jernih tidak berbau, pH ≤ 4,5", "IVA negatif."], "abn": [["Duh abu-abu homogen, bau amis, pH > 4,5, clue cell, whiff (+)", "Vaginosis bakterial"], ["Duh kuning-hijau berbusa, strawberry cervix, trikomonas", "Trikomoniasis"], ["Duh putih kental seperti keju, gatal, pseudohifa KOH", "Kandidiasis vulvovaginal"], ["Duh mukopurulen dari endoserviks, serviks rapuh mudah berdarah", "Servisitis (gonore/klamidia)"], ["Bengkak fluktuatif jam 5/7 labia", "Kista/abses Bartholin"], ["Acetowhite tebal berbatas tegas", "IVA positif (lesi prakanker) — krioterapi/rujuk"], ["Massa serviks rapuh mudah berdarah, berbau", "Curiga kanker serviks — rujuk"]], "doc": "Vulva/vagina tenang. Inspekulo: portio licin, OUE tertutup, erosi (−), fluksus (−), fluor (+) putih jernih tidak berbau, pH 4. IVA (−).", "key": ["Insersi spekulum miring tekan ke posterior lalu horizontal", "Pap smear tanpa jeli & fiksasi segera", "Interpretasi duh dengan pH, salin, KOH"], "tips": [], "dz": ["vaginosis", "trikomoniasis", "kandidiasis-vv", "bartholin", "kanker-serviks", "servisitis"]},
	{"id": "bimanual", "g": "reproduksi", "name": "Pemeriksaan bimanual & rektovaginal", "sk": [392, 393, 402], "goal": "Menilai serviks, uterus, dan adneksa secara palpasi.", "tools": ["Sarung tangan", "Jeli pelumas"], "prep": [], "steps": [["Insersi jari", "Setelah spekulum dilepas, jari II–III tangan dominan berpelumas masuk ke vagina, ibu jari diabduksi menjauhi klitoris."], ["Serviks", "Konsistensi (normal seperti ujung hidung; hamil lunak seperti bibir — Hegar/Goodell), posisi, ostium, nyeri goyang serviks (cervical motion tenderness)."], ["Uterus", "Tangan luar di abdomen bawah menekan ke arah tangan dalam: ukuran (normal sebesar telur ayam; ukuran kehamilan dalam minggu), posisi (antefleksi/retrofleksi), konsistensi, permukaan (berbenjol: mioma), mobilitas, nyeri."], ["Adneksa", "Jari dalam ke forniks lateral, tangan luar di fossa iliaka; raba ovarium (normal ±3 × 2 cm, sedikit nyeri) dan massa adneksa (ukuran, konsistensi, nyeri, mobilitas)."], ["Kavum Douglas", "Forniks posterior: menonjol, nyeri (darah/pus), nodul (endometriosis)."], ["Rektovaginal", "Jari II di vagina, jari III di rektum — menilai septum rektovaginal, kavum Douglas, ligamentum sakrouterina (stadium kanker serviks), uterus retrofleksi. Rectal toucher saja pada wanita yang belum menikah/virgo."]], "normal": ["Portio kenyal, nyeri goyang (−)", "uterus antefleksi, sebesar telur ayam, mobile, nyeri (−)", "adneksa & parametrium lemas, massa (−)", "kavum Douglas tidak menonjol."], "abn": [["Nyeri goyang serviks + nyeri adneksa + demam", "Penyakit radang panggul (PID)"], ["Nyeri goyang + massa adneksa + kavum Douglas menonjol + amenore", "Kehamilan ektopik terganggu — kegawatan"], ["Uterus membesar berbenjol keras", "Mioma uteri"], ["Massa adneksa kistik mobile", "Kista ovarium; terfiksir padat ireguler => curiga keganasan"], ["Uterus membesar lunak + amenore", "Kehamilan (tanda Hegar, Chadwick)"], ["Nodul nyeri di ligamen sakrouterina + dismenore", "Endometriosis"]], "doc": "VT bimanual: portio kenyal, OUE tertutup, nyeri goyang (−). CUT antefleksi, sebesar telur ayam. Adneksa & parametrium kanan-kiri lemas, massa (−). Kavum Douglas tidak menonjol.", "key": ["Tangan luar menekan ke arah tangan dalam", "Nilai nyeri goyang serviks", "Rektovaginal untuk kavum Douglas & parametrium"], "tips": [], "dz": ["pid", "kehamilan-ektopik", "mioma-adenomiosis", "kista-ovarium", "endometriosis"]},
	{"id": "leopold-djj", "g": "reproduksi", "name": "Abdomen ibu hamil: TFU, Leopold & denyut jantung janin", "sk": [427, 428, 429, 430], "goal": "Menilai usia kehamilan, letak-presentasi-posisi janin, dan kesejahteraan janin (DJJ).", "tools": ["Pita ukur (metlin)", "Doppler/stetoskop Laennec (Pinard)", "Jam"], "prep": ["Kandung kemih kosong", "ibu berbaring terlentang lutut sedikit fleksi (miring kiri bila pusing)", "pemeriksa di kanan ibu"], "steps": [["Inspeksi", "Bentuk perut (membujur/melintang), linea nigra, striae gravidarum, skar SC, gerak janin."], ["TFU", "Palpasi puncak fundus; ukur dengan metlin dari tepi atas simfisis ke puncak fundus (cm ≈ usia kehamilan minggu, setelah 20 minggu ±2 cm). Taksiran berat janin (Johnson-Tausack): (TFU − 12) × 155 g bila belum masuk PAP, (TFU − 11) × 155 bila sudah masuk."], ["Leopold I (menghadap ibu)", "Kedua tangan di fundus: bagian janin di fundus — bulat keras melenting (kepala) atau lunak tidak melenting (bokong)."], ["Leopold II", "Kedua tangan di sisi kanan-kiri perut: punggung (keras memanjang seperti papan) vs bagian kecil (ekstremitas). Tentukan punggung kanan/kiri."], ["Leopold III", "Satu tangan (ibu jari & jari lain) mencekam bagian terbawah di atas simfisis: kepala/bokong; masih dapat digoyangkan (belum masuk PAP)."], ["Leopold IV (menghadap kaki ibu)", "Kedua tangan di bagian terbawah; konvergen = belum masuk PAP, divergen = sudah masuk. Perlimaan bagian kepala yang masih teraba di atas simfisis (5/5 … 0/5)."], ["DJJ", "Cari punctum maksimum di sisi punggung (kepala di bawah: di bawah umbilikus). Hitung 1 menit penuh sambil meraba nadi ibu (bedakan). Doppler ≥ 10–12 minggu; Laennec ≥ 18–20 minggu."]], "normal": ["TFU sesuai usia kehamilan", "janin tunggal hidup intrauterin, letak memanjang, presentasi kepala, punggung kanan/kiri", "DJJ 110–160 x/menit teratur."], "abn": [["TFU > usia kehamilan ≥ 3 cm", "Gemelli, polihidramnion, makrosomia, mola, salah HPHT"], ["TFU < usia kehamilan ≥ 3 cm", "Pertumbuhan janin terhambat, oligohidramnion, salah HPHT"], ["Bokong di bawah (Leopold III lunak, tidak melenting)", "Presentasi bokong (sungsang) — rencana persalinan/rujuk"], ["Letak lintang (fundus & bawah kosong, kepala di samping)", "Letak lintang — rujuk"], ["DJJ < 110 atau > 160 x/menit menetap", "Gawat janin — resusitasi intrauterin, rujuk"], ["DJJ tidak terdengar", "Konfirmasi USG (IUFD?)"]], "doc": "TFU 30 cm (sesuai 32 mgg), TBJ 2.790 g. L I: bokong; L II: punggung kiri; L III: kepala; L IV: konvergen (5/5). DJJ 140 x/menit reguler.", "key": ["Urutan dan arah menghadap Leopold benar", "DJJ dihitung 1 menit sambil meraba nadi ibu", "Ukur TFU dengan metlin"], "tips": ["ANC minimal 6 kali (2 di trimester 1, 1 di trimester 2, 3 di trimester 3), 2× USG oleh dokter"], "dz": ["malpresentasi", "hipoksia-janin", "pjt"]},
	{"id": "kehamilan-muda", "g": "reproduksi", "name": "Pemeriksaan pada kehamilan muda", "sk": [431, 433], "goal": "Menegakkan kehamilan trimester I, menentukan usia kehamilan, dan menyingkirkan kehamilan ektopik/abortus.", "tools": ["Tes kehamilan urin (β-hCG)", "Spekulum", "Doppler"], "prep": [], "steps": [["Anamnesis", "HPHT & siklus (hitung HPL Naegele: hari +7, bulan −3, tahun +1), mual-muntah, perdarahan, nyeri perut."], ["Tanda tidak pasti & mungkin", "Amenore, mual, payudara tegang, Chadwick (vagina/serviks kebiruan), Hegar (isthmus lunak), Piskacek (uterus asimetris di tempat implantasi), Goodell (serviks lunak), tes urin positif."], ["Tes kehamilan urin", "Urin pagi; celupkan strip sesuai batas, baca 3–5 menit. Dua garis = positif (β-hCG ≥ 25 mIU/mL, ±10–14 hari setelah konsepsi)."], ["Inspekulo", "Perdarahan dari OUE? ostium terbuka? jaringan?"], ["Bimanual", "Ukuran uterus sesuai usia (8 minggu sebesar telur angsa, 12 minggu teraba di atas simfisis), nyeri goyang, massa adneksa."], ["Tanda pasti", "DJJ dengan Doppler (≥ 10–12 minggu), kantong gestasi/janin pada USG."]], "normal": ["Tes urin (+), uterus sesuai usia kehamilan, tidak ada perdarahan/nyeri, DJJ (+) bila ≥ 12 minggu."], "abn": [["Tes (+) + nyeri perut + perdarahan sedikit + nyeri goyang serviks", "Kehamilan ektopik terganggu — rujuk segera"], ["Perdarahan + ostium tertutup + uterus sesuai", "Abortus iminens"], ["Perdarahan + ostium terbuka + jaringan", "Abortus insipiens/inkomplet"], ["Uterus jauh lebih besar dari usia, hiperemesis, perdarahan, gelembung", "Mola hidatidosa"], ["Mual-muntah berat, dehidrasi, ketonuria", "Hiperemesis gravidarum"]], "doc": "PP test (+). HPHT 1/8/2026, HPL 8/5/2027, UK 8 minggu. Inspekulo: fluksus (−), OUE tertutup. VT: uterus sebesar telur angsa, nyeri goyang (−), adneksa lemas.", "key": ["Rumus Naegele", "Cara baca tes urin", "Singkirkan kehamilan ektopik"], "tips": [], "dz": ["kehamilan-ektopik", "abortus", "mola", "hiperemesis"]},
	{"id": "pelvimetri", "g": "reproduksi", "name": "Pelvimetri klinis", "sk": [432], "goal": "Menilai kapasitas panggul untuk memperkirakan kemungkinan persalinan per vaginam.", "tools": ["Sarung tangan", "Jeli"], "prep": ["Usia kehamilan ≥ 36 minggu atau saat inpartu", "kandung kemih kosong", "posisi litotomi"], "steps": [["Pintu atas panggul (PAP)", "Jari II–III menelusuri ke belakang mencari promontorium. Tidak teraba = konjugata diagonalis > 12 cm (luas). Bila teraba, ukur jarak promontorium–tepi bawah simfisis (konjugata diagonalis); konjugata vera = CD − 1,5 cm (normal ≥ 11 cm)."], ["Linea innominata", "Teraba seluruhnya (sempit) atau hanya sebagian (≤ 1/3 normal)."], ["Pintu tengah panggul", "Spina iskiadika menonjol/tumpul; dinding samping lurus/konvergen; sakrum cekung/datar; koksigis mobile."], ["Pintu bawah panggul", "Arkus pubis (normal ≥ 90°, muat 2 jari); jarak antartuberositas iskiadika dengan kepalan tangan (normal ≥ 8,5–10 cm, muat 4 buku jari)."], ["Simpulan", "Panggul luas/normal, sempit, atau patologis; nilai bersama taksiran berat janin (disproporsi kepala-panggul)."]], "normal": ["Promontorium tidak teraba, linea innominata teraba < 1/3, spina tidak menonjol, sakrum cekung, arkus pubis > 90°, distansia tuberum ≥ 4 buku jari — kesan panggul normal (ginekoid)."], "abn": [["Promontorium teraba, CD < 11,5 cm", "Panggul sempit PAP — risiko CPD, rujuk"], ["Spina iskiadika menonjol, dinding konvergen", "Penyempitan pintu tengah (panggul android)"], ["Arkus pubis < 90°", "Penyempitan pintu bawah"]], "doc": "Pelvimetri klinis: promontorium tidak teraba, linea innominata teraba 1/3, spina iskiadika tidak menonjol, sakrum cekung, arkus pubis > 90°, distansia tuberum 4 buku jari. Kesan: panggul luas.", "key": ["Urutan PAP → pintu tengah → pintu bawah", "Rumus konjugata vera"], "tips": [], "dz": ["cpd"]},
	{"id": "postpartum", "g": "reproduksi", "name": "Pemeriksaan postpartum: fundus, plasenta, lokia & perdarahan", "sk": [452, 453, 469, 470], "goal": "Menilai involusi uterus, kelengkapan plasenta, lokia, dan jumlah perdarahan setelah persalinan.", "tools": ["Bengkok/kasa", "Underpad/kain yang ditimbang", "Sarung tangan"], "prep": [], "steps": [["Kontraksi & TFU", "Palpasi fundus: keras (kontraksi baik) atau lembek; TFU setelah plasenta lahir 2 jari di bawah pusat, hari ke-1 setinggi pusat, turun ±1 jari/hari, tidak teraba hari ke-10–14."], ["Kelengkapan plasenta", "Sisi maternal: kotiledon lengkap, tidak ada yang robek/hilang; sisi fetal: selaput ketuban lengkap, pembuluh darah yang terputus di tepi (plasenta suksenturiata); tali pusat (2 arteri 1 vena), insersi."], ["Perkiraan perdarahan", "Ukur darah di bengkok/kantong; timbang kasa/underpad (1 g ≈ 1 mL); estimasi visual cenderung lebih rendah."], ["Lokia", "Warna, jumlah, bau: rubra (merah, hari 1–3), sanguinolenta (merah-kuning, 4–7), serosa (kuning-coklat, 8–14), alba (putih, > 2 minggu)."], ["Perineum & tanda vital", "Robekan, hematoma; TD, nadi, kandung kemih (penuh menghambat kontraksi)."]], "normal": ["Uterus keras, TFU 2 jari di bawah pusat, plasenta & selaput lengkap, perdarahan < 500 mL, lokia rubra tidak berbau."], "abn": [["Uterus lembek + perdarahan banyak", "Atonia uteri — masase, uterotonika, kompresi bimanual"], ["Kotiledon/selaput tidak lengkap", "Sisa plasenta — eksplorasi manual/kuret"], ["Perdarahan ≥ 500 mL (vaginal) atau ≥ 1000 mL (SC)", "Perdarahan postpartum — stabilisasi & rujuk"], ["Uterus keras tetapi perdarahan terus", "Robekan jalan lahir (serviks, vagina, perineum)"], ["Lokia berbau busuk + demam + uterus nyeri", "Endometritis postpartum"], ["TFU tidak turun (subinvolusi)", "Sisa plasenta, infeksi, mioma"]], "doc": "Kontraksi uterus baik, TFU 2 jari di bawah pusat. Plasenta lahir lengkap (kotiledon & selaput). Perdarahan ±250 mL. Lokia rubra, tidak berbau. Kandung kemih kosong.", "key": ["Periksa kotiledon dan selaput", "Estimasi darah dengan cara terukur", "Kenali 4T (tonus, trauma, tissue, trombin)"], "tips": [], "dz": ["hpp", "retensio-plasenta", "infeksi-nifas"]},
	{"id": "bayi-hangat-talipusat", "g": "anak", "name": "Menjaga bayi tetap hangat, pemotongan & perawatan tali pusat", "sk": [444, 445], "goal": "Mencegah hipotermia bayi baru lahir dan merawat tali pusat secara aman.", "tools": ["Kain kering hangat, topi", "Klem tali pusat 2 buah", "Gunting steril", "Penjepit/benang tali pusat"], "prep": [], "steps": [["Cegah kehilangan panas", "Ruangan hangat bebas angin (25–28 °C); keringkan bayi segera dari kepala sampai kaki kecuali tangan; ganti kain basah; pasang topi; kontak kulit-ke-kulit di dada ibu (IMD ≥ 1 jam); tunda memandikan ≥ 6 jam (idealnya 24 jam)."], ["Pemotongan tunda", "Jepit tali pusat setelah 1–3 menit (kecuali bayi perlu resusitasi)."], ["Klem & potong", "Klem pertama ±3 cm dari pusar, urut darah ke arah ibu, klem kedua 2 cm dari klem pertama; potong di antara klem dengan gunting steril sambil melindungi perut bayi dengan tangan."], ["Ikat", "Pasang penjepit/ikatan kuat ±1 cm dari dinding perut."], ["Perawatan", "Tali pusat dibiarkan kering dan terbuka (perawatan kering bersih), tanpa ramuan/alkohol; lipat popok di bawah tali pusat. Lepas sendiri 5–15 hari."], ["Edukasi tanda bahaya", "Kemerahan meluas ke kulit perut, bengkak, bernanah, berbau."]], "normal": ["Suhu bayi 36,5–37,5 °C", "tali pusat kering, tidak merah, tidak berbau."], "abn": [["Suhu aksila < 36,5 °C", "Hipotermia — kontak kulit, metode kanguru, cari infeksi/hipoglikemia"], ["Kemerahan > 1 cm di sekitar pusar, pus, bau", "Omfalitis — antibiotik, rujuk bila meluas"], ["Perdarahan dari tali pusat", "Ikatan longgar, defisiensi vitamin K"]], "doc": "Bayi dikeringkan, IMD dilakukan 1 jam, suhu 36,8 °C. Tali pusat dijepit 2 menit setelah lahir, dipotong steril, diikat, dirawat kering terbuka.", "key": ["Keringkan dan kontak kulit segera", "Potong tali pusat steril dengan melindungi perut bayi", "Perawatan kering tanpa ramuan"], "tips": [], "dz": ["infeksi-umbilikus"]},
	{"id": "tulang-belakang", "g": "muskulo", "name": "Tulang belakang: inspeksi postur, skapula, gerak & palpasi (termasuk sakroiliaka)", "sk": [515, 518, 519, 520, 531, 532], "goal": "Menilai postur, kelengkungan, gerak, dan nyeri tekan tulang belakang serta sendi sakroiliaka.", "tools": [], "prep": ["Pasien berdiri dengan punggung terbuka (pakaian dalam/baju periksa)"], "steps": [["Inspeksi berdiri dari belakang", "Kesejajaran kepala-bahu-pelvis, ketinggian bahu & skapula (winging scapula), krista iliaka, lipatan glutea; skoliosis."], ["Inspeksi dari samping", "Lordosis servikal, kifosis torakal, lordosis lumbal; hiperkifosis/gibbus, flat back."], ["Adam forward bend test", "Membungkuk ke depan lengan menggantung; punuk iga (rib hump) = skoliosis struktural."], ["Gerak lumbal & torakal", "Fleksi (ujung jari ke lantai), ekstensi, fleksi lateral kanan-kiri, rotasi (pelvis difiksasi). Inspeksi saat berbaring dan bangun."], ["Palpasi", "Prosesus spinosus satu per satu (nyeri, step-off spondilolistesis), otot paraspinal (spasme), sendi sakroiliaka (lesung di atas bokong)."], ["Perkusi", "Ketuk prosesus spinosus dengan kepalan/palu; nyeri ketok lokal (fraktur, infeksi, metastasis)."]], "normal": ["Postur tegak, kurvatura fisiologis, skoliosis (−), gerak penuh tanpa nyeri, nyeri tekan/ketok (−), spasme (−)."], "abn": [["Rib hump saat membungkuk", "Skoliosis struktural — ukur sudut Cobb"], ["Gibbus + nyeri ketok + demam/penurunan BB", "Spondilitis TB (Pott) — rujuk"], ["Nyeri ketok vertebra lokal pada lansia/keganasan", "Fraktur kompresi osteoporotik atau metastasis"], ["Hilang lordosis lumbal + gerak terbatas semua arah + pagi kaku", "Spondilitis ankilosa"], ["Spasme paraspinal tanpa defisit neurologis", "Nyeri punggung mekanik (low back pain muskuloskeletal)"], ["Winging scapula", "Paresis n. torakalis longus (m. serratus anterior)"]], "doc": "Vertebra: postur tegak, kurvatura fisiologis, skoliosis (−), gibbus (−). ROM lumbal penuh tanpa nyeri. Nyeri tekan/ketok prosesus spinosus (−), spasme paraspinal (−), nyeri tekan SI (−).", "key": ["Inspeksi dari belakang dan samping", "Adam forward bend", "Palpasi dan perkusi prosesus spinosus satu per satu"], "tips": [], "dz": ["deformitas-spinal", "spondilitis-tb", "osteoporosis"]},
	{"id": "sendi-umum", "g": "muskulo", "name": "Sendi ekstremitas: inspeksi, palpasi tendon-sendi, nyeri tekan & ROM", "sk": [517, 528, 530, 533], "goal": "Menilai sendi secara umum dengan pendekatan look-feel-move.", "tools": ["Goniometer"], "prep": [], "steps": [["Look", "Pembengkakan, kemerahan, deformitas (valgus/varus, subluksasi, nodus Heberden/Bouchard, ulnar deviation, swan neck, boutonnière), atrofi otot, skar, posisi."], ["Feel", "Suhu (punggung tangan, bandingkan), nyeri tekan garis sendi, efusi, sinovitis (bengkak kenyal \"boggy\"), krepitasi, tendon (nyeri, nodul, ruptur), tofus."], ["Move aktif", "Pasien menggerakkan sendi sendiri; amati rentang dan nyeri."], ["Move pasif", "Pemeriksa menggerakkan; bandingkan dengan aktif. Ukur ROM dengan goniometer (posisi netral = 0°)."], ["Interpretasi ROM", "Aktif terbatas, pasif penuh = kelainan otot/tendon/saraf; keduanya terbatas = kelainan sendi (kapsul, intraartikular)."], ["Pola keterlibatan", "Mono/oligo/poliartritis; simetris/asimetris; sendi kecil/besar; aksial."]], "normal": ["Tidak ada pembengkakan, deformitas, nyeri tekan, atau efusi", "ROM aktif dan pasif penuh tanpa nyeri."], "abn": [["Monoartritis akut merah panas nyeri hebat MTP-1", "Artritis gout akut"], ["Monoartritis akut + demam", "Artritis septik — aspirasi & rujuk segera"], ["Poliartritis simetris sendi kecil tangan (MCP, PIP) + kaku pagi > 1 jam", "Artritis reumatoid"], ["Nodus Heberden (DIP) & Bouchard (PIP), krepitasi, nyeri saat beraktivitas", "Osteoartritis"], ["Tofus di daun telinga/jari/siku", "Gout kronik bertofus"], ["Oligoartritis asimetris tungkai + entesitis + daktilitis", "Spondiloartritis (reaktif, psoriatik)"]], "doc": "Sendi: deformitas (−), bengkak (−), kemerahan (−), nyeri tekan (−), krepitasi (−). ROM aktif & pasif penuh.", "key": ["Urutan look-feel-move", "Bandingkan dengan sisi sehat", "Bandingkan ROM aktif dan pasif"], "tips": [], "dz": ["gout", "artritis-reumatoid", "osteoartritis", "artritis-septik"]},
	{"id": "rom-leher", "g": "muskulo", "name": "ROM kepala & leher", "sk": [534], "goal": "Menilai rentang gerak tulang belakang servikal.", "tools": [], "prep": [], "steps": [["Inspeksi", "Posisi kepala (tortikolis), spasme otot, massa."], ["Fleksi", "Dagu ke dada (normal 45°, dagu menyentuh sternum)."], ["Ekstensi", "Menengadah (normal 45–55°)."], ["Fleksi lateral", "Telinga ke bahu tanpa mengangkat bahu (normal 40°)."], ["Rotasi", "Menoleh ke kanan-kiri, dagu ke arah bahu (normal 70–80°)."], ["Spurling", "Ekstensi + fleksi lateral + rotasi ke sisi keluhan, tekan aksial lembut; nyeri menjalar ke lengan = radikulopati servikal."]], "normal": ["Fleksi 45°, ekstensi 55°, fleksi lateral 40°, rotasi 70° ke kedua sisi tanpa nyeri."], "abn": [["Terbatas semua arah + krepitasi pada lansia", "Spondilosis servikal"], ["Spurling (+)", "Radikulopati servikal (HNP servikal)"], ["Kepala miring + rotasi ke sisi berlawanan, sternokleidomastoideus tegang", "Tortikolis"], ["Nyeri leher pasca trauma + nyeri tekan garis tengah", "Jangan gerakkan — imobilisasi, foto servikal (NEXUS/Canadian C-spine)"]], "doc": "ROM servikal: fleksi 45°, ekstensi 50°, lateral fleksi 40°/40°, rotasi 70°/70°, nyeri (−). Spurling (−).", "key": ["Jangan menilai ROM leher pada trauma sebelum fraktur disingkirkan"], "tips": [], "dz": []},
	{"id": "bahu", "g": "muskulo", "name": "Tes fungsi otot & sendi bahu", "sk": [535], "goal": "Menilai ROM bahu dan kelainan rotator cuff, impingement, serta instabilitas.", "tools": [], "prep": [], "steps": [["Look & feel", "Kontur deltoid (atrofi, step-off AC, hilangnya bulatan bahu pada dislokasi), nyeri tekan sendi AC, tuberkulum mayus, sulkus bisipital."], ["ROM", "Fleksi 180°, ekstensi 60°, abduksi 180°, adduksi, rotasi eksterna 90°, interna (punggung tangan ke punggung — vertebra tertinggi yang dicapai)."], ["Painful arc", "Nyeri pada abduksi aktif 60–120° = impingement/tendinitis supraspinatus; nyeri 160–180° = sendi AC."], ["Rotator cuff", "Empty can/Jobe (supraspinatus: lengan abduksi 90°, 30° ke depan, ibu jari ke bawah, tahan dorongan ke bawah); rotasi eksterna melawan tahanan (infraspinatus/teres minor); lift-off/belly press (subskapularis); drop arm (ruptur supraspinatus)."], ["Impingement", "Neer (elevasi pasif lengan pronasi dengan skapula difiksasi), Hawkins-Kennedy (fleksi 90° siku 90°, rotasi interna paksa)."], ["Instabilitas", "Apprehension test (abduksi 90° + rotasi eksterna — pasien takut lepas) & relocation."]], "normal": ["ROM penuh tanpa nyeri, painful arc (−), tes rotator cuff & impingement (−)."], "abn": [["Painful arc 60–120° + Neer/Hawkins (+)", "Sindrom impingement/tendinitis supraspinatus"], ["Drop arm (+), kelemahan empty can", "Ruptur rotator cuff"], ["Semua gerak aktif & pasif terbatas terutama rotasi eksterna", "Frozen shoulder (kapsulitis adhesiva), sering pada DM"], ["Bahu \"kotak\" (squared-off), lengan abduksi-rotasi eksterna pasca jatuh", "Dislokasi anterior bahu"], ["Apprehension (+)", "Instabilitas anterior bahu"]], "doc": "Bahu: deformitas (−), nyeri tekan (−). ROM penuh. Painful arc (−), empty can (−), drop arm (−), Neer (−), Hawkins (−).", "key": ["Bandingkan aktif dan pasif", "Sebut minimal 3 tes khusus beserta interpretasinya"], "tips": [], "dz": ["tendinitis-bursitis", "dislokasi"]},
	{"id": "tangan-pergelangan", "g": "muskulo", "name": "Pergelangan tangan, metakarpal & jari (Phalen, Tinel, Finkelstein, Luthy, Gowers)", "sk": [536], "goal": "Menilai fungsi pergelangan dan tangan serta tes provokasi saraf dan tendon.", "tools": [], "prep": [], "steps": [["Look", "Deformitas (ulnar deviation, swan neck, boutonnière, mallet finger), atrofi tenar (n. medianus) atau interoseus (n. ulnaris), nodul, ganglion."], ["ROM", "Fleksi-ekstensi pergelangan (80°/70°), deviasi radial-ulnar, pronasi-supinasi, mengepal penuh, ekstensi jari, oposisi ibu jari."], ["Phalen", "Kedua punggung tangan saling menempel dengan pergelangan fleksi maksimal 60 detik; kesemutan jari I–III = carpal tunnel syndrome (CTS)."], ["Tinel", "Ketuk di atas terowongan karpal (n. medianus) atau kubital (n. ulnaris); parestesia di distribusi saraf = positif."], ["Luthy (botol)", "Minta pasien menggenggam botol; kulit antara ibu jari-telunjuk tidak menempel rapat pada botol = kelemahan abduktor polisis brevis (n. medianus)."], ["Finkelstein", "Ibu jari digenggam dalam kepalan, deviasi ulnar pergelangan; nyeri hebat di prosesus stiloideus radius = tenosinovitis de Quervain."], ["Froment & tes saraf", "Froment (jepit kertas antara ibu jari-telunjuk: fleksi IP ibu jari = kelemahan adduktor polisis/n. ulnaris); wrist drop (n. radialis)."], ["Gowers (anak, kelemahan proksimal)", "Bangun dari duduk di lantai dengan \"memanjat\" tungkai sendiri menggunakan tangan."]], "normal": ["Tidak ada deformitas/atrofi, ROM penuh, Phalen (−), Tinel (−), Luthy (−), Finkelstein (−)."], "abn": [["Phalen (+), Tinel (+), atrofi tenar, kesemutan malam hari", "Carpal tunnel syndrome"], ["Finkelstein (+)", "Tenosinovitis de Quervain (sering ibu menyusui/pekerja tangan)"], ["Jari terkunci saat fleksi lalu \"klik\"", "Trigger finger (tenosinovitis stenosans)"], ["Benjolan kistik di dorsum pergelangan, transiluminasi (+)", "Ganglion"], ["Gowers (+) pada anak laki-laki + hipertrofi betis", "Distrofi otot Duchenne"], ["Nyeri tekan snuffbox anatomis pasca jatuh bertumpu tangan", "Fraktur skafoid (foto rontgen; risiko nekrosis avaskular)"]], "doc": "Manus: deformitas (−), atrofi tenar/hipotenar (−). ROM penuh. Phalen (−/−), Tinel (−/−), Luthy (−), Finkelstein (−).", "key": ["Phalen 60 detik", "Interpretasi distribusi saraf medianus/ulnaris/radialis"], "tips": [], "dz": ["neuropati-jeratan", "tendinitis-bursitis", "kista-ganglion"]},
	{"id": "panggul", "g": "muskulo", "name": "Sendi panggul (ROM, Trendelenburg, Thomas) & panjang tungkai", "sk": [522, 537], "goal": "Menilai sendi panggul, kontraktur, kelemahan abduktor, dan perbedaan panjang tungkai.", "tools": ["Pita ukur"], "prep": [], "steps": [["Look", "Gait (antalgik/Trendelenburg), posisi tungkai (rotasi eksterna & memendek pasca jatuh lansia = fraktur leher femur)."], ["ROM", "Fleksi 120° (lutut fleksi), ekstensi 30° (tengkurap), abduksi 45°, adduksi 30°, rotasi interna 35° & eksterna 45° (panggul & lutut fleksi 90°). Rotasi interna biasanya terganggu paling awal pada OA."], ["Thomas test", "Fleksikan penuh panggul kontralateral (lordosis lumbal hilang); tungkai yang diperiksa terangkat dari kasur = kontraktur fleksi panggul."], ["Trendelenburg test", "Berdiri satu kaki selama 30 detik; panggul sisi yang diangkat turun = kelemahan abduktor (gluteus medius) sisi yang menumpu."], ["Panjang tungkai sebenarnya (true length)", "SIAS ke maleolus medial; pelvis harus lurus. Selisih > 1–1,5 cm bermakna."], ["Panjang semu (apparent)", "Umbilikus ke maleolus medial (dipengaruhi kemiringan pelvis). Galeazzi (lutut fleksi, bandingkan tinggi lutut) pada anak."]], "normal": ["ROM panggul penuh tanpa nyeri", "Thomas (−)", "Trendelenburg (−)", "panjang tungkai sama."], "abn": [["Tungkai memendek, rotasi eksterna, nyeri pasca jatuh pada lansia", "Fraktur kolum femur — imobilisasi & rujuk"], ["Rotasi interna terbatas & nyeri lipat paha", "Osteoartritis panggul, nekrosis avaskular kaput femur"], ["Thomas (+)", "Kontraktur fleksi panggul (OA, abses psoas)"], ["Trendelenburg (+)", "Kelemahan gluteus medius, dislokasi panggul, coxa vara, neuropati gluteus superior"], ["True leg length berbeda", "Kelainan tulang/sendi panggul (fraktur, DDH, Perthes)"], ["Galeazzi (+) pada bayi + Ortolani/Barlow (+)", "Developmental dysplasia of the hip (DDH)"]], "doc": "Coxae: ROM penuh tanpa nyeri. Thomas (−/−), Trendelenburg (−/−). True leg length kanan 86 cm, kiri 86 cm.", "key": ["Pelvis lurus sebelum mengukur panjang tungkai", "Bedakan panjang sebenarnya vs semu"], "tips": [], "dz": ["fraktur", "osteoartritis", "ddh"]},
	{"id": "lutut", "g": "muskulo", "name": "Lutut: ligamen krusiatum & kolateral, meniskus", "sk": [524, 525], "goal": "Menilai efusi, stabilitas ligamen, dan cedera meniskus lutut.", "tools": [], "prep": [], "steps": [["Look & feel", "Bengkak, efusi (bulge sign untuk efusi sedikit; patellar tap/ballottement untuk efusi sedang-besar), nyeri tekan garis sendi medial/lateral, kista Baker di fossa poplitea."], ["ROM", "Ekstensi 0°, fleksi 135°; lutut terkunci (locking)."], ["Ligamen kolateral", "Lutut fleksi 20–30°, beri stres valgus (MCL) dan varus (LCL); celah sendi membuka/nyeri = cedera. Ulangi pada ekstensi penuh (bila longgar = cedera berat/kombinasi)."], ["Anterior drawer", "Lutut fleksi 90°, duduk di kaki pasien, tarik tibia ke depan — translasi berlebih tanpa end point = ACL."], ["Lachman (lebih sensitif)", "Lutut fleksi 20–30°, satu tangan memegang femur distal, tangan lain menarik tibia proksimal ke anterior."], ["Posterior drawer & sag sign", "Dorong tibia ke belakang / lutut fleksi 90° tibia turun ke belakang = PCL."], ["Meniskus", "McMurray (fleksi penuh lalu ekstensi sambil rotasi eksterna-valgus [medial] dan interna-varus [lateral]; klik/nyeri garis sendi); Apley compression (tengkurap, lutut 90°, tekan dan putar tumit); Thessaly (berdiri satu kaki fleksi 20° sambil memutar badan)."]], "normal": ["Efusi (−), nyeri tekan garis sendi (−), valgus/varus stabil, drawer & Lachman (−), McMurray (−)."], "abn": [["Lachman/anterior drawer (+), efusi cepat (hemartrosis) pasca cedera pivot", "Ruptur ligamen krusiatum anterior (ACL)"], ["Nyeri & laksitas stres valgus", "Cedera MCL"], ["Nyeri garis sendi + McMurray (+) + locking", "Robekan meniskus"], ["Sag sign (+) pasca dashboard injury", "Cedera PCL"], ["Efusi + krepitasi + osteofit, lansia", "Osteoartritis lutut"], ["Patellar tap (+), merah panas, demam", "Artritis septik — aspirasi"]], "doc": "Genu: efusi (−), nyeri tekan joint line (−). ROM 0–135°. Valgus/varus stress stabil. Anterior drawer (−), Lachman (−), posterior drawer (−). McMurray (−).", "key": ["Lachman pada fleksi 20–30°", "Bandingkan dengan lutut sehat", "Bedakan uji ligamen dan meniskus"], "tips": [], "dz": ["cedera-ligamen-lutut", "osteoartritis"]},
	{"id": "kaki-pergelangan", "g": "muskulo", "name": "Kaki & pergelangan kaki: postur, bentuk & gerak", "sk": [526, 527], "goal": "Menilai bentuk kaki, gerak pergelangan kaki, dan cedera ligamen/tendon.", "tools": [], "prep": [], "steps": [["Inspeksi berdiri", "Arkus longitudinal (pes planus/kavus), hindfoot valgus/varus, hallux valgus, jari palu (hammer toe), kalus, ulkus (kaki diabetik), callus pada titik tekan."], ["ROM", "Dorsofleksi 20°, plantarfleksi 50°, inversi 35°, eversi 15° (subtalar), gerak jari."], ["Palpasi", "Maleolus (Ottawa ankle rules: nyeri tekan tepi posterior/ujung 6 cm maleolus atau tak bisa menumpu 4 langkah = foto rontgen), ligamen talofibular anterior, basis metatarsal V, navikular, tendon Achilles, fasia plantar (nyeri tumit pagi hari)."], ["Thompson (Simmonds)", "Tengkurap kaki menggantung, remas betis — tidak ada plantarfleksi = ruptur tendon Achilles."], ["Anterior drawer pergelangan", "Tarik tumit ke depan dengan tibia difiksasi; translasi berlebih = ruptur ligamen talofibular anterior."], ["Sensasi & nadi", "Monofilamen 10 g (kaki diabetik), nadi dorsalis pedis & tibialis posterior."]], "normal": ["Arkus normal, deformitas (−), ROM penuh, nyeri tekan (−), Thompson (−)."], "abn": [["Nyeri tekan ligamen talofibular anterior pasca inversi", "Sprain pergelangan kaki lateral"], ["Ottawa positif", "Curiga fraktur — rontgen"], ["Thompson (+), celah teraba di tendon Achilles", "Ruptur tendon Achilles"], ["Nyeri tumit plantar langkah pertama pagi hari", "Fasiitis plantaris"], ["Monofilamen tidak terasa + deformitas + kalus", "Kaki diabetik berisiko tinggi ulkus"], ["Kaki bayi equinovarus kaku tidak bisa dikoreksi pasif", "CTEV (clubfoot) — rujuk dini (Ponseti)"]], "doc": "Pedis: arkus normal, deformitas (−). ROM ankle penuh. Nyeri tekan maleolus (−). Thompson (−). Monofilamen terasa di 10 titik.", "key": ["Ottawa ankle rules", "Thompson untuk tendon Achilles", "Monofilamen pada pasien DM"], "tips": [], "dz": ["sprain-strain", "kaki-diabetik", "deformitas-kongenital-kaki"]},
	{"id": "efloresensi", "g": "kulit", "name": "Deskripsi lesi kulit (efloresensi) & inspeksi dengan lup", "sk": [555, 562], "goal": "Mendeskripsikan ujud kelainan kulit (UKK) secara sistematis untuk diagnosis dermatologis.", "tools": ["Lup (kaca pembesar)", "Penggaris", "Senter", "Kaca objek (diaskopi)", "Sarung tangan"], "prep": ["Pencahayaan alami/terang", "periksa seluruh kulit termasuk kuku, rambut, mukosa"], "steps": [["Lokasi & distribusi", "Regio, simetris/unilateral, generalisata/lokalisata/universalis, area fleksor/ekstensor, terpajan matahari, dermatomal, intertriginosa."], ["UKK primer", "Makula (datar, < 1 cm; patch ≥ 1 cm), papul (menonjol padat < 1 cm; plak ≥ 1 cm), nodul (dalam, ≥ 1 cm), vesikel (berisi cairan < 1 cm; bula ≥ 1 cm), pustul (pus), urtika (edema dermis sementara), kista, tumor."], ["UKK sekunder", "Skuama, krusta, erosi, ekskoriasi, ulkus, fisura, likenifikasi, atrofi, sikatriks, hiperpigmentasi/hipopigmentasi."], ["Karakter", "Jumlah (soliter/multipel), ukuran (milier, lentikular, numular, plakat), bentuk, batas (tegas/tidak), tepi (aktif/meninggi), warna, permukaan."], ["Konfigurasi", "Linear, anular (cincin), arsinar, polisiklik, serpiginosa, korimbiformis, herpetiformis (berkelompok), target (iris)."], ["Diaskopi", "Tekan kaca objek: eritema memucat (vasodilatasi) vs tidak memucat (purpura/petekie — ekstravasasi darah)."], ["Lup", "Detail skuama, papul halus, terowongan (skabies), pungtum, pola pembuluh."]], "normal": ["Kulit tanpa UKK."], "abn": [["Plak eritematosa berbatas tegas dengan skuama tebal putih keperakan di ekstensor", "Psoriasis vulgaris"], ["Plak anular tepi aktif (papul/vesikel/skuama) dengan central healing", "Tinea korporis"], ["Vesikel berkelompok di atas dasar eritema sesuai dermatom", "Herpes zoster"], ["Papul/vesikel di sela jari, pergelangan, genital, gatal malam + terowongan", "Skabies"], ["Purpura palpabel di tungkai", "Vaskulitis (Henoch-Schönlein)"], ["Lesi target + keterlibatan mukosa", "Eritema multiforme/SJS-TEN — hentikan obat tersangka, rujuk"], ["Bula kendur + Nikolsky (+)", "Pemfigus vulgaris, SSSS, TEN"]], "doc": "Status dermatologis: regio antebrakii dekstra, tampak plak eritematosa, numular, multipel, batas tegas, tepi aktif dengan skuama halus, central healing (+).", "key": ["Urutan lokasi → UKK primer → sekunder → karakter → konfigurasi", "Gunakan istilah UKK baku"], "tips": [], "dz": ["psoriasis", "tinea", "herpes-zoster", "skabies", "sjs-ten"]},
	{"id": "mukosa-perianal", "g": "kulit", "name": "Inspeksi membran mukosa & daerah perianal", "sk": [556, 557], "goal": "Menemukan kelainan mukosa (mulut, mata, genital) dan perianal yang menyertai penyakit kulit.", "tools": ["Senter", "Spatel lidah", "Sarung tangan"], "prep": [], "steps": [["Mukosa mulut", "Bibir, mukosa pipi, gusi, lidah, palatum: erosi, ulkus, bercak putih (liken planus retikular, kandidiasis), vesikel, bercak Koplik."], ["Mukosa mata", "Konjungtiva: hiperemis, erosi, pseudomembran (SJS)."], ["Mukosa genital", "Erosi, ulkus, kondiloma, vesikel."], ["Perianal", "Inspeksi dengan memisahkan bokong: ekskoriasi (oksiuriasis), maserasi, kondiloma akuminata, fisura, fistel, kandidiasis/tinea kruris meluas, dermatitis."]], "normal": ["Mukosa merah muda tanpa erosi/ulkus/plak", "perianal tenang."], "abn": [["Erosi mukosa ≥ 2 lokasi + lesi kulit target/bula", "SJS-TEN — kegawatan dermatologi"], ["Erosi mukosa mulut nyeri persisten + bula kulit", "Pemfigus vulgaris"], ["Papul verukosa seperti kembang kol di perianal/genital", "Kondiloma akuminata (HPV)"], ["Gatal perianal malam hari pada anak + ekskoriasi", "Enterobiasis (cacing kremi)"], ["Plak putih retikular (Wickham striae) di mukosa pipi", "Liken planus oral"]], "doc": "Mukosa oral/konjungtiva/genital tenang, erosi (−). Perianal: ekskoriasi (−), kondiloma (−).", "key": ["Selalu periksa mukosa pada erupsi bula dan reaksi obat"], "tips": [], "dz": ["sjs-ten", "kondiloma", "oksiuriasis"]},
	{"id": "kuku-kulit-ekstremitas", "g": "kulit", "name": "Kulit & kuku ekstremitas", "sk": [558], "goal": "Menilai kuku dan kulit ekstremitas sebagai petunjuk penyakit kulit dan sistemik.", "tools": ["Senter", "Lup"], "prep": [], "steps": [["Lempeng kuku", "Warna (pucat, kuning, hitam/melanonikia longitudinal), bentuk (koilonikia/sendok, clubbing), permukaan (pitting, garis Beau, onikolisis, hiperkeratosis subungual), ketebalan."], ["Lipat kuku", "Paronikia (bengkak merah nyeri), hilangnya kutikula, eritema periungual/telangiektasia."], ["Kulit ekstremitas", "Warna, suhu, turgor, edema, rambut, ulkus, varises, hiperpigmentasi, likenifikasi."], ["Bandingkan kanan-kiri", "Distribusi kelainan."]], "normal": ["Kuku merah muda, licin, tidak rapuh", "kulit ekstremitas normal."], "abn": [["Pitting kuku + onikolisis + oil spot", "Psoriasis kuku"], ["Kuku menebal, kuning, rapuh, hiperkeratosis subungual", "Onikomikosis"], ["Koilonikia", "Anemia defisiensi besi"], ["Lipat kuku bengkak merah nyeri bernanah", "Paronikia akut (bakteri)"], ["Melanonikia longitudinal lebar/berubah, Hutchinson sign (pigmen di lipat kuku)", "Curiga melanoma subungual — rujuk"], ["Garis Beau (alur melintang)", "Gangguan pertumbuhan kuku sementara (penyakit berat, kemoterapi)"]], "doc": "Kuku: warna merah muda, pitting (−), onikolisis (−), paronikia (−). Kulit ekstremitas: tidak ada kelainan.", "key": ["Inspeksi kuku tangan dan kaki", "Sebut makna klinis kelainan kuku"], "tips": [], "dz": ["tinea-lain", "paronikia", "psoriasis"]},
	{"id": "wood-lamp", "g": "kulit", "name": "Pemeriksaan lampu Wood", "sk": [559], "goal": "Membantu diagnosis infeksi jamur, bakteri, dan kelainan pigmen dengan sinar UVA 365 nm.", "tools": ["Lampu Wood"], "prep": ["Ruangan benar-benar gelap", "jangan bersihkan area dengan sabun/salep sebelumnya (dapat berpendar palsu)"], "steps": [["Biarkan mata beradaptasi", "±1 menit dalam gelap."], ["Sinari dari jarak 10–15 cm", "Amati pendaran pada lesi dan bandingkan dengan kulit sekitar."], ["Interpretasi warna", "Kuning keemasan (pitiriasis versikolor), merah koral (eritrasma), hijau terang (tinea kapitis Microsporum), putih kebiruan terang batas tegas (vitiligo), hijau (Pseudomonas)."]], "normal": ["Kulit normal tidak berpendar khas."], "abn": [["Pendar kuning keemasan", "Pitiriasis versikolor (Malassezia)"], ["Pendar merah koral di lipatan", "Eritrasma (Corynebacterium minutissimum)"], ["Pendar hijau pada rambut kepala", "Tinea kapitis Microsporum (Trichophyton tidak berpendar)"], ["Depigmentasi tampak lebih jelas putih terang berbatas tegas", "Vitiligo (beda dari hipopigmentasi pitiriasis alba/kusta yang samar)"]], "doc": "Lampu Wood: lesi di punggung berpendar kuning keemasan.", "key": ["Ruangan gelap total", "Interpretasi warna pendaran"], "tips": [], "dz": ["tinea", "eritrasma", "vitiligo", "tinea-lain"]},
	{"id": "dermografisme-palpasi", "g": "kulit", "name": "Dermografisme & palpasi kulit (termasuk rangsang sensoris)", "sk": [560, 561], "goal": "Menilai respons urtikaria terhadap goresan dan karakter lesi saat diraba.", "tools": ["Benda tumpul (ujung spatel/pena tertutup)", "Kapas", "Jarum"], "prep": [], "steps": [["Dermografisme", "Goreskan benda tumpul dengan tekanan sedang di punggung atau lengan bawah; amati 5–10 menit."], ["Palpasi lesi", "Konsistensi (lunak/padat/keras), kedalaman (epidermis, dermis, subkutis), suhu, nyeri tekan, fluktuasi, permukaan (kasar/licin), indurasi."], ["Rangsang sensoris", "Sensasi raba (kapas), nyeri (jarum), suhu pada lesi dibandingkan kulit normal — wajib pada lesi hipopigmentasi/eritematosa yang dicurigai kusta."], ["Nikolsky", "Gosok kulit tampak normal di dekat bula dengan ibu jari; epidermis terkelupas = positif."]], "normal": ["Dermografisme hanya garis merah tipis yang cepat hilang (white/red line normal)", "sensasi lesi normal."], "abn": [["Gelegata (urtika linier) sesuai goresan dalam beberapa menit", "Dermografisme (urtikaria fisik)"], ["Garis putih menetap (white dermographism)", "Dermatitis atopik"], ["Lesi anestesi/hipestesi", "Kusta (morbus Hansen)"], ["Fluktuasi + nyeri + hangat", "Abses — insisi drainase"], ["Nikolsky (+)", "Pemfigus vulgaris, SSSS, TEN"]], "doc": "Dermografisme (−). Palpasi: lesi padat, tidak nyeri, sensasi raba-nyeri-suhu pada lesi normal. Nikolsky (−).", "key": ["Uji sensasi pada lesi dicurigai kusta", "Waktu pengamatan dermografisme"], "tips": [], "dz": ["urtikaria", "dermatitis-atopik", "kusta", "abses-perianal"]},
	{"id": "rambut-skalp", "g": "kulit", "name": "Rambut & kulit kepala (inspeksi, pull test)", "sk": [563], "goal": "Menilai kerontokan rambut, kelainan batang rambut, dan kulit kepala.", "tools": ["Lup", "Kaca objek"], "prep": [], "steps": [["Inspeksi", "Pola kebotakan (difus, berpola androgenik, bercak bulat), kulit kepala (skuama, eritema, pustul, sikatriks), batang rambut (patah, black dot), kutu & telur (nits)."], ["Pull test", "Genggam ±50–60 helai rambut dekat kulit kepala, tarik perlahan sambil meluncur ke ujung; ulangi di beberapa area. > 10% (> 5–6 helai) tercabut = kerontokan aktif."], ["Exclamation mark hair", "Rambut pendek patah yang menyempit ke arah pangkal di tepi bercak alopesia (alopesia areata)."], ["Kerokan/KOH", "Kerokan skuama dan rambut yang patah untuk jamur."]], "normal": ["Rambut tebal merata, pull test negatif (< 10%), kulit kepala tenang."], "abn": [["Bercak bulat botak licin + exclamation mark hair", "Alopesia areata"], ["Bercak skuama + rambut patah (black dot/grey patch) pada anak", "Tinea kapitis"], ["Pull test (+) difus 2–3 bulan setelah stres/demam/persalinan", "Telogen effluvium"], ["Penipisan vertex/frontotemporal bertahap", "Alopesia androgenetik"], ["Skuama kuning berminyak, eritema", "Dermatitis seboroik"], ["Telur menempel di batang rambut, gatal", "Pedikulosis kapitis"]], "doc": "Rambut hitam, distribusi merata, mudah dicabut (−), pull test (−). Kulit kepala: skuama (−), alopesia (−).", "key": ["Teknik pull test dan interpretasi", "Cari exclamation mark hair dan nits"], "tips": [], "dz": ["alopesia-areata", "tinea-lain", "pedikulosis"]},
	{"id": "kusta-saraf", "g": "kulit", "name": "Pemeriksaan sensorik, motorik & saraf tepi pada kusta (MH)", "sk": [568, 569], "goal": "Menegakkan diagnosis kusta, menentukan tipe, dan menilai cacat saraf (POD — pencegahan cacat).", "tools": ["Kapas yang dipilin", "Bolpoin (ujung tumpul) atau monofilamen", "Tabung panas-dingin", "Formulir POD"], "prep": [], "steps": [["Sensasi lesi", "Mata pasien tertutup, sentuhkan kapas tegak lurus pada lesi dan kulit normal; pasien menunjuk tempat yang disentuh. Lesi mati rasa = cardinal sign."], ["Penebalan saraf tepi", "Raba bilateral dan bandingkan: n. aurikularis magnus (leher, menoleh), n. ulnaris (sulkus di atas epikondilus medial), n. radialis kutaneus, n. medianus, n. peroneus komunis (fossa poplitea lateral, belakang kaput fibula), n. tibialis posterior (belakang maleolus medial). Nilai pembesaran, konsistensi, nyeri."], ["Sensorik telapak (POD)", "Titik di telapak tangan (n. ulnaris & medianus) dan telapak kaki (n. tibialis posterior) dengan bolpoin/monofilamen — tekanan ringan sampai kulit sedikit melekuk."], ["Motorik (Voluntary Muscle Test)", "Mata: menutup mata rapat (n. fasialis, lagoftalmus diukur mm). Tangan: abduksi kelingking (n. ulnaris), abduksi ibu jari ke atas (n. medianus), ekstensi pergelangan (n. radialis). Kaki: dorsofleksi (n. peroneus). Nilai Kuat/Sedang/Lumpuh."], ["Hitung lesi & klasifikasi WHO", "PB (pausibasiler): 1–5 lesi, 1 saraf terkena, BTA (−). MB (multibasiler): > 5 lesi, > 1 saraf, atau BTA (+)."], ["Tentukan derajat cacat WHO", "0 = tidak ada gangguan sensorik/kelihatan; 1 = anestesi (tangan/kaki) tanpa cacat terlihat; 2 = cacat terlihat (lagoftalmus, kontraktur, ulkus, visus < 6/60)."]], "normal": ["Lesi tidak ada/sensasi normal", "saraf tepi tidak menebal", "sensorik dan motorik tangan-kaki-mata normal."], "abn": [["Lesi hipopigmentasi/eritematosa mati rasa + penebalan saraf tepi", "Kusta (2 dari 3 tanda kardinal: lesi mati rasa, penebalan saraf + gangguan fungsi, BTA +)"], ["Nyeri dan pembesaran saraf mendadak + kelemahan baru", "Reaksi reversal/neuritis — prednison segera"], ["Nodul eritema nyeri + demam saat terapi MB", "Eritema nodosum leprosum (ENL)"], ["Lagoftalmus > 0 mm", "Cacat mata — risiko keratitis, rujuk"], ["Claw hand, wrist/foot drop", "Cacat derajat 2 (kerusakan saraf motorik)"]], "doc": "Status MH: 3 lesi hipopigmentasi anestesi di lengan & punggung. Penebalan n. ulnaris kanan. VMT: kuat semua. Sensibilitas telapak tangan/kaki normal. Klasifikasi PB, cacat derajat 0.", "key": ["Uji sensasi dengan mata tertutup", "Palpasi saraf tepi bilateral", "Klasifikasi PB/MB dan derajat cacat"], "tips": ["Lakukan POD setiap bulan selama MDT dan saat reaksi"], "dz": ["kusta"]},
	{"id": "tanda-khusus-kulit", "g": "kulit", "name": "Tanda khusus: Köbner, tetesan lilin, Auspitz & Nikolsky", "sk": [570], "goal": "Menggunakan tanda klinis khusus untuk menegakkan diagnosis psoriasis dan penyakit bula.", "tools": ["Kaca objek/kuret tumpul"], "prep": [], "steps": [["Fenomena tetesan lilin (candle grease)", "Gores skuama psoriasis dengan pinggir kaca objek; skuama berubah putih seperti lilin yang digores."], ["Auspitz sign", "Lanjutkan kerokan sampai skuama habis; muncul bintik-bintik perdarahan (papila dermis yang memanjang)."], ["Fenomena Köbner (isomorfik)", "Lesi baru muncul di bekas trauma/garukan (anamnesis & inspeksi garis linear di bekas goresan); pada psoriasis, liken planus, vitiligo, veruka (pseudo-Köbner)."], ["Nikolsky", "Gosok kulit normal di sekitar bula — epidermis terlepas (pemfigus, TEN, SSSS). Asboe-Hansen: tekan bula — meluas ke samping."]], "normal": ["Tetesan lilin (−), Auspitz (−), Köbner (−), Nikolsky (−)."], "abn": [["Tetesan lilin (+) + Auspitz (+)", "Psoriasis vulgaris"], ["Köbner (+)", "Psoriasis aktif, liken planus, vitiligo aktif"], ["Nikolsky (+)", "Pemfigus vulgaris, TEN, SSSS (bukan pemfigoid bulosa)"]], "doc": "Fenomena tetesan lilin (+), Auspitz (+), Köbner (+). Nikolsky (−).", "key": ["Urutan: tetesan lilin dulu kemudian Auspitz", "Bedakan Nikolsky positif pada pemfigus vs negatif pada pemfigoid"], "tips": [], "dz": ["psoriasis", "penyakit-bulosa"]},
	{"id": "bbl-apgar", "g": "anak", "name": "Pemeriksaan bayi baru lahir, skor Apgar & malformasi kongenital", "sk": [594, 595, 596, 597], "goal": "Menilai adaptasi bayi baru lahir, menemukan kelainan kongenital, dan menentukan kebutuhan resusitasi.", "tools": ["Stetoskop", "Termometer", "Timbangan bayi", "Metlin", "Senter", "Jam"], "prep": ["Ruang hangat, tangan hangat, bayi telanjang di bawah pemancar panas"], "steps": [["Penilaian awal (segera)", "Cukup bulan? Bernapas/menangis? Tonus baik? Bila tidak → langkah awal resusitasi (hangatkan, posisi, isap bila perlu, keringkan, rangsang)."], ["Skor Apgar menit 1 & 5", "Appearance (warna: 0 biru/pucat, 1 tubuh merah ekstremitas biru, 2 merah seluruh), Pulse (0 tidak ada, 1 < 100, 2 ≥ 100), Grimace (refleks: 0 tidak ada, 1 meringis, 2 menangis/bersin), Activity (tonus: 0 lemas, 1 sedikit fleksi, 2 aktif), Respiration (0 tidak ada, 1 lemah/tidak teratur, 2 menangis kuat). Ulangi tiap 5 menit bila < 7."], ["Keadaan umum", "Gerakan, perilaku, tangisan (kuat/lemah/melengking), warna (ikterik, pletorik, pucat), postur fleksi."], ["Antropometri", "BB (BBLR < 2500 g), PB, LK (normal ±33–35 cm), LD."], ["Head-to-toe", "Kepala (kaput, sefalhematoma, UUB), mata (red reflex, sekret), telinga (letak rendah), hidung, mulut (labiopalatoskizis — raba palatum), leher, dada, jantung (murmur, nadi femoral), abdomen (massa, tali pusat 2A1V), genital (testis turun, hipospadia, ambigus), anus (paten), tulang belakang (spina bifida, lesung sakral), ekstremitas (polidaktili, CTEV, DDH Ortolani-Barlow)."], ["Tanda dismorfik", "Fisura palpebra miring ke atas, garis simian, sandal gap (sindrom Down); mikrognatia, dll."]], "normal": ["Apgar ≥ 7, menangis kuat, aktif, warna merah, BB 2500–4000 g, LK 33–35 cm, tidak ada kelainan kongenital, anus paten."], "abn": [["Apgar 4–6", "Asfiksia sedang — ventilasi"], ["Apgar 0–3", "Asfiksia berat — resusitasi lengkap"], ["Tangisan melengking + kejang", "Gangguan SSP (perdarahan, meningitis, kernikterus)"], ["Anus tidak paten", "Atresia ani — puasakan, rujuk bedah anak"], ["Celah bibir/langit-langit", "Labiopalatoskizis — edukasi menyusui khusus, rujuk"], ["Nadi femoral lemah/tidak teraba", "Koarktasio aorta"], ["Fitur dismorfik khas (fisura miring, garis simian, hipotonia)", "Sindrom Down — skrining jantung & tiroid"], ["Benjolan di lumbosakral/lesung dalam berambut", "Defek tabung saraf (spina bifida)"]], "doc": "Bayi laki-laki lahir spontan, cukup bulan, Apgar 8/9. BB 3.100 g, PB 49 cm, LK 34 cm. KU aktif, menangis kuat, merah. Kelainan kongenital (−), anus (+).", "key": ["Komponen Apgar dan waktunya", "Pemeriksaan head-to-toe termasuk palatum dan anus", "Kenali kebutuhan resusitasi"], "tips": [], "dz": ["sumbing", "atresia-ani"]},
	{"id": "refleks-bayi", "g": "anak", "name": "Refleks primitif bayi (Moro, rooting, menghisap, menggenggam, melangkah, ATNR, suspensi vertikal)", "sk": [53, 54, 599, 600, 601, 602], "goal": "Menilai integritas sistem saraf bayi melalui refleks primitif sesuai usia.", "tools": [], "prep": ["Bayi tenang, tidak lapar, ruangan hangat"], "steps": [["Moro", "Bayi terlentang, angkat kepala sedikit lalu biarkan jatuh ±30° ke tangan pemeriksa (atau kejutkan dengan menepuk kasur). Respons: abduksi-ekstensi lengan, jari membuka, lalu adduksi seperti memeluk ± menangis. Ada sejak lahir, hilang 4–6 bulan."], ["Rooting & menghisap", "Gores pipi/sudut mulut — kepala menoleh dan mulut membuka; jari bersih di mulut — menghisap kuat dan berirama. Hilang 3–4 bulan (rooting)."], ["Menggenggam palmar & plantar", "Tekan telapak tangan — jari menggenggam (hilang 3–6 bulan); tekan telapak kaki di pangkal jari — jari menekuk (hilang 9–12 bulan)."], ["Melangkah (stepping)", "Pegang bayi tegak di ketiak, telapak kaki menyentuh permukaan — gerakan melangkah. Hilang ±2 bulan."], ["ATNR (asymmetric tonic neck reflex)", "Terlentang, putar kepala ke satu sisi — lengan & tungkai sisi wajah ekstensi, sisi oksiput fleksi (\"posisi anggar\"). Muncul 2 minggu, hilang 6 bulan."], ["Suspensi vertikal", "Angkat bayi di ketiak tegak tanpa kaki menyentuh — kepala tegak sebentar, tungkai fleksi. Tungkai ekstensi kaku bersilang (scissoring) = spastisitas."], ["Suspensi ventral (Landau)", "Bayi ditelungkupkan di telapak tangan — kepala sejajar/naik, punggung lurus (bukan seperti kain lemas/inverted U)."]], "normal": ["Refleks ada simetris sesuai usia dan menghilang pada waktunya."], "abn": [["Moro asimetris", "Fraktur klavikula, palsi pleksus brakialis (Erb), hemiparesis"], ["Moro tidak ada pada neonatus", "Gangguan SSP berat (asfiksia, perdarahan, infeksi)"], ["Refleks primitif menetap melewati usianya (mis. ATNR > 6 bulan)", "Palsi serebral/gangguan perkembangan"], ["Menghisap lemah", "Prematur, sepsis, gangguan neurologis"], ["Scissoring pada suspensi vertikal", "Spastisitas (palsi serebral)"], ["Hipotonia (inverted U pada suspensi ventral)", "Sindrom Down, hipotiroid, SMA, sepsis"]], "doc": "Refleks primitif: Moro (+) simetris, rooting (+), menghisap (+) kuat, grasp palmar (+/+), stepping (+), ATNR (+). Tonus normal.", "key": ["Interpretasi sesuai usia", "Bandingkan kanan-kiri (Moro)", "Waktu menghilangnya refleks"], "tips": [], "dz": ["cerebral-palsy"]},
	{"id": "tumbuh-kembang", "g": "anak", "name": "Penilaian pertumbuhan & perkembangan anak (KPSP, Denver)", "sk": [603], "goal": "Menilai perkembangan motorik kasar, halus, bahasa, dan personal-sosial serta mendeteksi keterlambatan.", "tools": ["Buku KIA/KMS", "KPSP sesuai usia", "Lembar Denver II", "Kit (kubus, pensil, bola, kerincingan)"], "prep": [], "steps": [["Hitung usia", "Usia kronologis; koreksi untuk prematur sampai 2 tahun (usia − minggu prematuritas)."], ["KPSP (Kuesioner Pra Skrining Perkembangan)", "9–10 pertanyaan sesuai usia (3, 6, 9, 12, 15, 18, 21, 24, 30, 36, … bulan). Jawaban \"ya\" 9–10 sesuai, 7–8 meragukan, ≤ 6 penyimpangan."], ["Denver II", "Tarik garis usia; uji item yang dipotong garis usia di 4 sektor; nilai pass/fail/refusal; tentukan caution (gagal item 75–90%) dan delayed (gagal item yang sudah dilewati 90% anak)."], ["Tonggak penting", "3 bln mengangkat kepala 45°; 6 bln duduk dengan bantuan, meraih benda; 9 bln duduk sendiri, merangkak, \"mama-papa\" nonspesifik; 12 bln berdiri/berjalan dipegang, 1–2 kata bermakna, menjimpit; 18 bln berjalan sendiri, menunjuk; 24 bln berlari, kalimat 2 kata."], ["Tes daya dengar (TDD) & daya lihat (TDL), KMME (masalah perilaku), M-CHAT (autisme 18–36 bln), GPPH", "Sesuai jadwal SDIDTK."], ["Red flags", "Tidak tersenyum sosial 3 bln, tidak duduk 9 bln, tidak berjalan 18 bln, tidak ada kata 16 bln, kehilangan kemampuan yang sudah ada (regresi) kapan pun."]], "normal": ["KPSP 9–10 (sesuai usia)", "Denver: tidak ada delayed, ≤ 1 caution."], "abn": [["KPSP 7–8", "Meragukan — stimulasi & ulang 2 minggu"], ["KPSP ≤ 6", "Kemungkinan penyimpangan — rujuk tumbuh kembang"], ["Keterlambatan global ≥ 2 sektor", "Global developmental delay (CP, sindrom genetik, hipotiroid, gizi buruk)"], ["Keterlambatan bahasa + sosial, kontak mata buruk, perilaku berulang", "Curiga gangguan spektrum autisme (M-CHAT)"], ["Regresi perkembangan", "Selalu rujuk (penyakit neurodegeneratif, epilepsi, autisme)"]], "doc": "Usia 12 bulan. KPSP 10/10 (sesuai). Motorik kasar: berdiri dipegang; motorik halus: menjimpit; bahasa: 2 kata bermakna; sosial: melambai. Kesan: perkembangan sesuai usia.", "key": ["Koreksi usia prematur", "Interpretasi KPSP", "Kenali red flags"], "tips": [], "dz": ["gangguan-perkembangan-campuran", "cerebral-palsy", "autisme"]},
	{"id": "antropometri-anak", "g": "anak", "name": "Antropometri anak & status gizi (kurva WHO)", "sk": [604, 486], "goal": "Mengukur BB, PB/TB, LK, LiLA dan menentukan status gizi dengan kurva WHO.", "tools": ["Timbangan bayi/digital", "Infantometer (PB, < 2 tahun) & mikrotoa (TB, ≥ 2 tahun)", "Metlin", "Pita LiLA", "Kurva WHO 2006 (0–5 th) & CDC/WHO 2007 (5–18 th)"], "prep": [], "steps": [["Berat badan", "Bayi telanjang/popok kering; anak pakaian minimal; timbangan dikalibrasi 0."], ["Panjang/tinggi badan", "< 2 tahun berbaring dengan infantometer (2 orang: kepala menempel papan kepala, lutut ditekan lurus, telapak kaki tegak); ≥ 2 tahun berdiri (TB = PB − 0,7 cm)."], ["Lingkar kepala", "Pita melingkari oksiput-glabela (lingkar terbesar); sampai usia 2–3 tahun."], ["LiLA", "Pertengahan akromion-olekranon lengan kiri; 6–59 bulan < 11,5 cm = gizi buruk, 11,5–12,5 gizi kurang."], ["Plot di kurva", "BB/U, PB-TB/U, BB/PB-TB, IMT/U, LK/U; tentukan Z-score."], ["Interpretasi Z-score", "BB/PB-TB: < −3 SD gizi buruk (severely wasted), −3 s.d. < −2 gizi kurang (wasted), −2 s.d. +1 normal, > +1 berisiko gizi lebih, > +2 gizi lebih, > +3 obesitas. TB/U < −2 pendek (stunted), < −3 sangat pendek. BB/U < −2 berat badan kurang."], ["Edema & tanda klinis", "Edema bilateral pitting dorsum pedis (kwashiorkor) = gizi buruk apa pun Z-score-nya; baggy pants, iga gambang (marasmus)."]], "normal": ["Semua indeks antara −2 SD dan +1 SD", "LK normal untuk usia."], "abn": [["BB/PB < −3 SD, LiLA < 11,5 cm, atau edema bilateral", "Gizi buruk — tata laksana 10 langkah, rujuk bila komplikasi"], ["TB/U < −2 SD", "Stunting — evaluasi asupan, infeksi berulang, stimulasi"], ["IMT/U > +2 SD (5–18 th)", "Obesitas anak"], ["LK < −2 SD", "Mikrosefali (infeksi kongenital, kraniosinostosis, genetik)"], ["LK > +2 SD atau naik melintasi garis persentil", "Makrosefali/hidrosefalus"], ["Kurva BB mendatar/turun pada 2 pengukuran", "Gagal tumbuh (weight faltering)"]], "doc": "Anak P, 24 bulan. BB 11,5 kg, TB 86 cm, LK 47 cm, LiLA 14 cm. BB/U 0 s.d. −1 SD, TB/U −1 SD, BB/TB 0 SD, LK normal. Kesan: gizi baik, perawakan normal.", "key": ["PB berbaring < 2 tahun", "Pakai indikator dan kurva yang sesuai usia/jenis kelamin", "Edema bilateral = gizi buruk"], "tips": [], "dz": ["malnutrisi", "stunting", "obesitas-anak"]},
	{"id": "luar-jenazah", "g": "forensik", "name": "Pemeriksaan luar jenazah, properti & lubang-lubang tubuh", "sk": [712, 713, 718], "goal": "Melakukan pemeriksaan luar jenazah secara sistematis untuk identifikasi, perkiraan waktu dan sebab kematian, sesuai permintaan penyidik (SPV).", "tools": ["Formulir pemeriksaan luar", "Kamera & skala", "Pita ukur", "Senter", "Sarung tangan, masker, APD", "Kantong barang bukti", "Termometer rektal"], "prep": ["Pastikan ada surat permintaan visum (SPV) dari penyidik", "label jenazah sesuai", "dokumentasi foto sebelum disentuh"], "steps": [["Label & pembungkus", "Label (isi, segel, materai), bahan pembungkus jenazah — catat dan foto."], ["Properti (pakaian & perhiasan)", "Urutan dari luar ke dalam: jenis, bahan, warna, merek, ukuran, kerusakan (robekan, lubang, bercak darah/lumpur); isi saku; perhiasan; simpan sebagai barang bukti."], ["Identitas umum", "Jenis kelamin, perkiraan umur, ras, panjang badan, berat/gizi, warna kulit, rambut (warna, panjang, distribusi), tato, jaringan parut, tahi lalat, cacat, sirkumsisi."], ["Tanda kematian", "Lebam mayat, kaku mayat, penurunan suhu (catat suhu rektal & lingkungan), pembusukan."], ["Lubang-lubang tubuh", "Mata (kornea, konjungtiva — perdarahan bintik), hidung, mulut (gigi, lidah, benda asing), telinga, kemaluan, dubur — keluar cairan/darah/busa/feses/sperma, benda asing."], ["Luka & patah tulang", "Deskripsikan tiap luka (lihat materi deskripsi luka), palpasi tulang."], ["Dokumentasi", "Foto keseluruhan & close-up dengan skala; tulis temuan objektif tanpa menyimpulkan sebab kematian pada bagian pemberitaan."]], "normal": ["Tidak ditemukan luka/tanda kekerasan", "tanda kematian pasti sesuai perkiraan waktu."], "abn": [["Busa halus putih dari mulut-hidung", "Tenggelam (juga edema paru)"], ["Darah dari telinga/hidung + hematoma kacamata (brill hematoma)", "Fraktur basis kranii"], ["Cairan/benda asing di vagina/anus", "Kemungkinan kekerasan seksual — ambil swab"], ["Pakaian robek/berlubang sesuai luka", "Kekerasan (tusukan/tembakan) — cocokkan lokasi"]], "doc": "Jenazah terbungkus kantong jenazah warna oranye, berlabel … Pakaian: kaos merah merek …, robek di dada kiri 2 cm … Identitas: laki-laki, ±40 tahun, PB 168 cm … Lubang tubuh: keluar busa halus putih dari hidung & mulut …", "key": ["SPV sebelum memeriksa", "Urutan properti dari luar ke dalam", "Deskripsi objektif tanpa interpretasi"], "tips": ["Pemeriksaan luar saja tidak dapat menentukan sebab kematian pasti — sampaikan perlunya autopsi kepada penyidik"], "dz": ["tenggelam"]},
	{"id": "lebam-kaku", "g": "forensik", "name": "Lebam mayat, kaku mayat & perkiraan waktu kematian", "sk": [714, 715], "goal": "Menilai tanda kematian lanjut untuk memperkirakan saat kematian dan posisi jenazah setelah meninggal.", "tools": ["Termometer rektal", "Jam", "Kamera"], "prep": [], "steps": [["Lebam mayat (livor mortis)", "Lokasi (bagian terendah, kecuali yang tertekan — pucat), warna (merah keunguan normal; merah terang/cherry red pada keracunan CO/sianida/hipotermia; coklat pada methemoglobinemia)."], ["Tekan lebam", "Tekan dengan jari ±30 detik; hilang (belum menetap, < 6–8 jam) atau tidak hilang (menetap, > 8–12 jam)."], ["Kaku mayat (rigor mortis)", "Coba gerakkan sendi kecil (rahang, jari) lalu besar (siku, lutut). Mulai 2–4 jam, lengkap 6–12 jam, menetap 12–24 jam, menghilang 24–36 jam (urutan sama seperti mulai)."], ["Suhu", "Suhu rektal & lingkungan; penurunan ±0,5–1 °C/jam (dipengaruhi lingkungan, pakaian, BMI)."], ["Pembusukan", "Warna hijau di perut kanan bawah (24–48 jam), marbling, gelembung/bula, gas (> 36–72 jam), belatung."], ["Kadaverik spasme", "Kekakuan seketika (benda tergenggam erat) — menunjukkan posisi saat meninggal."]], "normal": ["Lebam di bagian terendah, merah keunguan", "kaku mayat sesuai perkiraan waktu."], "abn": [["Lebam tidak sesuai posisi ditemukan", "Jenazah telah dipindahkan setelah lebam menetap"], ["Lebam merah terang (cherry red)", "Keracunan CO, sianida, hipotermia"], ["Lebam tidak ada/minimal", "Perdarahan masif (kehilangan darah)"], ["Kaku mayat timbul cepat", "Aktivitas fisik berat sebelum meninggal, demam, lingkungan panas"]], "doc": "Lebam mayat di punggung, bokong, tungkai belakang, merah keunguan, tidak hilang dengan penekanan. Kaku mayat lengkap di seluruh sendi, sukar dilawan. Suhu rektal 30 °C (ruangan 27 °C). Kesan: kematian ±12–24 jam sebelum pemeriksaan.", "key": ["Tekan lebam untuk menilai menetap", "Kaku mayat dari sendi kecil ke besar", "Perkiraan waktu dalam rentang, bukan angka pasti"], "tips": [], "dz": ["tenggelam"]},
	{"id": "asfiksia-tenggelam", "g": "forensik", "name": "Tanda asfiksia & tanda tenggelam", "sk": [716, 721], "goal": "Mengenali tanda-tanda asfiksia mekanik dan tenggelam pada pemeriksaan luar.", "tools": ["Kamera", "Pita ukur", "Senter", "Kaca pembesar"], "prep": [], "steps": [["Tanda asfiksia umum (tidak spesifik)", "Sianosis wajah/ujung jari, bendungan wajah, perdarahan berbintik (petekie/Tardieu spot) di konjungtiva, kelopak, wajah; lebam gelap; busa halus."], ["Jerat (gantung/cekik tali)", "Jejas jerat — lokasi, arah (miring ke atas pada gantung, horizontal pada jerat), lebar, pola anyaman, simpul; luka lecet tekan."], ["Pencekikan manual", "Luka lecet berbentuk bulan sabit (kuku) & memar bulat (ujung jari) di leher."], ["Pembekapan/sumbatan", "Luka lecet/memar di sekitar mulut-hidung, bagian dalam bibir; benda asing di jalan napas."], ["Tanda tenggelam", "Busa halus sukar pecah di mulut-hidung (champignon d'écume), kulit telapak keriput putih (washer woman's hand — menunjukkan lama di air, bukan tenggelam), cutis anserina, benda asing (lumpur, pasir, tumbuhan) di tangan/saluran napas."], ["Bedakan masuk air hidup/mati", "Busa & benda asing di saluran napas dalam serta tes diatom (autopsi) menunjukkan korban masih hidup saat tenggelam."]], "normal": ["Tidak ditemukan tanda asfiksia maupun jejas di leher."], "abn": [["Jejas jerat miring ke atas, tidak melingkar penuh, simpul di belakang telinga", "Gantung (hanging)"], ["Jejas jerat horizontal melingkar penuh di bawah tiroid", "Jerat (strangulasi) — curiga pembunuhan"], ["Memar bulat & lecet bulan sabit di leher", "Pencekikan manual — pembunuhan"], ["Busa halus mulut-hidung + benda asing di genggaman", "Tenggelam saat masih hidup"], ["Washer woman's hand tanpa busa", "Lama di air (tidak memastikan tenggelam)"]], "doc": "Wajah sembab kebiruan, perdarahan berbintik di konjungtiva kanan-kiri. Leher: jejas jerat berbentuk alur, lebar 1 cm, melingkar miring ke atas belakang, terputus di belakang telinga kanan, dasar luka lecet tekan kecoklatan.", "key": ["Deskripsi jejas jerat lengkap (arah, lebar, pola, lokasi simpul)", "Tanda asfiksia tidak spesifik — perlu korelasi"], "tips": [], "dz": ["tenggelam"]},
	{"id": "gigi-jenazah", "g": "forensik", "name": "Pemeriksaan gigi jenazah (odontogram)", "sk": [717], "goal": "Mencatat gigi geligi untuk identifikasi dan perkiraan usia.", "tools": ["Formulir odontogram (sistem FDI)", "Senter", "Kaca mulut", "Kamera"], "prep": [], "steps": [["Buka mulut", "Bila kaku mayat, lemaskan dengan hati-hati atau tunggu; jangan merusak."], ["Catat tiap gigi (FDI)", "Kuadran 1–4 (dewasa) / 5–8 (gigi susu): ada/hilang (antemortem — soket menutup; postmortem — soket terbuka), karies, tambalan (bahan & permukaan), mahkota, jembatan, gigi tiruan, kelainan posisi."], ["Ciri khusus", "Diastema, gigi berlubang khas, warna (tetrasiklin), atrisi (keausan), kelainan bentuk."], ["Perkiraan usia", "Pola erupsi gigi susu/tetap (anak), molar 3 (dewasa muda), atrisi dan kehilangan gigi (lansia)."], ["Bandingkan dengan data antemortem", "Rekam medis gigi/ronsen dari dokter gigi keluarga."]], "normal": ["Gigi geligi lengkap tercatat pada odontogram."], "abn": [["Tambalan/protesa khas", "Data identifikasi primer (dibandingkan dengan rekam gigi antemortem)"], ["Gigi patah segar dengan luka bibir", "Kekerasan tumpul pada mulut"]], "doc": "Odontogram: 18 hilang antemortem; 16 tambalan amalgam oklusal; 11–21 diastema; 36 karies profunda; 38 belum erupsi. Kesan: dewasa muda ±20–25 tahun.", "key": ["Gunakan sistem FDI", "Bedakan kehilangan antemortem vs postmortem"], "tips": ["Gigi adalah identifikasi primer (bersama sidik jari dan DNA) menurut DVI Interpol"], "dz": []},
	{"id": "deskripsi-luka", "g": "forensik", "name": "Pemeriksaan korban trauma: deskripsi luka, derajat luka & patah tulang", "sk": [710, 711, 719, 720], "goal": "Mendeskripsikan luka secara objektif dan lengkap serta menentukan kualifikasi luka untuk visum korban hidup.", "tools": ["Pita ukur/penggaris", "Kamera dengan skala", "Lup", "Formulir & diagram tubuh"], "prep": [], "steps": [["Lokasi", "Regio anatomis, koordinat dari garis tengah tubuh/titik anatomis tetap (mis. 5 cm kanan garis tengah, 3 cm di bawah puting)."], ["Jenis luka", "Memar (warna menunjukkan umur kasar), luka lecet (geser/tekan), luka robek (tepi tidak rata, jembatan jaringan — tumpul), luka iris (tepi rata, panjang > dalam), luka tusuk (dalam > panjang), luka bacok, luka tembak (masuk: kelim lecet/jelaga/tato; keluar: lebih besar tidak beraturan), luka bakar, luka listrik."], ["Karakter", "Jumlah, bentuk, ukuran (panjang × lebar × dalam), tepi (rata/tidak, lecet), sudut (tajam/tumpul), dasar (jaringan apa), sekitar (memar, jelaga), jembatan jaringan, perdarahan aktif."], ["Patah tulang", "Deformitas, krepitasi, gerak abnormal, nyeri sumbu; foto rontgen untuk konfirmasi."], ["Derajat luka (Pasal KUHP)", "Luka ringan/derajat 1 (tidak menimbulkan penyakit/halangan pekerjaan — Pasal 352); luka sedang/derajat 2 (menimbulkan penyakit/halangan sementara — Pasal 351 ayat 1); luka berat/derajat 3 (memenuhi Pasal 90 KUHP: tidak dapat sembuh sempurna, bahaya maut, kehilangan indra, cacat, lumpuh, gugurnya kandungan, dll)."], ["Dokumentasi", "Foto dengan skala, diagram tubuh, waktu pemeriksaan; jangan mengubah luka sebelum didokumentasi."]], "normal": ["Tidak ditemukan luka."], "abn": [["Luka tepi rata, sudut lancip, tanpa jembatan jaringan", "Kekerasan tajam"], ["Luka tepi tidak rata, jembatan jaringan, memar sekitar", "Kekerasan tumpul"], ["Luka di telapak/lengan bawah sisi ulnar pada korban tusukan", "Luka tangkisan (defensive wound)"], ["Luka iris sejajar dangkal multipel di pergelangan (luka percobaan)", "Pola bunuh diri"], ["Memar berbagai warna/usia pada anak + cerita tidak sesuai", "Curiga kekerasan anak — laporkan"]], "doc": "Pada dada kiri, 4 cm kiri garis tengah, 6 cm di bawah puting, terdapat luka terbuka berbentuk celah, ukuran 2,5 × 0,5 cm, tepi rata, satu sudut lancip satu tumpul, dasar jaringan otot, jembatan jaringan (−). Kesimpulan: luka akibat kekerasan tajam, derajat … (luka berat sesuai Pasal 90 KUHP bila menimbulkan bahaya maut).", "key": ["Lokasi dengan koordinat titik anatomis tetap", "Deskripsi lengkap tanpa menyebut alat secara spesifik", "Kualifikasi luka sesuai KUHP"], "tips": [], "dz": ["forensik-luka"]},
	{"id": "anogenital", "g": "forensik", "name": "Pemeriksaan selaput dara & anogenital korban dugaan kekerasan seksual", "sk": [708, 709], "goal": "Memeriksa dan mendokumentasikan temuan anogenital serta mengambil bukti biologis pada korban kekerasan seksual secara berperspektif korban.", "tools": ["Kamera dengan skala", "Lampu sorot", "Lidi kapas steril & kaca objek", "Spekulum (dewasa, bila perlu)", "Kit bukti (amplop kertas, label)", "Kateter Foley kecil (teknik balon pada remaja/dewasa)", "Formulir khusus"], "prep": ["Informed consent tertulis korban (wali bila anak)", "SPV penyidik bila ada", "pendamping perempuan", "stabilisasi medis & psikologis didahulukan", "jelaskan setiap langkah dan hak korban untuk menghentikan"], "steps": [["Anamnesis terarah", "Waktu kejadian, jenis kontak, penetrasi, ejakulasi, kondom, mandi/ganti baju/buang air sesudahnya, riwayat haid & hubungan seksual sebelumnya (hanya yang relevan)."], ["Pemeriksaan umum", "Luka di tubuh (leher, payudara, paha dalam, pergelangan) — deskripsi luka."], ["Genital luar", "Posisi frog-leg (anak) atau litotomi; inspeksi labia, fourchette posterior, fossa navikularis, vestibulum: memar, lecet, robekan, perdarahan, sekret."], ["Selaput dara", "Bentuk (anular, semilunar, fimbriata, septata), tepi, robekan (lokasi arah jam; sampai dasar/tidak sampai dasar; baru — tepi merah, berdarah, bengkak; lama — tepi tumpul tidak berdarah). Teknik balon kateter Foley untuk melihat tepi selaput pada remaja/dewasa."], ["Anus", "Posisi lutut-dada/lateral: lecet, robekan (fisura), memar, dilatasi refleks."], ["Pengambilan bukti", "Swab forniks posterior/vagina, anus, mulut sesuai riwayat (sperma/PSA/DNA), kerokan kuku, rambut pubis, pakaian; keringkan & simpan amplop kertas; rantai bukti (chain of custody)."], ["Tata laksana", "Kontrasepsi darurat (< 120 jam), profilaksis IMS & PEP HIV (< 72 jam), vaksin hepatitis B, dukungan psikologis, rujuk/koordinasi UPTD PPA."]], "normal": ["Tidak ditemukan luka", "selaput dara utuh. Catatan: selaput dara utuh TIDAK menyingkirkan penetrasi."], "abn": [["Robekan baru selaput dara sampai dasar + perdarahan", "Penetrasi baru-baru ini"], ["Robekan lama sampai dasar (tepi tumpul)", "Pernah ada penetrasi (waktu tidak dapat dipastikan)"], ["Lecet/robekan fourchette posterior", "Kekerasan/penetrasi akut"], ["Spermatozoa pada swab", "Bukti ejakulasi (berguna hingga 72 jam di vagina)"], ["IMS pada anak praremaja", "Sangat mendukung kekerasan seksual"]], "doc": "Selaput dara bentuk anular, terdapat robekan baru sampai dasar pada arah jam 6, tepi kemerahan, perdarahan aktif minimal. Fourchette posterior: luka lecet 0,5 cm. Anus: tidak ada kelainan. Diambil swab forniks posterior untuk pemeriksaan sperma.", "key": ["Informed consent & pendamping", "Lokasi robekan dengan arah jam dan sampai dasar/tidak", "Rantai bukti & tata laksana pascakekerasan"], "tips": ["Hindari istilah \"perawan/tidak perawan\"", "Utamakan keselamatan dan kesehatan korban"], "dz": ["kejahatan-seksual"]},
	{"id": "visum", "g": "forensik", "name": "Pembuatan Visum et Repertum", "sk": [705], "goal": "Menyusun laporan tertulis hasil pemeriksaan medis atas permintaan penyidik sebagai alat bukti sah (Pasal 184 KUHAP).", "tools": [], "prep": [], "steps": [["Dasar hukum", "Dibuat atas SPV tertulis dari penyidik (Polri) — Pasal 133 KUHAP; dokter wajib memberikan keterangan ahli (Pasal 179 KUHAP)."], ["Struktur", "(1) Pro Justitia (di kiri atas, pengganti materai); (2) Pendahuluan: identitas dokter, penyidik, nomor & tanggal SPV, identitas korban, waktu & tempat pemeriksaan; (3) Pemberitaan/hasil pemeriksaan: temuan objektif lengkap dalam bahasa awam; (4) Kesimpulan: jenis luka/kekerasan, kualifikasi luka (korban hidup) atau sebab kematian (bila autopsi); (5) Penutup: sumpah/janji jabatan dokter, tanda tangan & nama terang."], ["Bahasa", "Indonesia baku tanpa singkatan, istilah awam (luka lecet, memar), angka ditulis dengan huruf bila perlu; hanya fakta yang dilihat."], ["Kerahasiaan & penyerahan", "Hanya diserahkan kepada penyidik peminta; salinan untuk arsip RS."], ["Jenis", "VeR korban hidup (definitif, sementara, lanjutan), VeR jenazah, VeR kejahatan susila, VeR psikiatri."]], "normal": ["VeR lengkap 5 bagian, sesuai SPV, objektif."], "abn": [["VeR dibuat tanpa SPV", "Tidak sah sebagai alat bukti"], ["Kesimpulan menyebut pelaku/alat spesifik", "Melampaui kewenangan dokter — sebut \"akibat kekerasan tumpul/tajam\""]], "doc": "PRO JUSTITIA. VISUM ET REPERTUM No. … Yang bertanda tangan di bawah ini, dr. …, atas permintaan tertulis dari Kepolisian Sektor … No. … tertanggal …, telah melakukan pemeriksaan pada … HASIL PEMERIKSAAN: … KESIMPULAN: Pada korban laki-laki berusia ±30 tahun ini ditemukan luka lecet dan memar akibat kekerasan tumpul. Luka tersebut tidak menimbulkan penyakit atau halangan dalam menjalankan pekerjaan untuk sementara waktu. Demikian visum et repertum ini dibuat dengan sesungguhnya berdasarkan keilmuan saya dan dengan mengingat sumpah sesuai KUHAP.", "key": ["Lima bagian VeR", "Pro Justitia", "Kesimpulan sesuai kualifikasi tanpa menuduh"], "tips": [], "dz": ["forensik-luka"]},
];
